static std::string_view ClassifyDreams7baProvenanceRow(const Dreams7baProvenanceRow& row) {
    if (row.buffer2_post == row.input_key) {
        return row.buffer2_pre == row.input_key ? "accepted_or_preexisting"
                                                : "accepted_transition";
    }
    if (row.buffer2_post == std::numeric_limits<u32>::max()) {
        return row.buffer2_pre == std::numeric_limits<u32>::max()
                   ? "sentinel_or_preexisting"
                   : "sentinel_transition";
    }
    return row.buffer2_post == row.buffer2_pre ? "no_observed_store" : "other_transition";
}

static bool HasDreamsBoundVulkanIdentity(const DreamsBoundBufferIdentity& buffer) {
    return buffer.backing_handle != 0 &&
           static_cast<VkBuffer>(buffer.descriptor.buffer) != VK_NULL_HANDLE &&
           buffer.descriptor.range != VK_WHOLE_SIZE &&
           buffer.logical_base_offset <= buffer.descriptor.range;
}

static u64 DreamsBoundEffectiveOffset(const DreamsBoundBufferIdentity& buffer) {
    return static_cast<u64>(buffer.descriptor.offset) + buffer.logical_base_offset;
}

static u64 DreamsBoundEffectiveRange(const DreamsBoundBufferIdentity& buffer) {
    return static_cast<u64>(buffer.descriptor.range) - buffer.logical_base_offset;
}

static bool SameDreamsBoundBuffer(const DreamsBoundBufferIdentity& producer,
                                  const DreamsBoundBufferIdentity& consumer) {
    if (!producer.valid || !consumer.valid || producer.guest_base != consumer.guest_base ||
        producer.guest_size != consumer.guest_size || producer.stride != consumer.stride) {
        return false;
    }
    const bool producer_has_vk = HasDreamsBoundVulkanIdentity(producer);
    const bool consumer_has_vk = HasDreamsBoundVulkanIdentity(consumer);
    if (producer_has_vk || consumer_has_vk) {
        return producer_has_vk && consumer_has_vk &&
               producer.backing_handle == consumer.backing_handle &&
               DreamsBoundEffectiveOffset(producer) == DreamsBoundEffectiveOffset(consumer) &&
               DreamsBoundEffectiveRange(producer) == DreamsBoundEffectiveRange(consumer);
    }
    return producer.raw_descriptor == consumer.raw_descriptor;
}

static bool Dreams84aaGatherCrossCheck() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_84AA_GATHER_CROSSCHECK");
        return value != nullptr && value[0] == '1' && value[1] == '\0';
    }();
    return enabled;
}

static bool SameDreamsAtlasBacking(const DreamsAtlasImageIdentity& lhs,
                                   const DreamsAtlasImageIdentity& rhs) {
    return lhs.valid && rhs.valid && lhs.image_uid != 0 && lhs.image_id == rhs.image_id &&
           lhs.image_uid == rhs.image_uid && lhs.backing_handle != 0 &&
           lhs.backing_handle == rhs.backing_handle && lhs.guest_base == rhs.guest_base &&
           lhs.guest_size == rhs.guest_size;
}

static bool SameDreamsAtlasView(const DreamsAtlasImageIdentity& lhs,
                                const DreamsAtlasImageIdentity& rhs) {
    return SameDreamsAtlasBacking(lhs, rhs) && lhs.descriptor_base == rhs.descriptor_base &&
           lhs.descriptor_width == rhs.descriptor_width &&
           lhs.descriptor_height == rhs.descriptor_height &&
           lhs.descriptor_depth == rhs.descriptor_depth &&
           lhs.descriptor_pitch == rhs.descriptor_pitch && lhs.cached_width == rhs.cached_width &&
           lhs.cached_height == rhs.cached_height && lhs.cached_depth == rhs.cached_depth &&
           lhs.cached_pitch == rhs.cached_pitch && lhs.view_type == rhs.view_type &&
           lhs.view_format == rhs.view_format && lhs.base_level == rhs.base_level &&
           lhs.levels == rhs.levels && lhs.base_layer == rhs.base_layer &&
           lhs.layers == rhs.layers && lhs.view_mapping == rhs.view_mapping;
}

static bool SameDreamsAtlasByteCoordinates(const DreamsAtlasImageIdentity& producer,
                                           const DreamsAtlasImageIdentity& consumer) {
    return SameDreamsAtlasBacking(producer, consumer) &&
           producer.descriptor_base == consumer.descriptor_base &&
           producer.descriptor_width == consumer.descriptor_width &&
           producer.descriptor_height == consumer.descriptor_height &&
           producer.descriptor_depth == consumer.descriptor_depth &&
           producer.descriptor_pitch == consumer.descriptor_pitch &&
           producer.cached_width == consumer.cached_width &&
           producer.cached_height == consumer.cached_height &&
           producer.cached_depth == consumer.cached_depth &&
           producer.cached_pitch == consumer.cached_pitch &&
           producer.view_type == consumer.view_type && producer.base_level == consumer.base_level &&
           producer.levels == consumer.levels && producer.base_layer == consumer.base_layer &&
           producer.layers == consumer.layers &&
           producer.view_format == static_cast<u32>(vk::Format::eR8Uint) &&
           consumer.view_format == static_cast<u32>(vk::Format::eR8Unorm);
}

static bool OverlapDreamsAtlasGuestRange(const DreamsAtlasImageIdentity& lhs,
                                         const DreamsAtlasImageIdentity& rhs) {
    return lhs.valid && rhs.valid && lhs.guest_size != 0 && rhs.guest_size != 0 &&
           lhs.guest_base < rhs.guest_base + rhs.guest_size &&
           rhs.guest_base < lhs.guest_base + lhs.guest_size;
}

static bool RelatedDreamsAtlasImage(const DreamsAtlasImageIdentity& producer,
                                    const DreamsAtlasImageIdentity& consumer) {
    if (!producer.valid || !consumer.valid) {
        return false;
    }
    if (producer.backing_handle != 0 || consumer.backing_handle != 0) {
        return SameDreamsAtlasView(producer, consumer) ||
               SameDreamsAtlasByteCoordinates(producer, consumer);
    }
    return producer.raw_descriptor == consumer.raw_descriptor &&
           producer.descriptor_base == consumer.descriptor_base &&
           OverlapDreamsAtlasGuestRange(producer, consumer);
}

static std::optional<u64> PackDreamsAtlasBrick(s32 x, s32 y, s32 z) {
    constexpr u32 CoordinateBits = 21;
    constexpr u32 CoordinateLimit = 1U << CoordinateBits;
    if (x < 0 || y < 0 || z < 0 || static_cast<u32>(x) >= CoordinateLimit * 8U ||
        static_cast<u32>(y) >= CoordinateLimit * 8U ||
        static_cast<u32>(z) >= CoordinateLimit * 8U) {
        return std::nullopt;
    }
    const u64 brick_x = static_cast<u32>(x) >> 3;
    const u64 brick_y = static_cast<u32>(y) >> 3;
    const u64 brick_z = static_cast<u32>(z) >> 3;
    return brick_x | (brick_y << CoordinateBits) | (brick_z << (CoordinateBits * 2));
}

struct DreamsAtlasGatherCrossCheckResult {
    bool seen{};
    u32 matched{};
    u32 mismatched{};
    u32 unknown{};

    bool Compared() const {
        return matched + mismatched != 0;
    }
};
