static u64 ResolveGuestBufferBindingSize(Core::MemoryManager* memory, const Shader::Info& stage,
                                         u32 buffer_index, const Shader::BufferResource& desc,
                                         const AmdGpu::Buffer& sharp) {
    u64 size = memory->ClampRangeSize(sharp.base_address, sharp.GetSize());
    if (sharp.stride != 0 || sharp.num_records != std::numeric_limits<u32>::max()) {
        return size;
    }

    if (Common::ElfInfo::Instance().GameSerial() == "CUSA04301") {
        const u64 reachable =
            Shader::DreamsCompat::ExactUnboundedBufferReachableBytes(stage.pgm_hash, buffer_index);
        if (reachable != 0 && stage.l_stage == Shader::LogicalStage::Compute && !desc.IsSpecial() &&
            !desc.is_written && !desc.is_formatted) {
            return std::min(size, reachable);
        }
    }
    // Preserve the existing bounded fallback for every unaudited shader. Returning the full
    // mapped range here can ask Vulkan for a multi-gigabyte buffer; only replace this fallback
    // when another shader has either a proven access range or a faithful paged implementation.
    return std::min(size, LegacyMaxUnboundedGuestBufferWindow);
}

// Read the bytes from the exact Vulkan buffer object that the shader is bound to consume. This is
// intentionally different from resolving the guest address through BufferCache again: a read-only
// binding may have been copied to the stream buffer, and that distinction is precisely what the
// ordered-chain diagnostic needs to preserve.
static bool ReadDreamsBoundBufferForCapture(Vulkan::Scheduler& scheduler,
                                            VideoCore::BufferCache& buffer_cache,
                                            const vk::DescriptorBufferInfo& source,
                                            u64 relative_offset, std::span<u8> destination) {
    if (destination.empty()) {
        return true;
    }
    if (static_cast<VkBuffer>(source.buffer) == VK_NULL_HANDLE ||
        destination.size() > std::numeric_limits<u32>::max() ||
        relative_offset > std::numeric_limits<u64>::max() - source.offset) {
        return false;
    }
    if (source.range != VK_WHOLE_SIZE &&
        (relative_offset > source.range || destination.size() > source.range - relative_offset)) {
        return false;
    }

    const u64 source_offset = source.offset + relative_offset;
    const u64 size = destination.size();
    auto& download = buffer_cache.GetUtilityBuffer(VideoCore::MemoryUsage::Download);
    const auto [download_data, download_offset] = download.Map(size, sizeof(u32));
    if (download_data == nullptr) {
        return false;
    }
    download.Commit();

    scheduler.EndRendering();
    const auto cmdbuf = scheduler.CommandBuffer();
    const vk::BufferMemoryBarrier2 source_pre{
        .srcStageMask = vk::PipelineStageFlagBits2::eAllCommands,
        .srcAccessMask = vk::AccessFlagBits2::eMemoryWrite,
        .dstStageMask = vk::PipelineStageFlagBits2::eTransfer,
        .dstAccessMask = vk::AccessFlagBits2::eTransferRead,
        .buffer = source.buffer,
        .offset = source_offset,
        .size = size,
    };
    cmdbuf.pipelineBarrier2(vk::DependencyInfo{
        .dependencyFlags = vk::DependencyFlagBits::eByRegion,
        .bufferMemoryBarrierCount = 1,
        .pBufferMemoryBarriers = &source_pre,
    });
    cmdbuf.copyBuffer(source.buffer, download.Handle(), vk::BufferCopy{
                                                              .srcOffset = source_offset,
                                                              .dstOffset = download_offset,
                                                              .size = size,
                                                          });
    const std::array<vk::BufferMemoryBarrier2, 2> post_barriers{{
        {
            .srcStageMask = vk::PipelineStageFlagBits2::eTransfer,
            .srcAccessMask = vk::AccessFlagBits2::eTransferRead,
            .dstStageMask = vk::PipelineStageFlagBits2::eAllCommands,
            .dstAccessMask =
                vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite,
            .buffer = source.buffer,
            .offset = source_offset,
            .size = size,
        },
        {
            .srcStageMask = vk::PipelineStageFlagBits2::eTransfer,
            .srcAccessMask = vk::AccessFlagBits2::eTransferWrite,
            .dstStageMask = vk::PipelineStageFlagBits2::eHost,
            .dstAccessMask = vk::AccessFlagBits2::eHostRead,
            .buffer = download.Handle(),
            .offset = download_offset,
            .size = size,
        },
    }};
    cmdbuf.pipelineBarrier2(vk::DependencyInfo{
        .dependencyFlags = vk::DependencyFlagBits::eByRegion,
        .bufferMemoryBarrierCount = static_cast<u32>(post_barriers.size()),
        .pBufferMemoryBarriers = post_barriers.data(),
    });
    scheduler.Finish();
    download.InvalidateMappedRange(download_offset, size);
    std::memcpy(destination.data(), download_data, size);
    return true;
}

struct DreamsBoundBufferCaptureRegion {
    vk::DescriptorBufferInfo source;
    u64 relative_offset{};
    std::span<u8> destination;
};

// Capture many sparse records with one submission/fence. This keeps the provenance probe out of
// the guest shader while still reading the exact VkBuffer objects and offsets bound to it.
static bool ReadDreamsBoundBufferRegionsForCapture(
    Vulkan::Scheduler& scheduler, VideoCore::BufferCache& buffer_cache,
    std::span<const DreamsBoundBufferCaptureRegion> regions) {
    if (regions.empty()) {
        return true;
    }

    std::vector<u64> download_offsets;
    download_offsets.reserve(regions.size());
    u64 download_size{};
    for (const auto& region : regions) {
        if (region.destination.empty()) {
            download_offsets.push_back(download_size);
            continue;
        }
        if (static_cast<VkBuffer>(region.source.buffer) == VK_NULL_HANDLE ||
            region.relative_offset > std::numeric_limits<u64>::max() - region.source.offset ||
            (region.source.range != VK_WHOLE_SIZE &&
             (region.relative_offset > region.source.range ||
              region.destination.size() > region.source.range - region.relative_offset))) {
            return false;
        }
        download_size = (download_size + 3) & ~u64{3};
        download_offsets.push_back(download_size);
        if (region.destination.size() > std::numeric_limits<u64>::max() - download_size) {
            return false;
        }
        download_size += region.destination.size();
    }
    if (download_size == 0) {
        return true;
    }

    auto& download = buffer_cache.GetUtilityBuffer(VideoCore::MemoryUsage::Download);
    const auto [download_data, download_base] = download.Map(download_size, sizeof(u32));
    if (download_data == nullptr) {
        return false;
    }
    download.Commit();

    std::vector<vk::BufferMemoryBarrier2> source_pre;
    std::vector<vk::BufferMemoryBarrier2> source_post;
    source_pre.reserve(regions.size());
    source_post.reserve(regions.size() + 1);
    for (const auto& region : regions) {
        if (region.destination.empty()) {
            continue;
        }
        const u64 source_offset = region.source.offset + region.relative_offset;
        const u64 size = region.destination.size();
        source_pre.push_back({
            .srcStageMask = vk::PipelineStageFlagBits2::eAllCommands,
            .srcAccessMask = vk::AccessFlagBits2::eMemoryWrite,
            .dstStageMask = vk::PipelineStageFlagBits2::eTransfer,
            .dstAccessMask = vk::AccessFlagBits2::eTransferRead,
            .buffer = region.source.buffer,
            .offset = source_offset,
            .size = size,
        });
        source_post.push_back({
            .srcStageMask = vk::PipelineStageFlagBits2::eTransfer,
            .srcAccessMask = vk::AccessFlagBits2::eTransferRead,
            .dstStageMask = vk::PipelineStageFlagBits2::eAllCommands,
            .dstAccessMask =
                vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite,
            .buffer = region.source.buffer,
            .offset = source_offset,
            .size = size,
        });
    }

    scheduler.EndRendering();
    const auto cmdbuf = scheduler.CommandBuffer();
    cmdbuf.pipelineBarrier2(vk::DependencyInfo{
        .dependencyFlags = vk::DependencyFlagBits::eByRegion,
        .bufferMemoryBarrierCount = static_cast<u32>(source_pre.size()),
        .pBufferMemoryBarriers = source_pre.data(),
    });
    for (u32 index = 0; index < regions.size(); ++index) {
        const auto& region = regions[index];
        if (region.destination.empty()) {
            continue;
        }
        cmdbuf.copyBuffer(region.source.buffer, download.Handle(), vk::BufferCopy{
                                                                           .srcOffset =
                                                                               region.source.offset +
                                                                               region.relative_offset,
                                                                           .dstOffset =
                                                                               download_base +
                                                                               download_offsets[index],
                                                                           .size =
                                                                               region.destination.size(),
                                                                       });
    }
    source_post.push_back({
        .srcStageMask = vk::PipelineStageFlagBits2::eTransfer,
        .srcAccessMask = vk::AccessFlagBits2::eTransferWrite,
        .dstStageMask = vk::PipelineStageFlagBits2::eHost,
        .dstAccessMask = vk::AccessFlagBits2::eHostRead,
        .buffer = download.Handle(),
        .offset = download_base,
        .size = download_size,
    });
    cmdbuf.pipelineBarrier2(vk::DependencyInfo{
        .dependencyFlags = vk::DependencyFlagBits::eByRegion,
        .bufferMemoryBarrierCount = static_cast<u32>(source_post.size()),
        .pBufferMemoryBarriers = source_post.data(),
    });
    scheduler.Finish();
    download.InvalidateMappedRange(download_base, download_size);
    for (u32 index = 0; index < regions.size(); ++index) {
        const auto& region = regions[index];
        if (!region.destination.empty()) {
            std::memcpy(region.destination.data(), download_data + download_offsets[index],
                        region.destination.size());
        }
    }
    return true;
}

static bool LogImageGather3DCapture(
    u64 expected_shader,
    const std::array<u32, Shader::DreamsCompat::ImageGather3DCapture::DwordCount>& capture) {
    const auto word = [&](u32 absolute_dword) {
        return capture[absolute_dword - Gather3DCapture::BaseDword];
    };
    const auto record = [&](u32 site, u32 field) {
        return word(Gather3DCapture::RecordDword(site, field));
    };
    const u32 seen = word(Gather3DCapture::SeenDword);
    for (u32 site = 0; site < Gather3DCapture::MaxSites; ++site) {
        if ((seen & (1U << site)) == 0) {
            continue;
        }
        LOG_WARNING(
            Render_Vulkan,
            "3D ImageGather capture shader={:#010x}:{:#010x} expected={:#x} stage={} site={} "
            "wg={},{},{} local={},{},{} image_binding={} component={} z_filter={} "
            "coord_raw={:#010x},{:#010x},{:#010x} dims={}x{}x{} seen={:#x}",
            record(site, Gather3DCapture::ShaderHashHi),
            record(site, Gather3DCapture::ShaderHashLo), expected_shader,
            record(site, Gather3DCapture::Stage), record(site, Gather3DCapture::Site),
            record(site, Gather3DCapture::Workgroup), record(site, Gather3DCapture::Workgroup + 1),
            record(site, Gather3DCapture::Workgroup + 2),
            record(site, Gather3DCapture::LocalInvocation),
            record(site, Gather3DCapture::LocalInvocation + 1),
            record(site, Gather3DCapture::LocalInvocation + 2),
            record(site, Gather3DCapture::ImageBinding), record(site, Gather3DCapture::Component),
            record(site, Gather3DCapture::ZFilter),
            record(site, Gather3DCapture::NormalizedCoordinates),
            record(site, Gather3DCapture::NormalizedCoordinates + 1),
            record(site, Gather3DCapture::NormalizedCoordinates + 2),
            record(site, Gather3DCapture::Dimensions),
            record(site, Gather3DCapture::Dimensions + 1),
            record(site, Gather3DCapture::Dimensions + 2), seen);
        for (u32 source = 0; source < 4; ++source) {
            const u32 selected = record(site, Gather3DCapture::SelectedComponents + source);
            const u32 emitted = record(site, Gather3DCapture::EmittedComponents + source);
            LOG_WARNING(
                Render_Vulkan,
                "3D ImageGather source site={} output_lane={} xyz={},{},{} "
                "texel_raw={:#010x},{:#010x},{:#010x},{:#010x} "
                "selected={:#010x} emitted={:#010x} match={}",
                site, source,
                std::bit_cast<s32>(record(site, Gather3DCapture::SourceCoordinates + source * 3)),
                std::bit_cast<s32>(
                    record(site, Gather3DCapture::SourceCoordinates + source * 3 + 1)),
                std::bit_cast<s32>(
                    record(site, Gather3DCapture::SourceCoordinates + source * 3 + 2)),
                record(site, Gather3DCapture::SourceTexels + source * 4),
                record(site, Gather3DCapture::SourceTexels + source * 4 + 1),
                record(site, Gather3DCapture::SourceTexels + source * 4 + 2),
                record(site, Gather3DCapture::SourceTexels + source * 4 + 3), selected, emitted,
                selected == emitted);
        }
    }
    return seen != 0;
}

static DreamsAtlasGatherCrossCheckResult CrossCheckDreamsAtlasGather(
    u64 expected_shader,
    const std::array<u32, Shader::DreamsCompat::ImageGather3DCapture::DwordCount>& capture,
    std::span<const DreamsAtlasImageIdentity> bound_images) {
    DreamsAtlasGatherCrossCheckResult result{};
    const auto word = [&](u32 absolute_dword) {
        return capture[absolute_dword - Gather3DCapture::BaseDword];
    };
    const auto record = [&](u32 site, u32 field) {
        return word(Gather3DCapture::RecordDword(site, field));
    };
    const u32 seen = word(Gather3DCapture::SeenDword);
    result.seen = seen != 0;
    for (u32 site = 0; site < Gather3DCapture::MaxSites; ++site) {
        if ((seen & (1U << site)) == 0) {
            continue;
        }

        const u32 binding = record(site, Gather3DCapture::ImageBinding);
        const DreamsAtlasImageIdentity invalid_identity{};
        const auto& consumer =
            binding < bound_images.size() ? bound_images[binding] : invalid_identity;
        LOG_WARNING(
            Render_Vulkan,
            "Dreams 84aa/gather cross-check consumer shader={:#x} site={} binding={} valid={} "
            "resource={} element={} binding_type={} image_id={} uid={} backing={:#x} "
            "raw={:#018x},{:#018x},{:#018x},{:#018x} descriptor_base={:#x} "
            "descriptor={}x{}x{} pitch={} guest={:#x}+{:#x} cached={}x{}x{} pitch={} "
            "view_type={} format={} level={}+{} layer={}+{} map={},{},{},{}",
            expected_shader, site, binding, consumer.valid, consumer.resource_index,
            consumer.array_element, consumer.binding_type, consumer.image_id, consumer.image_uid,
            consumer.backing_handle, consumer.raw_descriptor[0], consumer.raw_descriptor[1],
            consumer.raw_descriptor[2], consumer.raw_descriptor[3], consumer.descriptor_base,
            consumer.descriptor_width, consumer.descriptor_height, consumer.descriptor_depth,
            consumer.descriptor_pitch, consumer.guest_base, consumer.guest_size,
            consumer.cached_width, consumer.cached_height, consumer.cached_depth,
            consumer.cached_pitch, consumer.view_type, consumer.view_format, consumer.base_level,
            consumer.levels, consumer.base_layer, consumer.layers, consumer.view_mapping[0],
            consumer.view_mapping[1], consumer.view_mapping[2], consumer.view_mapping[3]);

        const DreamsAtlasExpectedImage* exact{};
        const DreamsAtlasExpectedImage* related{};
        std::string_view relation = "image-unseen";
        for (const auto& atlas : g_dreams_atlas_expected_images) {
            if (SameDreamsAtlasView(atlas.identity, consumer)) {
                exact = &atlas;
                relation = "same-atlas-view";
                break;
            }
            if (related == nullptr && SameDreamsAtlasBacking(atlas.identity, consumer)) {
                related = &atlas;
                relation = "same-backing-view-mismatch";
            } else if (related == nullptr &&
                       atlas.identity.raw_descriptor == consumer.raw_descriptor &&
                       atlas.identity.descriptor_base == consumer.descriptor_base) {
                related = &atlas;
                relation = "same-descriptor-different-backing";
            } else if (related == nullptr &&
                       OverlapDreamsAtlasGuestRange(atlas.identity, consumer)) {
                related = &atlas;
                relation = "guest-alias-or-copy-different-backing";
            }
        }
        if (exact == nullptr && related != nullptr &&
            SameDreamsAtlasByteCoordinates(related->identity, consumer)) {
            exact = related;
            relation = "same-backing-r8uint-r8unorm";
        }

        const u32 component = record(site, Gather3DCapture::Component);
        for (u32 source = 0; source < 4; ++source) {
            const s32 x =
                std::bit_cast<s32>(record(site, Gather3DCapture::SourceCoordinates + source * 3));
            const s32 y = std::bit_cast<s32>(
                record(site, Gather3DCapture::SourceCoordinates + source * 3 + 1));
            const s32 z = std::bit_cast<s32>(
                record(site, Gather3DCapture::SourceCoordinates + source * 3 + 2));
            const u32 sampled_raw = record(site, Gather3DCapture::SelectedComponents + source);

            const DreamsAtlasExpectedBrick* brick{};
            std::string_view source_relation = relation;
            const auto brick_key = PackDreamsAtlasBrick(x, y, z);
            if (exact != nullptr && brick_key.has_value()) {
                const auto brick_it = exact->bricks.find(*brick_key);
                if (brick_it != exact->bricks.end()) {
                    brick = &brick_it->second;
                } else {
                    source_relation = "same-atlas-unwritten-coordinate";
                }
            } else if (exact != nullptr) {
                source_relation = "same-atlas-invalid-coordinate";
            }

            const bool r8_unorm =
                consumer.valid && consumer.view_format == static_cast<u32>(vk::Format::eR8Unorm);
            if (brick == nullptr || !r8_unorm || component != 0) {
                ++result.unknown;
                if (!r8_unorm && consumer.valid) {
                    source_relation = "non-r8-unorm-view";
                } else if (component != 0) {
                    source_relation = "non-red-gather-component";
                }
                const auto& producer = exact != nullptr ? exact : related;
                LOG_WARNING(
                    Render_Vulkan,
                    "Dreams 84aa/gather cross-check UNKNOWN shader={:#x} site={} source={} "
                    "xyz={},{},{} sampled_raw={:#010x} relation={} producer_id={} uid={} "
                    "backing={:#x} descriptor_base={:#x} view_type={} format={} level={}+{} "
                    "layer={}+{}",
                    expected_shader, site, source, x, y, z, sampled_raw, source_relation,
                    producer != nullptr ? producer->identity.image_id : 0,
                    producer != nullptr ? producer->identity.image_uid : 0,
                    producer != nullptr ? producer->identity.backing_handle : 0,
                    producer != nullptr ? producer->identity.descriptor_base : 0,
                    producer != nullptr ? producer->identity.view_type : 0,
                    producer != nullptr ? producer->identity.view_format : 0,
                    producer != nullptr ? producer->identity.base_level : 0,
                    producer != nullptr ? producer->identity.levels : 0,
                    producer != nullptr ? producer->identity.base_layer : 0,
                    producer != nullptr ? producer->identity.layers : 0);
                continue;
            }

            const u32 lane = (static_cast<u32>(y) & 7U) * 8U + (static_cast<u32>(x) & 7U);
            const u32 byte = static_cast<u32>(z) & 7U;
            const u8 expected = brick->bytes[byte * 64 + lane];
            const float sampled_float = std::bit_cast<float>(sampled_raw);
            const bool sampled_valid =
                std::isfinite(sampled_float) && sampled_float >= 0.0f && sampled_float <= 1.0f;
            const u32 sampled_byte = sampled_valid
                                         ? static_cast<u32>(std::lround(sampled_float * 255.0f))
                                         : std::numeric_limits<u32>::max();
            const bool matches = sampled_valid && sampled_byte == expected;
            const bool descriptor_equal = brick->producer_descriptor == consumer.raw_descriptor;
            if (matches) {
                ++result.matched;
                LOG_WARNING(
                    Render_Vulkan,
                    "Dreams 84aa/gather cross-check MATCH shader={:#x} site={} source={} "
                    "xyz={},{},{} expected={:#04x} sampled_byte={:#04x} sampled_raw={:#010x} "
                    "producer_dispatch={} producer_validation_mismatches={} "
                    "raw_descriptor_equal={}",
                    expected_shader, site, source, x, y, z, expected, sampled_byte, sampled_raw,
                    brick->dispatch_sequence, brick->validation_mismatches, descriptor_equal);
            } else {
                ++result.mismatched;
                LOG_ERROR(Render_Vulkan,
                          "Dreams 84aa/gather cross-check MISMATCH shader={:#x} site={} source={} "
                          "xyz={},{},{} expected={:#04x} sampled_byte={:#x} sampled_raw={:#010x} "
                          "sampled_valid={} producer_dispatch={} producer_validation_mismatches={} "
                          "raw_descriptor_equal={}",
                          expected_shader, site, source, x, y, z, expected, sampled_byte,
                          sampled_raw, sampled_valid, brick->dispatch_sequence,
                          brick->validation_mismatches, descriptor_equal);
            }
        }
    }
    LOG_WARNING(Render_Vulkan,
                "Dreams 84aa/gather cross-check summary shader={:#x} seen={} matched={} "
                "mismatched={} unknown={} producer_atlases={}",
                expected_shader, result.seen, result.matched, result.mismatched, result.unknown,
                g_dreams_atlas_expected_images.size());
    return result;
}

static bool LogImageGather3DConsumerCapture(
    u64 expected_shader,
    const std::array<u32, Shader::DreamsCompat::ImageGather3DConsumerCapture::DwordCount>&
        capture) {
    const auto word = [&](u32 absolute_dword) {
        return capture[absolute_dword - Gather3DConsumerCapture::BaseDword];
    };
    const auto record = [&](u32 site, u32 index, u32 field) {
        return word(Gather3DConsumerCapture::RecordDword(site, index, field));
    };
    const u32 seen = word(Gather3DConsumerCapture::SeenDword);
    for (u32 site = 0; site < Gather3DConsumerCapture::MaxSites; ++site) {
        if ((seen & (1U << site)) == 0) {
            continue;
        }
        const u32 total = word(Gather3DConsumerCapture::CounterDword(site));
        const u32 stored = std::min(total, Gather3DConsumerCapture::MaxRecordsPerSite);
        LOG_WARNING(Render_Vulkan,
                    "3D ImageGather consumer expected={:#x} site={} records={}/{} seen={:#x}",
                    expected_shader, site, stored, total, seen);
        for (u32 index = 0; index < stored; ++index) {
            const std::array<u32, 4> input{
                record(site, index, Gather3DConsumerCapture::InputValues),
                record(site, index, Gather3DConsumerCapture::InputValues + 1),
                record(site, index, Gather3DConsumerCapture::InputValues + 2),
                record(site, index, Gather3DConsumerCapture::InputValues + 3),
            };
            const std::array<u32, 4> reloaded{
                record(site, index, Gather3DConsumerCapture::ReloadedValues),
                record(site, index, Gather3DConsumerCapture::ReloadedValues + 1),
                record(site, index, Gather3DConsumerCapture::ReloadedValues + 2),
                record(site, index, Gather3DConsumerCapture::ReloadedValues + 3),
            };
            LOG_WARNING(Render_Vulkan,
                        "3D ImageGather consumer shader={:#010x}:{:#010x} site={} record={} "
                        "wg={},{},{} local={},{},{} handle={} components={} buffer_type={} "
                        "raw_index={} resolved_index={} input={:#010x},{:#010x},{:#010x},{:#010x} "
                        "reload={:#010x},{:#010x},{:#010x},{:#010x} match_mask={:#x} "
                        "input_f32={},{},{},{} reload_f32={},{},{},{}",
                        record(site, index, Gather3DConsumerCapture::ShaderHashHi),
                        record(site, index, Gather3DConsumerCapture::ShaderHashLo), site, index,
                        record(site, index, Gather3DConsumerCapture::Workgroup),
                        record(site, index, Gather3DConsumerCapture::Workgroup + 1),
                        record(site, index, Gather3DConsumerCapture::Workgroup + 2),
                        record(site, index, Gather3DConsumerCapture::LocalInvocation),
                        record(site, index, Gather3DConsumerCapture::LocalInvocation + 1),
                        record(site, index, Gather3DConsumerCapture::LocalInvocation + 2),
                        record(site, index, Gather3DConsumerCapture::Handle),
                        record(site, index, Gather3DConsumerCapture::Components),
                        record(site, index, Gather3DConsumerCapture::BufferType),
                        record(site, index, Gather3DConsumerCapture::RawAddress),
                        record(site, index, Gather3DConsumerCapture::ResolvedAddress), input[0],
                        input[1], input[2], input[3], reloaded[0], reloaded[1], reloaded[2],
                        reloaded[3], record(site, index, Gather3DConsumerCapture::MatchMask),
                        std::bit_cast<float>(input[0]), std::bit_cast<float>(input[1]),
                        std::bit_cast<float>(input[2]), std::bit_cast<float>(input[3]),
                        std::bit_cast<float>(reloaded[0]), std::bit_cast<float>(reloaded[1]),
                        std::bit_cast<float>(reloaded[2]), std::bit_cast<float>(reloaded[3]));
        }
    }
    return seen != 0;
}

class DreamsPerformanceProfiler {
public:
    struct DocToken {
        static constexpr u32 InvalidSlot = std::numeric_limits<u32>::max();
        u32 slot = InvalidSlot;

        explicit operator bool() const noexcept {
            return slot != InvalidSlot;
        }
    };

    struct ComputeToken {
        static constexpr u32 InvalidSlot = std::numeric_limits<u32>::max();
        u32 slot = InvalidSlot;

        explicit operator bool() const noexcept {
            return slot != InvalidSlot;
        }
    };

    struct DrawToken {
        static constexpr u32 InvalidSlot = std::numeric_limits<u32>::max();
        u32 slot = InvalidSlot;

        explicit operator bool() const noexcept {
            return slot != InvalidSlot;
        }
    };

    DreamsPerformanceProfiler(const Instance& instance_, Scheduler& scheduler_)
        : instance{instance_}, scheduler{scheduler_}, device{instance.GetDevice()}, requested{[] {
              const char* value = std::getenv("SHADPS4_DREAMS_PERF_PROFILE");
              return value != nullptr && std::string_view{value} == "1";
          }()},
          all_compute_requested{[] {
              const char* value = std::getenv("SHADPS4_DREAMS_PERF_PROFILE_ALL_COMPUTE");
              return value != nullptr && std::string_view{value} == "1";
          }()},
          all_draw_requested{[] {
              const char* value = std::getenv("SHADPS4_DREAMS_PERF_PROFILE_ALL_DRAW");
              return value != nullptr && std::string_view{value} == "1";
          }()} {}

    void CountDraw() {
        if (!IsActiveForDreams()) {
            return;
        }
        ++interval_draws;
        if (((interval_draws + interval_dispatches) & 1023U) == 0) {
            MaybePollAndReport();
        }
    }

    void CountDispatch() {
        if (!IsActiveForDreams()) {
            return;
        }
        ++interval_dispatches;
        if (((interval_draws + interval_dispatches) & 1023U) == 0) {
            MaybePollAndReport();
        }
    }

    DocToken BeginDoc(vk::CommandBuffer cmdbuf, u32 groups) {
        if (!IsDocActive()) {
            return {};
        }

        const u32 frame = DebugState.GetFrameNum();
        if (frame != current_frame) {
            current_frame = frame;
            current_frame_doc_seen = 0;
        }
        ++interval_doc_seen;
        interval_doc_groups += groups;
        ++current_frame_doc_seen;
        MaybePollAndReport();
        if (!Initialize() || free_slots.empty()) {
            ++interval_doc_dropped;
            ++total_doc_dropped;
            return {};
        }

        const u32 slot_index = free_slots.back();
        free_slots.pop_back();
        auto& slot = slots[slot_index];
        slot.frame = frame;
        slot.groups = groups;
        slot.tick = 0;

        const u32 first_query = slot_index * TimestampsPerDoc;
        cmdbuf.resetQueryPool(query_pool.get(), first_query, TimestampsPerDoc);
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eTopOfPipe, query_pool.get(),
                               first_query + 0);
        ++interval_doc_sampled;
        return {.slot = slot_index};
    }

    void EndCollectBeginPrefix(vk::CommandBuffer cmdbuf, DocToken token) const {
        if (!token) {
            return;
        }
        const u32 first_query = token.slot * TimestampsPerDoc;
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eBottomOfPipe, query_pool.get(),
                               first_query + 1);
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eTopOfPipe, query_pool.get(),
                               first_query + 2);
    }

    void EndPrefixBeginReplay(vk::CommandBuffer cmdbuf, DocToken token) const {
        if (!token) {
            return;
        }
        const u32 first_query = token.slot * TimestampsPerDoc;
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eBottomOfPipe, query_pool.get(),
                               first_query + 3);
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eTopOfPipe, query_pool.get(),
                               first_query + 4);
    }

    void EndDoc(vk::CommandBuffer cmdbuf, DocToken token) {
        if (!token) {
            return;
        }
        const u32 first_query = token.slot * TimestampsPerDoc;
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eBottomOfPipe, query_pool.get(),
                               first_query + 5);
        slots[token.slot].tick = scheduler.CurrentTick();
        active_slots.push_back(token.slot);
    }

    ComputeToken BeginCompute(vk::CommandBuffer cmdbuf, u64 shader_hash, bool indirect, u32 dim_x,
                              u32 dim_y, u32 dim_z) {
        if (!IsComputeActive()) {
            return {};
        }

        ++interval_compute_seen;
        MaybePollAndReport();
        if (!InitializeCompute()) {
            ++interval_compute_dropped;
            return {};
        }
        if (compute_free_slots.empty()) {
            PollComputeResults();
        }
        if (compute_free_slots.empty()) {
            ++interval_compute_dropped;
            return {};
        }

        const u32 slot_index = compute_free_slots.back();
        compute_free_slots.pop_back();
        auto& slot = compute_slots[slot_index];
        slot.shader_hash = shader_hash;
        slot.tick = 0;
        slot.frame = DebugState.GetFrameNum();
        slot.dim_x = dim_x;
        slot.dim_y = dim_y;
        slot.dim_z = dim_z;
        slot.indirect = indirect;

        const u32 first_query = slot_index * TimestampsPerCompute;
        cmdbuf.resetQueryPool(compute_query_pool.get(), first_query, TimestampsPerCompute);
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eTopOfPipe, compute_query_pool.get(),
                               first_query);
        ++interval_compute_sampled;
        return {.slot = slot_index};
    }

    void EndCompute(vk::CommandBuffer cmdbuf, ComputeToken token) {
        if (!token) {
            return;
        }
        const u32 first_query = token.slot * TimestampsPerCompute;
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eBottomOfPipe, compute_query_pool.get(),
                               first_query + 1);
        compute_slots[token.slot].tick = scheduler.CurrentTick();
        compute_active_slots.push_back(token.slot);
    }

    DrawToken BeginDraw(vk::CommandBuffer cmdbuf, u64 vertex_hash, u64 fragment_hash, bool indirect,
                        bool indexed, u32 vertices_or_indices, u32 instances, u32 max_count,
                        bool has_count_buffer) {
        if (!IsDrawActive()) {
            return {};
        }

        ++interval_draw_seen;
        MaybePollAndReport();
        if (!InitializeDraw()) {
            ++interval_draw_dropped;
            return {};
        }
        if (draw_free_slots.empty()) {
            PollDrawResults();
        }
        if (draw_free_slots.empty()) {
            ++interval_draw_dropped;
            return {};
        }

        const u32 slot_index = draw_free_slots.back();
        draw_free_slots.pop_back();
        auto& slot = draw_slots[slot_index];
        slot.vertex_hash = vertex_hash;
        slot.fragment_hash = fragment_hash;
        slot.tick = 0;
        slot.frame = DebugState.GetFrameNum();
        slot.vertices_or_indices = vertices_or_indices;
        slot.instances = instances;
        slot.max_count = max_count;
        slot.indirect = indirect;
        slot.indexed = indexed;
        slot.has_count_buffer = has_count_buffer;

        const u32 first_query = slot_index * TimestampsPerDraw;
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eTopOfPipe, draw_query_pool.get(),
                               first_query);
        ++interval_draw_sampled;
        return {.slot = slot_index};
    }

    void EndDraw(vk::CommandBuffer cmdbuf, DrawToken token) {
        if (!token) {
            return;
        }
        const u32 first_query = token.slot * TimestampsPerDraw;
        cmdbuf.writeTimestamp2(vk::PipelineStageFlagBits2::eBottomOfPipe, draw_query_pool.get(),
                               first_query + 1);
        draw_slots[token.slot].tick = scheduler.CurrentTick();
        draw_active_slots.push_back(token.slot);
    }

    void Poll() {
        if (initialized) {
            PollResults();
        }
        if (compute_initialized) {
            PollComputeResults();
        }
        if (draw_initialized) {
            PollDrawResults();
        }
        MaybeReport();
    }

private:
    static constexpr u32 TimestampsPerDoc = 6;
    static constexpr u32 SlotCount = 4096;
    static constexpr u32 TimestampsPerCompute = 2;
    static constexpr u32 ComputeSlotCount = 32768;
    static constexpr u32 TimestampsPerDraw = 2;
    static constexpr u32 DrawSlotCount = 32768;

    struct Slot {
        u64 tick{};
        u32 frame{};
        u32 groups{};
    };

    struct ComputeSlot {
        u64 shader_hash{};
        u64 tick{};
        u32 frame{};
        u32 dim_x{};
        u32 dim_y{};
        u32 dim_z{};
        bool indirect{};
    };

    struct ComputeStats {
        u64 count{};
        u64 first_tick{std::numeric_limits<u64>::max()};
        u64 last_tick{};
        u32 first_frame{std::numeric_limits<u32>::max()};
        u32 last_frame{};
        u32 max_frame{};
        u32 max_dim_x{};
        u32 max_dim_y{};
        u32 max_dim_z{};
        u64 max_tick{};
        double total_ms{};
        double max_ms{};
    };

    struct DrawSlot {
        u64 vertex_hash{};
        u64 fragment_hash{};
        u64 tick{};
        u32 frame{};
        u32 vertices_or_indices{};
        u32 instances{};
        u32 max_count{};
        bool indirect{};
        bool indexed{};
        bool has_count_buffer{};
    };

    struct DrawStats {
        u64 count{};
        u64 first_tick{std::numeric_limits<u64>::max()};
        u64 last_tick{};
        u32 first_frame{std::numeric_limits<u32>::max()};
        u32 last_frame{};
        u32 max_frame{};
        u32 max_vertices_or_indices{};
        u32 max_instances{};
        u32 max_count{};
        u64 max_tick{};
        bool max_has_count_buffer{};
        double total_ms{};
        double max_ms{};
    };

    bool IsActiveForDreams() const {
        return (requested || all_compute_requested || all_draw_requested) &&
               Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
    }

    bool IsDocActive() const {
        return requested && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
    }

    bool IsComputeActive() const {
        return all_compute_requested && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
    }

    bool IsDrawActive() const {
        return all_draw_requested && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
    }

    bool Initialize() {
        if (initialization_attempted) {
            return initialized;
        }
        initialization_attempted = true;

        const auto physical_device = instance.GetPhysicalDevice();
        const auto properties = physical_device.getProperties();
        const auto queue_families = physical_device.getQueueFamilyProperties();
        const u32 queue_family = instance.GetGraphicsQueueFamilyIndex();
        if (properties.limits.timestampPeriod <= 0.0f || queue_family >= queue_families.size() ||
            queue_families[queue_family].timestampValidBits == 0) {
            LOG_ERROR(Render_Vulkan,
                      "Dreams performance profiler disabled: graphics queue has no timestamps");
            return false;
        }

        timestamp_period_ns = properties.limits.timestampPeriod;
        timestamp_valid_bits = queue_families[queue_family].timestampValidBits;
        timestamp_mask = timestamp_valid_bits == 64 ? std::numeric_limits<u64>::max()
                                                    : (u64{1} << timestamp_valid_bits) - 1;

        const vk::QueryPoolCreateInfo query_pool_info{
            .queryType = vk::QueryType::eTimestamp,
            .queryCount = SlotCount * TimestampsPerDoc,
        };
        auto [result, pool] = device.createQueryPoolUnique(query_pool_info);
        if (result != vk::Result::eSuccess) {
            LOG_ERROR(Render_Vulkan, "Dreams performance profiler disabled: query-pool error {}",
                      vk::to_string(result));
            return false;
        }
        query_pool = std::move(pool);

        slots.resize(SlotCount);
        free_slots.reserve(SlotCount);
        for (u32 index = SlotCount; index-- > 0;) {
            free_slots.push_back(index);
        }
        report_start = std::chrono::steady_clock::now();
        report_frame = DebugState.GetFrameNum();
        current_frame = report_frame;
        initialized = true;
        LOG_WARNING(Render_Vulkan,
                    "Dreams performance profiler enabled: async timestamps slots={} period={}ns "
                    "valid_bits={} (no GPU/CPU waits)",
                    SlotCount, timestamp_period_ns, timestamp_valid_bits);
        return true;
    }

    bool InitializeCompute() {
        if (compute_initialization_attempted) {
            return compute_initialized;
        }
        compute_initialization_attempted = true;

        const auto physical_device = instance.GetPhysicalDevice();
        const auto properties = physical_device.getProperties();
        const auto queue_families = physical_device.getQueueFamilyProperties();
        const u32 queue_family = instance.GetGraphicsQueueFamilyIndex();
        if (properties.limits.timestampPeriod <= 0.0f || queue_family >= queue_families.size() ||
            queue_families[queue_family].timestampValidBits == 0) {
            LOG_ERROR(Render_Vulkan,
                      "Dreams all-compute profiler disabled: graphics queue has no timestamps");
            return false;
        }

        timestamp_period_ns = properties.limits.timestampPeriod;
        timestamp_valid_bits = queue_families[queue_family].timestampValidBits;
        timestamp_mask = timestamp_valid_bits == 64 ? std::numeric_limits<u64>::max()
                                                    : (u64{1} << timestamp_valid_bits) - 1;

        const vk::QueryPoolCreateInfo query_pool_info{
            .queryType = vk::QueryType::eTimestamp,
            .queryCount = ComputeSlotCount * TimestampsPerCompute,
        };
        auto [result, pool] = device.createQueryPoolUnique(query_pool_info);
        if (result != vk::Result::eSuccess) {
            LOG_ERROR(Render_Vulkan, "Dreams all-compute profiler disabled: query-pool error {}",
                      vk::to_string(result));
            return false;
        }
        compute_query_pool = std::move(pool);

        compute_slots.resize(ComputeSlotCount);
        compute_free_slots.reserve(ComputeSlotCount);
        for (u32 index = ComputeSlotCount; index-- > 0;) {
            compute_free_slots.push_back(index);
        }
        report_start = std::chrono::steady_clock::now();
        report_frame = DebugState.GetFrameNum();
        current_frame = report_frame;
        compute_initialized = true;
        LOG_WARNING(Render_Vulkan,
                    "Dreams all-compute profiler enabled: async timestamps slots={} period={}ns "
                    "valid_bits={} (no GPU/CPU waits)",
                    ComputeSlotCount, timestamp_period_ns, timestamp_valid_bits);
        return true;
    }

    bool InitializeDraw() {
        if (draw_initialization_attempted) {
            return draw_initialized;
        }
        draw_initialization_attempted = true;

        const auto physical_device = instance.GetPhysicalDevice();
        const auto properties = physical_device.getProperties();
        const auto queue_families = physical_device.getQueueFamilyProperties();
        const auto feature_chain =
            physical_device
                .getFeatures2<vk::PhysicalDeviceFeatures2, vk::PhysicalDeviceVulkan12Features>();
        const bool host_query_reset =
            feature_chain.get<vk::PhysicalDeviceVulkan12Features>().hostQueryReset;
        const u32 queue_family = instance.GetGraphicsQueueFamilyIndex();
        if (properties.limits.timestampPeriod <= 0.0f || queue_family >= queue_families.size() ||
            queue_families[queue_family].timestampValidBits == 0 || !host_query_reset) {
            LOG_ERROR(Render_Vulkan,
                      "Dreams all-draw profiler disabled: timestamps or host query reset missing");
            return false;
        }

        timestamp_period_ns = properties.limits.timestampPeriod;
        timestamp_valid_bits = queue_families[queue_family].timestampValidBits;
        timestamp_mask = timestamp_valid_bits == 64 ? std::numeric_limits<u64>::max()
                                                    : (u64{1} << timestamp_valid_bits) - 1;

        const vk::QueryPoolCreateInfo query_pool_info{
            .queryType = vk::QueryType::eTimestamp,
            .queryCount = DrawSlotCount * TimestampsPerDraw,
        };
        auto [result, pool] = device.createQueryPoolUnique(query_pool_info);
        if (result != vk::Result::eSuccess) {
            LOG_ERROR(Render_Vulkan, "Dreams all-draw profiler disabled: query-pool error {}",
                      vk::to_string(result));
            return false;
        }
        draw_query_pool = std::move(pool);
        device.resetQueryPool(draw_query_pool.get(), 0, DrawSlotCount * TimestampsPerDraw);

        draw_slots.resize(DrawSlotCount);
        draw_free_slots.reserve(DrawSlotCount);
        for (u32 index = DrawSlotCount; index-- > 0;) {
            draw_free_slots.push_back(index);
        }
        report_start = std::chrono::steady_clock::now();
        report_frame = DebugState.GetFrameNum();
        current_frame = report_frame;
        draw_initialized = true;
        LOG_WARNING(Render_Vulkan,
                    "Dreams all-draw profiler enabled: async timestamps slots={} period={}ns "
                    "valid_bits={} (no GPU/CPU waits)",
                    DrawSlotCount, timestamp_period_ns, timestamp_valid_bits);
        return true;
    }

    u64 TimestampDelta(u64 begin, u64 end) const {
        return (end - begin) & timestamp_mask;
    }

    void PollResults() {
        if (active_slots.empty() || !scheduler.IsFree(slots[active_slots.front()].tick)) {
            return;
        }

        const u64 completed_tick = scheduler.GetMasterSemaphore()->KnownGpuTick();
        while (!active_slots.empty()) {
            const u32 slot_index = active_slots.front();
            auto& slot = slots[slot_index];
            if (slot.tick > completed_tick) {
                break;
            }

            std::array<u64, TimestampsPerDoc> timestamps{};
            const auto result = device.getQueryPoolResults(
                query_pool.get(), slot_index * TimestampsPerDoc, TimestampsPerDoc,
                sizeof(timestamps), timestamps.data(), sizeof(u64), vk::QueryResultFlagBits::e64);
            if (result == vk::Result::eSuccess) {
                const double tick_to_ms = static_cast<double>(timestamp_period_ns) / 1'000'000.0;
                const double collect_ms =
                    static_cast<double>(TimestampDelta(timestamps[0], timestamps[1])) * tick_to_ms;
                const double prefix_ms =
                    static_cast<double>(TimestampDelta(timestamps[2], timestamps[3])) * tick_to_ms;
                const double replay_ms =
                    static_cast<double>(TimestampDelta(timestamps[4], timestamps[5])) * tick_to_ms;
                const double total_ms =
                    static_cast<double>(TimestampDelta(timestamps[0], timestamps[5])) * tick_to_ms;
                interval_gpu_collect_ms += collect_ms;
                interval_gpu_prefix_ms += prefix_ms;
                interval_gpu_replay_ms += replay_ms;
                interval_gpu_total_ms += total_ms;
                ++interval_doc_completed;
            } else {
                ++interval_query_errors;
                if (interval_query_errors == 1 || std::has_single_bit(interval_query_errors)) {
                    LOG_ERROR(Render_Vulkan,
                              "Dreams performance profiler query failed after completed tick: {}",
                              vk::to_string(result));
                }
            }

            slot = {};
            active_slots.pop_front();
            free_slots.push_back(slot_index);
        }
    }

    void PollComputeResults() {
        if (compute_active_slots.empty() ||
            !scheduler.IsFree(compute_slots[compute_active_slots.front()].tick)) {
            return;
        }

        const u64 completed_tick = scheduler.GetMasterSemaphore()->KnownGpuTick();
        while (!compute_active_slots.empty()) {
            const u32 slot_index = compute_active_slots.front();
            auto& slot = compute_slots[slot_index];
            if (slot.tick > completed_tick) {
                break;
            }

            std::array<u64, TimestampsPerCompute> timestamps{};
            const auto result = device.getQueryPoolResults(
                compute_query_pool.get(), slot_index * TimestampsPerCompute, TimestampsPerCompute,
                sizeof(timestamps), timestamps.data(), sizeof(u64), vk::QueryResultFlagBits::e64);
            if (result == vk::Result::eSuccess) {
                const double elapsed_ms =
                    static_cast<double>(TimestampDelta(timestamps[0], timestamps[1])) *
                    static_cast<double>(timestamp_period_ns) / 1'000'000.0;
                auto& stats = interval_compute_stats[std::pair{slot.shader_hash, slot.indirect}];
                ++stats.count;
                stats.total_ms += elapsed_ms;
                stats.first_frame = std::min(stats.first_frame, slot.frame);
                stats.last_frame = std::max(stats.last_frame, slot.frame);
                stats.first_tick = std::min(stats.first_tick, slot.tick);
                stats.last_tick = std::max(stats.last_tick, slot.tick);
                if (elapsed_ms > stats.max_ms) {
                    stats.max_ms = elapsed_ms;
                    stats.max_frame = slot.frame;
                    stats.max_tick = slot.tick;
                    stats.max_dim_x = slot.dim_x;
                    stats.max_dim_y = slot.dim_y;
                    stats.max_dim_z = slot.dim_z;
                }
                interval_compute_gpu_ms += elapsed_ms;
                ++interval_compute_completed;
            } else {
                ++interval_compute_query_errors;
                if (interval_compute_query_errors == 1 ||
                    std::has_single_bit(interval_compute_query_errors)) {
                    LOG_ERROR(Render_Vulkan,
                              "Dreams all-compute query failed after completed tick: {}",
                              vk::to_string(result));
                }
            }

            slot = {};
            compute_active_slots.pop_front();
            compute_free_slots.push_back(slot_index);
        }
    }

    void PollDrawResults() {
        if (draw_active_slots.empty() ||
            !scheduler.IsFree(draw_slots[draw_active_slots.front()].tick)) {
            return;
        }

        const u64 completed_tick = scheduler.GetMasterSemaphore()->KnownGpuTick();
        while (!draw_active_slots.empty()) {
            const u32 slot_index = draw_active_slots.front();
            auto& slot = draw_slots[slot_index];
            if (slot.tick > completed_tick) {
                break;
            }

            std::array<u64, TimestampsPerDraw> timestamps{};
            const auto result = device.getQueryPoolResults(
                draw_query_pool.get(), slot_index * TimestampsPerDraw, TimestampsPerDraw,
                sizeof(timestamps), timestamps.data(), sizeof(u64), vk::QueryResultFlagBits::e64);
            if (result == vk::Result::eSuccess) {
                const double elapsed_ms =
                    static_cast<double>(TimestampDelta(timestamps[0], timestamps[1])) *
                    static_cast<double>(timestamp_period_ns) / 1'000'000.0;
                const auto key = std::pair{std::pair{slot.vertex_hash, slot.fragment_hash},
                                           std::pair{slot.indirect, slot.indexed}};
                auto& stats = interval_draw_stats[key];
                ++stats.count;
                stats.total_ms += elapsed_ms;
                stats.first_frame = std::min(stats.first_frame, slot.frame);
                stats.last_frame = std::max(stats.last_frame, slot.frame);
                stats.first_tick = std::min(stats.first_tick, slot.tick);
                stats.last_tick = std::max(stats.last_tick, slot.tick);
                if (elapsed_ms > stats.max_ms) {
                    stats.max_ms = elapsed_ms;
                    stats.max_frame = slot.frame;
                    stats.max_tick = slot.tick;
                    stats.max_vertices_or_indices = slot.vertices_or_indices;
                    stats.max_instances = slot.instances;
                    stats.max_count = slot.max_count;
                    stats.max_has_count_buffer = slot.has_count_buffer;
                }
                interval_draw_gpu_ms += elapsed_ms;
                ++interval_draw_completed;
            } else {
                ++interval_draw_query_errors;
                if (interval_draw_query_errors == 1 ||
                    std::has_single_bit(interval_draw_query_errors)) {
                    LOG_ERROR(Render_Vulkan,
                              "Dreams all-draw query failed after completed tick: {}",
                              vk::to_string(result));
                }
            }

            device.resetQueryPool(draw_query_pool.get(), slot_index * TimestampsPerDraw,
                                  TimestampsPerDraw);
            slot = {};
            draw_active_slots.pop_front();
            draw_free_slots.push_back(slot_index);
        }
    }

    void MaybePollAndReport(bool force_poll = false) {
        ++commands_since_poll;
        const bool periodic_poll = (commands_since_poll & 63U) == 0;
        if (initialized && (force_poll || free_slots.empty() || periodic_poll)) {
            PollResults();
        }
        if (compute_initialized && (force_poll || compute_free_slots.empty() || periodic_poll)) {
            PollComputeResults();
        }
        if (draw_initialized && (force_poll || draw_free_slots.empty() || periodic_poll)) {
            PollDrawResults();
        }
        if (force_poll || periodic_poll) {
            commands_since_poll = 0;
            MaybeReport();
        }
    }

    void MaybeReport() {
        if (!IsActiveForDreams()) {
            return;
        }
        const auto now = std::chrono::steady_clock::now();
        const double elapsed = std::chrono::duration<double>(now - report_start).count();
        if (elapsed < 1.0) {
            return;
        }

        const u32 frame = DebugState.GetFrameNum();
        if (frame != current_frame) {
            current_frame = frame;
            current_frame_doc_seen = 0;
        }
        const u32 frames = frame - report_frame;
        const double docs_per_second = static_cast<double>(interval_doc_seen) / elapsed;
        const double groups_per_second = static_cast<double>(interval_doc_groups) / elapsed;
        const double draws_per_second = static_cast<double>(interval_draws) / elapsed;
        const double dispatches_per_second = static_cast<double>(interval_dispatches) / elapsed;
        const double docs_per_frame =
            frames != 0 ? static_cast<double>(interval_doc_seen) / frames : 0.0;
        const double average_total_ms =
            interval_doc_completed != 0 ? interval_gpu_total_ms / interval_doc_completed : 0.0;
        LOG_WARNING(Render_Vulkan,
                    "Dreams perf 1s frames={} draws={}({:.1f}/s) dispatches={}({:.1f}/s) "
                    "84aa_seen={}({:.1f}/s,{:.2f}/frame) sampled={} completed={} inflight={} "
                    "dropped={} groups={}({:.1f}/s) gpu_ms collect={:.3f} prefix={:.3f} "
                    "replay={:.3f} total={:.3f} avg_total={:.3f} current_frame={} "
                    "current_frame_84aa={} query_errors={}",
                    frames, interval_draws, draws_per_second, interval_dispatches,
                    dispatches_per_second, interval_doc_seen, docs_per_second, docs_per_frame,
                    interval_doc_sampled, interval_doc_completed, active_slots.size(),
                    interval_doc_dropped, interval_doc_groups, groups_per_second,
                    interval_gpu_collect_ms, interval_gpu_prefix_ms, interval_gpu_replay_ms,
                    interval_gpu_total_ms, average_total_ms, frame, current_frame_doc_seen,
                    interval_query_errors);

        if (all_compute_requested) {
            using RankedCompute = std::pair<std::pair<u64, bool>, const ComputeStats*>;
            std::vector<RankedCompute> ranked;
            ranked.reserve(interval_compute_stats.size());
            for (const auto& [key, stats] : interval_compute_stats) {
                ranked.emplace_back(key, &stats);
            }
            std::ranges::sort(ranked, [](const RankedCompute& lhs, const RankedCompute& rhs) {
                if (lhs.second->total_ms != rhs.second->total_ms) {
                    return lhs.second->total_ms > rhs.second->total_ms;
                }
                return lhs.first < rhs.first;
            });
            constexpr size_t TopCount = 8;
            const size_t top_count = std::min(TopCount, ranked.size());
            LOG_WARNING(Render_Vulkan,
                        "Dreams compute perf 1s seen={} sampled={} completed={} inflight={} "
                        "dropped={} query_errors={} gpu_total_ms={:.3f} unique={} top={}",
                        interval_compute_seen, interval_compute_sampled, interval_compute_completed,
                        compute_active_slots.size(), interval_compute_dropped,
                        interval_compute_query_errors, interval_compute_gpu_ms,
                        interval_compute_stats.size(), top_count);
            for (size_t rank = 0; rank < top_count; ++rank) {
                const auto& [key, stats_ptr] = ranked[rank];
                const auto& stats = *stats_ptr;
                LOG_WARNING(Render_Vulkan,
                            "Dreams compute perf rank={} hash={:#018x} indirect={} count={} "
                            "total_ms={:.3f} avg_ms={:.3f} max_ms={:.3f} "
                            "frames={}-{} ticks={}-{} max_dims={}x{}x{} max_frame={} max_tick={}",
                            rank + 1, key.first, key.second, stats.count, stats.total_ms,
                            stats.total_ms / static_cast<double>(stats.count), stats.max_ms,
                            stats.first_frame, stats.last_frame, stats.first_tick, stats.last_tick,
                            stats.max_dim_x, stats.max_dim_y, stats.max_dim_z, stats.max_frame,
                            stats.max_tick);
            }
        }

        if (all_draw_requested) {
            using DrawKey = std::pair<std::pair<u64, u64>, std::pair<bool, bool>>;
            using RankedDraw = std::pair<DrawKey, const DrawStats*>;
            std::vector<RankedDraw> ranked;
            ranked.reserve(interval_draw_stats.size());
            for (const auto& [key, stats] : interval_draw_stats) {
                ranked.emplace_back(key, &stats);
            }
            std::ranges::sort(ranked, [](const RankedDraw& lhs, const RankedDraw& rhs) {
                if (lhs.second->total_ms != rhs.second->total_ms) {
                    return lhs.second->total_ms > rhs.second->total_ms;
                }
                return lhs.first < rhs.first;
            });
            constexpr size_t TopCount = 8;
            const size_t top_count = std::min(TopCount, ranked.size());
            LOG_WARNING(Render_Vulkan,
                        "Dreams draw perf 1s seen={} sampled={} completed={} inflight={} "
                        "dropped={} query_errors={} gpu_total_ms={:.3f} unique={} top={}",
                        interval_draw_seen, interval_draw_sampled, interval_draw_completed,
                        draw_active_slots.size(), interval_draw_dropped, interval_draw_query_errors,
                        interval_draw_gpu_ms, interval_draw_stats.size(), top_count);
            for (size_t rank = 0; rank < top_count; ++rank) {
                const auto& [key, stats_ptr] = ranked[rank];
                const auto& stats = *stats_ptr;
                LOG_WARNING(
                    Render_Vulkan,
                    "Dreams draw perf rank={} vs={:#018x} fs={:#018x} indirect={} indexed={} "
                    "count={} total_ms={:.3f} avg_ms={:.3f} max_ms={:.3f} "
                    "frames={}-{} ticks={}-{} max_vertices_or_indices={} max_instances={} "
                    "max_count={} max_count_buffer={} max_frame={} max_tick={}",
                    rank + 1, key.first.first, key.first.second, key.second.first,
                    key.second.second, stats.count, stats.total_ms,
                    stats.total_ms / static_cast<double>(stats.count), stats.max_ms,
                    stats.first_frame, stats.last_frame, stats.first_tick, stats.last_tick,
                    stats.max_vertices_or_indices, stats.max_instances, stats.max_count,
                    stats.max_has_count_buffer, stats.max_frame, stats.max_tick);
            }
        }

        interval_draws = 0;
        interval_dispatches = 0;
        interval_doc_seen = 0;
        interval_doc_sampled = 0;
        interval_doc_completed = 0;
        interval_doc_dropped = 0;
        interval_doc_groups = 0;
        interval_query_errors = 0;
        interval_gpu_collect_ms = 0.0;
        interval_gpu_prefix_ms = 0.0;
        interval_gpu_replay_ms = 0.0;
        interval_gpu_total_ms = 0.0;
        interval_compute_seen = 0;
        interval_compute_sampled = 0;
        interval_compute_completed = 0;
        interval_compute_dropped = 0;
        interval_compute_query_errors = 0;
        interval_compute_gpu_ms = 0.0;
        interval_compute_stats.clear();
        interval_draw_seen = 0;
        interval_draw_sampled = 0;
        interval_draw_completed = 0;
        interval_draw_dropped = 0;
        interval_draw_query_errors = 0;
        interval_draw_gpu_ms = 0.0;
        interval_draw_stats.clear();
        report_start = now;
        report_frame = frame;
    }

private:
    const Instance& instance;
    Scheduler& scheduler;
    vk::Device device;
    vk::UniqueQueryPool query_pool{};
    std::vector<Slot> slots;
    std::vector<u32> free_slots;
    std::deque<u32> active_slots;
    vk::UniqueQueryPool compute_query_pool{};
    std::vector<ComputeSlot> compute_slots;
    std::vector<u32> compute_free_slots;
    std::deque<u32> compute_active_slots;
    std::map<std::pair<u64, bool>, ComputeStats> interval_compute_stats;
    vk::UniqueQueryPool draw_query_pool{};
    std::vector<DrawSlot> draw_slots;
    std::vector<u32> draw_free_slots;
    std::deque<u32> draw_active_slots;
    std::map<std::pair<std::pair<u64, u64>, std::pair<bool, bool>>, DrawStats> interval_draw_stats;
    std::chrono::steady_clock::time_point report_start{std::chrono::steady_clock::now()};
    float timestamp_period_ns{};
    u64 timestamp_mask{};
    u64 interval_draws{};
    u64 interval_dispatches{};
    u64 interval_doc_seen{};
    u64 interval_doc_sampled{};
    u64 interval_doc_completed{};
    u64 interval_doc_dropped{};
    u64 interval_doc_groups{};
    u64 interval_query_errors{};
    u64 total_doc_dropped{};
    u64 current_frame_doc_seen{};
    u64 interval_compute_seen{};
    u64 interval_compute_sampled{};
    u64 interval_compute_completed{};
    u64 interval_compute_dropped{};
    u64 interval_compute_query_errors{};
    u64 interval_draw_seen{};
    u64 interval_draw_sampled{};
    u64 interval_draw_completed{};
    u64 interval_draw_dropped{};
    u64 interval_draw_query_errors{};
    double interval_gpu_collect_ms{};
    double interval_gpu_prefix_ms{};
    double interval_gpu_replay_ms{};
    double interval_gpu_total_ms{};
    double interval_compute_gpu_ms{};
    double interval_draw_gpu_ms{};
    u32 timestamp_valid_bits{};
    u32 commands_since_poll{};
    u32 report_frame{};
    u32 current_frame{};
    bool requested{};
    bool all_compute_requested{};
    bool all_draw_requested{};
    bool initialization_attempted{};
    bool initialized{};
    bool compute_initialization_attempted{};
    bool compute_initialized{};
    bool draw_initialization_attempted{};
    bool draw_initialized{};
};

static bool TraceDreamsVolumeResources() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_VOLUME_TRACE");
        return value != nullptr && std::string_view{value} != "0";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static bool UseDreamsTraversalTurnstile() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_ORDERED_COUNT_TURNSTILE");
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static bool OrderDreamsIndirectTraversal() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_ORDER_INDIRECT");
        // DS_ORDERED_COUNT must observe wave-creation order. The traversal shader has exactly one
        // 64-lane guest wave per workgroup, so dispatching indirect workgroups individually is a
        // correctness diagnostic without a cross-workgroup GPU spin lock. It is far too expensive
        // for normal execution: a live edit-mode A/B measured 3.48 FPS serialized versus 9.97 FPS
        // with the native indirect dispatch, with no visible regression. Keep it opt-in while the
        // ordered-count lowering is implemented in the shader path.
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled || UseDreamsTraversalTurnstile();
}

static u32 DreamsTraversalBatchSize() {
    static const u32 batch_size = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_ORDERED_COUNT_BATCH");
        if (value == nullptr || value[0] == '\0') {
            return UseDreamsTraversalTurnstile() ? 32U : 1U;
        }
        char* end{};
        const u64 parsed = std::strtoull(value, &end, 10);
        return end != value ? static_cast<u32>(std::clamp<u64>(parsed, 1, 64)) : 1U;
    }();
    return batch_size;
}

static void ResetDreamsTraversalTurn(vk::CommandBuffer cmdbuf, vk::Buffer gds_buffer) {
    constexpr vk::DeviceSize TurnOffset = Shader::DreamsCompat::OrderedBaseSlotsDword * sizeof(u32);
    const vk::BufferMemoryBarrier2 before_reset{
        .srcStageMask = vk::PipelineStageFlagBits2::eAllCommands,
        .srcAccessMask = vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite,
        .dstStageMask = vk::PipelineStageFlagBits2::eTransfer,
        .dstAccessMask = vk::AccessFlagBits2::eTransferWrite,
        .buffer = gds_buffer,
        .offset = TurnOffset,
        .size = sizeof(u32),
    };
    cmdbuf.pipelineBarrier2(vk::DependencyInfo{
        .bufferMemoryBarrierCount = 1,
        .pBufferMemoryBarriers = &before_reset,
    });
    cmdbuf.fillBuffer(gds_buffer, TurnOffset, sizeof(u32), 0);
    const vk::BufferMemoryBarrier2 after_reset{
        .srcStageMask = vk::PipelineStageFlagBits2::eTransfer,
        .srcAccessMask = vk::AccessFlagBits2::eTransferWrite,
        .dstStageMask = vk::PipelineStageFlagBits2::eComputeShader,
        .dstAccessMask = vk::AccessFlagBits2::eShaderRead | vk::AccessFlagBits2::eShaderWrite,
        .buffer = gds_buffer,
        .offset = TurnOffset,
        .size = sizeof(u32),
    };
    cmdbuf.pipelineBarrier2(vk::DependencyInfo{
        .bufferMemoryBarrierCount = 1,
        .pBufferMemoryBarriers = &after_reset,
    });
}

static bool OrderDreamsSceneCompact() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_SCENE_COMPACT_ORDERED");
        // SceneCompact reuses the same 64 ordered-count slots in every workgroup. Liverpool
        // processes those waves in creation order; native Vulkan workgroups may reach the shared
        // counters in any order. Full workgroup serialization is only a diagnostic because this
        // shader runs frequently and the resulting command expansion destroys frame rate.
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

