struct DreamsD25CaptureWindowConfig {
    u32 count{1};
    bool configured{};
};

struct DreamsD25CaptureWindowState {
    bool active{};
    bool use_occurrence_directories{};
    u32 total{1};
    u32 remaining{};
    u32 occurrence_index{};
    bool direct_draw_mode{};
    std::vector<u64> zero_output_producer_signatures;
};

static DreamsD25CaptureWindowState g_dreams_d25_capture_window;

static DreamsD25CaptureWindowConfig GetDreamsD25CaptureWindowConfig() {
    static const DreamsD25CaptureWindowConfig config = [] {
        DreamsD25CaptureWindowConfig value;
        const char* text = std::getenv("SHADPS4_DREAMS_D25_CAPTURE_WINDOW");
        if (text == nullptr || text[0] == '\0') {
            return value;
        }
        value.configured = true;
        char* end{};
        const u64 parsed = std::strtoull(text, &end, 0);
        if (end == text || *end != '\0' || parsed == 0) {
            LOG_WARNING(Render_Vulkan, "Invalid SHADPS4_DREAMS_D25_CAPTURE_WINDOW='{}'; using 1",
                        text);
            return value;
        }
        value.count = static_cast<u32>(std::min<u64>(parsed, 64));
        if (parsed > 64) {
            LOG_WARNING(Render_Vulkan, "SHADPS4_DREAMS_D25_CAPTURE_WINDOW={} capped to 64", parsed);
        }
        return value;
    }();
    return config;
}

static bool DreamsGeometryTraceTriggerExists() {
    const char* trigger_file = std::getenv("SHADPS4_DREAMS_GEOMETRY_TRACE_TRIGGER_FILE");
    if (trigger_file == nullptr || trigger_file[0] == '\0') {
        return false;
    }
    std::error_code error;
    return std::filesystem::exists(trigger_file, error) && !error;
}

static std::optional<std::filesystem::path> DreamsSlowDrawCaptureDirectory() {
    if (!TraceDreamsSlowDrawArgs()) {
        return std::nullopt;
    }
    const char* value = std::getenv("SHADPS4_DREAMS_SLOW_DRAW_CAPTURE_DIR");
    if (value == nullptr || value[0] == '\0') {
        return std::nullopt;
    }
    std::filesystem::path directory{value};
    const auto window_config = GetDreamsD25CaptureWindowConfig();
    const bool initial_window_producer = !g_dreams_d25_capture_window.active &&
                                         window_config.configured &&
                                         DreamsGeometryTraceTriggerExists();
    if ((g_dreams_d25_capture_window.active &&
         g_dreams_d25_capture_window.use_occurrence_directories) ||
        initial_window_producer) {
        const u32 occurrence =
            g_dreams_d25_capture_window.active ? g_dreams_d25_capture_window.occurrence_index : 0;
        directory /= fmt::format("occ{:03}", occurrence);
    }
    std::error_code error;
    std::filesystem::create_directories(directory, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Failed to create Dreams slow-draw capture directory {}: {}",
                  directory.string(), error.message());
        return std::nullopt;
    }
    return directory;
}

