static u32 DreamsVisibilityListTraceLimit() {
    static const u32 limit = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_VISIBILITY_LIST_TRACE_LIMIT");
        if (value == nullptr || value[0] == '\0') {
            return 16U;
        }
        char* end{};
        const u64 parsed = std::strtoull(value, &end, 10);
        return end != value ? static_cast<u32>(std::clamp<u64>(parsed, 1, 64)) : 16U;
    }();
    return limit;
}

static u32 g_dreams_visibility_list_trace_remaining{};
static u32 g_dreams_visibility_list_trace_ordinal{};
static bool g_dreams_visibility_list_trace_initialized{};

static bool ConsumeDreamsVisibilityListTraceRequest() {
    if (!TraceDreamsVisibilityLists()) {
        return false;
    }

    const char* trigger_file = std::getenv("SHADPS4_DREAMS_VISIBILITY_LIST_TRACE_TRIGGER_FILE");
    if (trigger_file != nullptr && trigger_file[0] != '\0') {
        std::error_code error;
        if (std::filesystem::remove(trigger_file, error)) {
            g_dreams_visibility_list_trace_remaining = DreamsVisibilityListTraceLimit();
            LOG_WARNING(Render_Vulkan, "Dreams visibility list trace armed for {} dispatches",
                        g_dreams_visibility_list_trace_remaining);
        }
    } else if (!g_dreams_visibility_list_trace_initialized) {
        g_dreams_visibility_list_trace_initialized = true;
        g_dreams_visibility_list_trace_remaining = DreamsVisibilityListTraceLimit();
        LOG_WARNING(Render_Vulkan, "Dreams visibility list trace auto-armed for {} dispatches",
                    g_dreams_visibility_list_trace_remaining);
    }

    if (g_dreams_visibility_list_trace_remaining == 0) {
        return false;
    }
    --g_dreams_visibility_list_trace_remaining;
    return true;
}

static u64 HashDreamsTraceWords(std::span<const u32> words) {
    u64 hash = 1469598103934665603ULL;
    for (const u32 word : words) {
        hash ^= word;
        hash *= 1099511628211ULL;
    }
    return hash;
}

static u64 HashDreamsTraceBytes(std::span<const u8> bytes) {
    u64 hash = 1469598103934665603ULL;
    for (const u8 byte : bytes) {
        hash ^= byte;
        hash *= 1099511628211ULL;
    }
    return hash;
}

// Host-only inventory of the exact visibility-list slice consumed by VS 0x3706083c. This is
// deliberately independent of CaptureVs370Interface(): setting this directory must not change
// shader translation, allocate private GDS, build a diagnostic pipeline, or replay a framebuffer.
struct DreamsVs370ListSliceProducerSnapshot {
    bool descriptor_valid{};
    u64 dispatch_sequence{};
    u64 shader_hash{};
    VAddr args_address{};
    VAddr output_base{};
    u64 output_size{};
    u32 output_stride{};
    u32 output_capacity_records{};
    u32 dispatch_initiator{};
    std::array<u32, 3> start{};
    std::array<u32, 3> threads{};
    std::array<u32, 4> raw_output_descriptor{};
    // Bindings 1 and 2 are the candidate-selector and source-lookup inputs for 7aa925e9.
    // Retain their exact descriptors without reading or fencing them at dispatch time. Their
    // contents are not immutable, so a later consumer-side capture must not claim these
    // descriptors alone prove the bytes which the producer consumed.
    std::array<bool, 2> upstream_descriptor_valid{};
    std::array<VAddr, 2> upstream_base{};
    std::array<u64, 2> upstream_size{};
    std::array<u32, 2> upstream_stride{};
    std::array<std::array<u32, 4>, 2> raw_upstream_descriptors{};
};

struct DreamsVs370ListSlicePendingDraw {
    bool ready{};
    u64 vertex_shader{};
    u64 fragment_shader{};
    VAddr command_address{};
    VAddr count_address{};
    u32 indirect_count{};
    VkDrawIndexedIndirectCommand command{};
    u32 shader_instance_base{};
    u64 first_record{};
    u64 end_record{};
    u64 compute_sequence_at_draw{};
    AmdGpu::Buffer b0{};
    AmdGpu::Buffer b3{};
    DreamsVs370ListSliceProducerSnapshot producer{};
    VAddr slice_address{};
    u64 slice_offset{};
    u64 slice_bytes{};
    bool gpu_modified_before_read{};
    u64 guest_words_before_hash{};
    std::vector<u32> guest_words_before;
    u64 bound_source_offset{};
    u64 bound_source_range{};
    u64 bound_logical_base_offset{};
    u64 bound_slice_relative_offset{};
    u64 b0_bound_source_offset{};
    u64 b0_bound_source_range{};
    u64 b0_bound_logical_base_offset{};
    std::vector<u8> b0_rows_0_through_10;
};

struct DreamsVs370ListSliceCaptureState {
    bool armed{};
    bool complete{};
    bool failed{};
    std::filesystem::path directory;
    std::vector<DreamsVs370ListSliceProducerSnapshot> producers;
};

static DreamsVs370ListSliceCaptureState g_dreams_vs370_list_slice_capture{};

static std::optional<std::filesystem::path> DreamsVs370ListSliceCaptureDirectory() {
    const char* value = std::getenv("SHADPS4_DREAMS_VS370_LIST_SLICE_CAPTURE_DIR");
    if (value == nullptr || value[0] == '\0') {
        return std::nullopt;
    }
    return std::filesystem::path{value};
}

static bool PollDreamsVs370ListSliceCaptureRequest() {
    auto& capture = g_dreams_vs370_list_slice_capture;
    if (Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return false;
    }
    if (capture.armed) {
        return true;
    }
    const auto directory = DreamsVs370ListSliceCaptureDirectory();
    if (!directory) {
        return false;
    }
    std::error_code error;
    const auto request = *directory / "capture.request";
    if (!std::filesystem::is_regular_file(request, error) || error) {
        return false;
    }
    error.clear();
    std::filesystem::create_directories(*directory, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Dreams VS370 list-slice capture cannot create {}: {}",
                  directory->string(), error.message());
        return false;
    }
    if (!std::filesystem::remove(request, error) || error) {
        LOG_ERROR(Render_Vulkan, "Dreams VS370 list-slice request cannot be consumed: {}",
                  error.message());
        return false;
    }
    error.clear();
    std::filesystem::remove(*directory / "complete.txt", error);
    error.clear();
    std::filesystem::remove(*directory / "failed.txt", error);
    error.clear();
    std::filesystem::remove(*directory / "complete.txt.tmp", error);
    capture = {};
    capture.armed = true;
    capture.directory = *directory;
    LOG_WARNING(Render_Vulkan,
                "Dreams VS370 list-slice capture armed for the first matching indexed draw");
    return true;
}

// Proof-grade one-shot lineage for the current sculpt visibility chain.  B535 contributes only
// its existing fixed-slot membership trace; d8 and 7aa payloads are read from the exact Vulkan
// buffers bound to those dispatches.  It intentionally stops at 7aa and therefore does not turn
// on the old VS370 interface capture or its 512-instance GDS envelope.
struct DreamsUpstreamB535Record {
    u32 pass{};
    u32 workgroup{};
    u32 lane{};
    u32 identity{};
    u32 record{};
    u32 output_role{};
    u32 output_index{};
    u32 flags{};
};

