    Phase phase{Phase::WaitingForB535};
    std::filesystem::path directory;
    u64 b535_first_sequence{};
    u64 b535_final_sequence{};
    std::vector<DreamsUpstreamB535Record> b535_records;
    VAddr d8_args_address{};
    u32 d8_next_pass{};
