// One exact producer/draw pair is sufficient for the isolated one-cube discriminator. Keeping
// this capture single-shot avoids seven additional GPU fences and duplicate fixture replays.
constexpr u32 DreamsVs370InterfaceCaptureOccurrences = 1;

struct DreamsVs370InterfaceCaptureState {
    bool armed{};
    bool complete{};
    bool failed{};
    u32 captured{};
    u32 group_count{};
    std::array<std::array<u32, 14>, DreamsVs370InterfaceCaptureOccurrences> pass_keys{};
    std::array<u32, DreamsVs370InterfaceCaptureOccurrences> pass_groups{};
    std::array<u64, DreamsVs370InterfaceCaptureOccurrences> input_hashes{};
    std::array<u64, DreamsVs370InterfaceCaptureOccurrences> interface_hashes{};
    std::array<bool, DreamsVs370InterfaceCaptureOccurrences> validity_complete{};
};

static DreamsVs370InterfaceCaptureState g_dreams_vs370_interface_capture{};

struct DreamsB535MembershipCaptureState {
    bool active{};
    bool complete{};
    bool failed{};
    u32 pass_count{};
    std::array<std::array<u32, 3>, B535Capture::MaxPasses> dims{};
    std::array<u64, B535Capture::MaxPasses> sequences{};
    // Exact input records which B535 explicitly rejected. Keep these alive until the matching
    // VS370 fixture is captured so the offline renderer can test them without fabricating data.
    std::vector<std::array<u32, 2>> dropped_records;
    // Every unique B535 input pair, including parents, children, terminals, and rejects. The
    // matching VS370 draw snapshots their keyed backing rows so offline candidate replay can test
    // genuine guest records instead of guessing record contents.
    std::vector<std::array<u32, 2>> input_records;
};

static DreamsB535MembershipCaptureState g_dreams_b535_membership_capture{};

static std::optional<std::filesystem::path> DreamsB535MembershipCaptureDirectory() {
    const char* value = std::getenv("SHADPS4_DREAMS_B535_MEMBERSHIP_CAPTURE_DIR");
    std::filesystem::path output;
    if (value != nullptr && value[0] != '\0') {
        output = value;
    } else if (const char* ordered_chain =
                   std::getenv("SHADPS4_DREAMS_ORDERED_CHAIN_CAPTURE_DIR");
               ordered_chain != nullptr && ordered_chain[0] != '\0') {
        output = std::filesystem::path{ordered_chain} / "b535-membership";
    } else if (const auto upstream = DreamsUpstreamLineageCaptureDirectory()) {
        output = *upstream / "b535-membership";
    } else {
        return std::nullopt;
    }
    std::error_code error;
    std::filesystem::create_directories(output, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Failed to create B535 membership capture directory {}: {}",
                  output.string(), error.message());
        return std::nullopt;
    }
    return output;
}

static bool PollDreamsB535MembershipCaptureTrigger() {
    auto& capture = g_dreams_b535_membership_capture;
    if (!Shader::DreamsCompat::CaptureB535Membership() || capture.active || capture.failed ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return capture.active;
    }
    std::error_code error;
    bool explicitly_triggered{};
    const char* trigger = std::getenv("SHADPS4_DREAMS_B535_MEMBERSHIP_CAPTURE_TRIGGER_FILE");
    if (trigger != nullptr && trigger[0] != '\0') {
        explicitly_triggered = std::filesystem::remove(trigger, error);
        error.clear();
    }
    bool ordered_chain_triggered{};
    if (const char* ordered_chain = std::getenv("SHADPS4_DREAMS_ORDERED_CHAIN_CAPTURE_DIR");
        ordered_chain != nullptr && ordered_chain[0] != '\0') {
        ordered_chain_triggered = !Shader::DreamsCompat::CaptureA3LookupProducerTrace() &&
            std::filesystem::is_regular_file(std::filesystem::path{ordered_chain} /
                                                 "capture.request",
                                             error) &&
            !error;
    }
    bool upstream_triggered{};
    if (const auto upstream = DreamsUpstreamLineageCaptureDirectory()) {
        const auto request = *upstream / "capture.request";
        error.clear();
        if (std::filesystem::is_regular_file(request, error) && !error) {
            error.clear();
            upstream_triggered = std::filesystem::remove(request, error) && !error;
        }
    }
    if ((!explicitly_triggered && !ordered_chain_triggered && !upstream_triggered) ||
        (capture.complete && ordered_chain_triggered && !explicitly_triggered)) {
        return false;
    }
    const auto directory = DreamsB535MembershipCaptureDirectory();
    if (!directory) {
        capture.failed = true;
        return false;
    }
    // A completed capture may be retriggered for the far/near counterpart. Remove only marker
    // files up front so a watcher cannot mistake the previous run for the newly armed one.
    std::filesystem::remove(*directory / "complete.txt", error);
    error.clear();
    std::filesystem::remove(*directory / "failed.txt", error);
    capture = {};
    capture.active = true;
    if (upstream_triggered) {
        const auto upstream = DreamsUpstreamLineageCaptureDirectory();
        if (!upstream) {
            capture.active = false;
            capture.failed = true;
            return false;
        }
        std::filesystem::create_directories(*upstream, error);
        if (error) {
            capture.active = false;
            capture.failed = true;
            LOG_ERROR(Render_Vulkan, "Dreams upstream lineage directory cannot be created: {}",
                      error.message());
            return false;
        }
        error.clear();
        std::filesystem::remove(*upstream / "complete.txt", error);
        error.clear();
        std::filesystem::remove(*upstream / "complete.txt.tmp", error);
        error.clear();
        std::filesystem::remove(*upstream / "failed.txt", error);
        auto& lineage = g_dreams_upstream_lineage_capture;
        lineage = {};
        lineage.phase = DreamsUpstreamLineageCaptureState::Phase::CapturingB535;
        lineage.directory = *upstream;
        LOG_WARNING(Render_Vulkan,
                    "Dreams upstream lineage capture armed at the next nonzero B535 chain");
    }
    LOG_WARNING(Render_Vulkan,
                "Dreams B535 membership capture armed for one nonzero traversal chain");
    return true;
}

