static std::optional<std::filesystem::path> DreamsCe3CoverageTraceDirectory() {
    const char* value = std::getenv("SHADPS4_DREAMS_CE3_COVERAGE_CAPTURE_DIR");
    if (value == nullptr || value[0] == '\0') {
        return std::nullopt;
    }
    std::filesystem::path output{value};
    std::error_code error;
    std::filesystem::create_directories(output, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Failed to create ce3 coverage trace directory {}: {}",
                  output.string(), error.message());
        return std::nullopt;
    }
    return output;
}

static bool DreamsCe3CoverageTraceRequested() {
    const auto directory = DreamsCe3CoverageTraceDirectory();
    if (!directory) {
        return false;
    }
    std::error_code error;
    return std::filesystem::is_regular_file(*directory / "capture.request", error) && !error;
}

static bool PollDreamsVs370InterfaceCaptureTrigger(bool matched_ordered_chain_producer = false) {
    auto& capture = g_dreams_vs370_interface_capture;
    if (!Shader::DreamsCompat::CaptureVs370Interface() || capture.complete || capture.failed ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301" ||
        (!matched_ordered_chain_producer && !DreamsOrderedChainAllowsVsCapture())) {
        return false;
    }
    if (capture.armed) {
        return true;
    }
    const char* trigger = std::getenv("SHADPS4_DREAMS_VS370_INTERFACE_CAPTURE_TRIGGER_FILE");
    if (trigger != nullptr && trigger[0] != '\0') {
        std::error_code error;
        if (!std::filesystem::remove(trigger, error)) {
            return false;
        }
    }
    capture.armed = true;
    LOG_WARNING(Render_Vulkan,
                "Dreams VS370 interface capture armed for {} exact nonzero sculpt draws",
                DreamsVs370InterfaceCaptureOccurrences);
    return true;
}

static bool WriteDreamsCaptureText(const std::filesystem::path& file, std::string_view text);

static void FailDreamsVs370InterfaceCapture(std::string_view reason) {
    auto& capture = g_dreams_vs370_interface_capture;
    capture.failed = true;
    capture.armed = false;
    LOG_ERROR(Render_Vulkan, "Dreams VS370 interface capture failed: {}", reason);
    if (const auto directory = DreamsVs370InterfaceCaptureDirectory()) {
        WriteDreamsCaptureText(*directory / "failed.txt", fmt::format("{}\n", reason));
    }
}

static bool WriteDreamsCaptureBytes(const std::filesystem::path& file, std::span<const u8> bytes,
                                    u64& hash) {
    hash = HashDreamsTraceBytes(bytes);
    std::ofstream output(file, std::ios::binary | std::ios::trunc);
    if (!output) {
        LOG_ERROR(Render_Vulkan, "Failed to open Dreams capture file {}", file.string());
        return false;
    }
    output.write(reinterpret_cast<const char*>(bytes.data()),
                 static_cast<std::streamsize>(bytes.size()));
    if (!output) {
        LOG_ERROR(Render_Vulkan, "Failed to write Dreams capture file {}", file.string());
        return false;
    }
    return true;
}

static bool WriteDreamsCaptureWords(const std::filesystem::path& file, std::span<const u32> words,
                                    u64& hash) {
    return WriteDreamsCaptureBytes(
        file, std::span<const u8>{reinterpret_cast<const u8*>(words.data()), words.size_bytes()},
        hash);
}

static bool AppendDreamsCaptureText(const std::filesystem::path& file, std::string_view text) {
    std::ofstream output(file, std::ios::binary | std::ios::app);
    if (!output) {
        LOG_ERROR(Render_Vulkan, "Failed to open Dreams capture metadata {}", file.string());
        return false;
    }
    output.write(text.data(), static_cast<std::streamsize>(text.size()));
    if (!output) {
        LOG_ERROR(Render_Vulkan, "Failed to write Dreams capture metadata {}", file.string());
        return false;
    }
    return true;
}

static bool WriteDreamsCaptureText(const std::filesystem::path& file, std::string_view text) {
    std::ofstream output(file, std::ios::binary | std::ios::trunc);
    if (!output) {
        LOG_ERROR(Render_Vulkan, "Failed to open Dreams capture metadata {}", file.string());
        return false;
    }
    output.write(text.data(), static_cast<std::streamsize>(text.size()));
    if (!output) {
        LOG_ERROR(Render_Vulkan, "Failed to write Dreams capture metadata {}", file.string());
        return false;
    }
    return true;
}

static bool VerifyDreamsCaptureBytes(const std::filesystem::path& file,
                                     std::span<const u8> expected, u64 expected_hash) {
    std::error_code error;
    if (!std::filesystem::is_regular_file(file, error) || error ||
        std::filesystem::file_size(file, error) != expected.size() || error) {
        LOG_ERROR(Render_Vulkan, "Dreams capture verification could not stat {}", file.string());
        return false;
    }
    std::vector<u8> actual(expected.size());
    std::ifstream input(file, std::ios::binary);
    if (!input) {
        LOG_ERROR(Render_Vulkan, "Dreams capture verification could not open {}", file.string());
        return false;
    }
    input.read(reinterpret_cast<char*>(actual.data()), static_cast<std::streamsize>(actual.size()));
    if (!input || HashDreamsTraceBytes(actual) != expected_hash ||
        !std::ranges::equal(actual, expected)) {
        LOG_ERROR(Render_Vulkan, "Dreams capture verification failed for {}", file.string());
        return false;
    }
    return true;
}

static bool WriteDreamsCaptureCompletionMarker(const std::filesystem::path& directory) {
    static constexpr std::string_view CompleteText = "complete\n";
    const auto temporary = directory / "complete.txt.tmp";
    const auto complete = directory / "complete.txt";
    std::error_code error;
    std::filesystem::remove(temporary, error);
    if (!WriteDreamsCaptureText(temporary, CompleteText)) {
        return false;
    }
    error.clear();
    std::filesystem::remove(complete, error);
    error.clear();
    std::filesystem::rename(temporary, complete, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Dreams completion marker rename failed for {}: {}",
                  complete.string(), error.message());
        return false;
    }
    const std::span<const u8> expected{
        reinterpret_cast<const u8*>(CompleteText.data()), CompleteText.size()};
    const bool verified =
        VerifyDreamsCaptureBytes(complete, expected, HashDreamsTraceBytes(expected));
    if (!verified) {
        error.clear();
        std::filesystem::remove(complete, error);
    }
    return verified;
}

static bool WriteDreamsCaptureRequestMarker(const std::filesystem::path& directory) {
    static constexpr std::string_view RequestText = "capture\n";
    const auto temporary = directory / "capture.request.tmp";
    const auto request = directory / "capture.request";
    const std::span<const u8> expected{
        reinterpret_cast<const u8*>(RequestText.data()), RequestText.size()};
    std::error_code error;
    if (std::filesystem::is_regular_file(request, error) && !error) {
        return VerifyDreamsCaptureBytes(request, expected, HashDreamsTraceBytes(expected));
    }
    error.clear();
    std::filesystem::remove(temporary, error);
    if (!WriteDreamsCaptureText(temporary, RequestText)) {
        return false;
    }
    if (!VerifyDreamsCaptureBytes(temporary, expected, HashDreamsTraceBytes(expected))) {
        return false;
    }
    error.clear();
    std::filesystem::rename(temporary, request, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Dreams capture request rename failed for {}: {}",
                  request.string(), error.message());
        return false;
    }
    return VerifyDreamsCaptureBytes(request, expected, HashDreamsTraceBytes(expected));
}

static std::string_view DreamsSculptAtlasLineagePhaseName(
    DreamsSculptAtlasLineageCapture::Phase phase) {
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    switch (phase) {
    case Phase::WaitingRequest:
        return "waiting-request";
    case Phase::Capturing84aa:
        return "capturing-84aa";
    case Phase::Waiting2f:
        return "waiting-2f";
    case Phase::WaitingF030:
        return "waiting-f030";
    case Phase::Complete:
        return "complete";
    case Phase::Failed:
        return "failed";
    }
    return "invalid";
}

static void FailDreamsSculptAtlasLineage(std::string_view reason) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    if (capture.phase == DreamsSculptAtlasLineageCapture::Phase::Complete ||
        capture.phase == DreamsSculptAtlasLineageCapture::Phase::Failed) {
        return;
    }
    const auto previous_phase = capture.phase;
    capture.phase = DreamsSculptAtlasLineageCapture::Phase::Failed;
    LOG_ERROR(Render_Vulkan, "Dreams sculpt-atlas lineage capture failed at {}: {}",
              DreamsSculptAtlasLineagePhaseName(previous_phase), reason);
    const auto directory = !capture.directory.empty() ? capture.directory : capture.root;
    bool marker_written{};
    if (!directory.empty()) {
        std::error_code error;
        std::filesystem::remove(directory / "complete.txt", error);
        marker_written = WriteDreamsCaptureText(
            directory / "failed.txt",
            fmt::format("phase\t{}\nreason\t{}\nproducer_sequence\t{}\n",
                        DreamsSculptAtlasLineagePhaseName(previous_phase), reason,
                        capture.producer_sequence));
    }
    if (!marker_written && !capture.root.empty() && directory != capture.root) {
        marker_written = WriteDreamsCaptureText(
            capture.root / "failed.txt",
            fmt::format("phase\t{}\nreason\t{}\nproducer_sequence\t{}\n",
                        DreamsSculptAtlasLineagePhaseName(previous_phase), reason,
                        capture.producer_sequence));
    }
    if (!marker_written) {
        LOG_ERROR(Render_Vulkan, "Dreams sculpt-atlas lineage failure marker could not be written");
    }
}

static void CheckDreamsSculptAtlasLineageDeadline(u64 sequence) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    if (!Shader::DreamsCompat::CaptureSculptAtlasLineage() ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301" ||
        capture.phase == Phase::Complete || capture.phase == Phase::Failed) {
        return;
    }
    // WaitingRequest owns no GPU resources and is bounded by the external one-shot runner. Dreams
    // can execute well over 8192 compute dispatches during bootstrap before its first eligible
    // 84aa, so a GPU-sequence deadline here would discard a correctly pre-armed request.
    if ((capture.phase == Phase::Waiting2f || capture.phase == Phase::WaitingF030) &&
        capture.deadline_sequence != 0 && sequence > capture.deadline_sequence) {
        FailDreamsSculptAtlasLineage(fmt::format(
            "expected same-atlas consumer did not arrive before dispatch sequence {}",
            capture.deadline_sequence));
    }
}

static bool RetryDreamsSculptAtlasLineageAfterEmptyProducer(std::string_view reason) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    if (capture.phase != Phase::Capturing84aa) {
        return false;
    }
    const u32 completed_attempts = capture.producer_attempts + 1;
    if (completed_attempts >= DreamsSculptAtlasLineageMaxProducerAttempts) {
        FailDreamsSculptAtlasLineage(
            fmt::format("{} after {} bounded producer attempts", reason, completed_attempts));
        return false;
    }
    const auto root = capture.root;
    const auto directory = capture.directory;
    const auto skipped_text =
        fmt::format("status\tskipped\nreason\t{}\nproducer_sequence\t{}\nproducer_groups\t{}\n"
                    "completed_attempts\t{}\n",
                    reason, capture.producer_sequence, capture.producer_groups,
                    completed_attempts);
    const std::span<const u8> skipped_bytes{reinterpret_cast<const u8*>(skipped_text.data()),
                                            skipped_text.size()};
    const auto skipped_file = directory / "skipped.txt";
    if (directory.empty() || !WriteDreamsCaptureText(skipped_file, skipped_text) ||
        !VerifyDreamsCaptureBytes(skipped_file, skipped_bytes,
                                 HashDreamsTraceBytes(skipped_bytes))) {
        FailDreamsSculptAtlasLineage("failed to record an empty producer attempt");
        return false;
    }
    if (!WriteDreamsCaptureRequestMarker(root)) {
        FailDreamsSculptAtlasLineage("failed to re-arm after an empty producer attempt");
        return false;
    }

    DreamsSculptAtlasLineageCapture next{};
    next.root = root;
    next.producer_attempts = completed_attempts;
    capture = std::move(next);
    LOG_WARNING(Render_Vulkan,
                "Dreams sculpt-atlas lineage skipped empty 84aa attempt {}/{} and remains armed",
                completed_attempts, DreamsSculptAtlasLineageMaxProducerAttempts);
    return true;
}

static bool AppendDreamsSculptAtlasLineageEvent(std::string_view stage, u64 sequence,
                                                std::string_view relation,
                                                std::string_view decision) {
    const auto& capture = g_dreams_sculpt_atlas_lineage;
    return !capture.directory.empty() &&
           AppendDreamsCaptureText(capture.directory / "events.tsv",
                                   fmt::format("{}\t{}\t{}\t{}\t{}\n",
                                               DreamsSculptAtlasLineagePhaseName(capture.phase),
                                               stage, sequence, relation, decision));
}

static bool BeginDreamsSculptAtlasLineageIfRequested(u64 sequence, u32 groups, bool exact_doc,
                                                      const DreamsAtlasImageIdentity& producer) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    if (!Shader::DreamsCompat::CaptureSculptAtlasLineage() ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return false;
    }
    if (capture.phase != Phase::WaitingRequest) {
        if ((capture.phase == Phase::Waiting2f || capture.phase == Phase::WaitingF030) &&
            SameDreamsAtlasBacking(capture.producer_image, producer)) {
            AppendDreamsSculptAtlasLineageEvent("84aa", sequence, "same_atlas",
                                                "fail_intervening_writer");
            FailDreamsSculptAtlasLineage(
                fmt::format("intervening 84aa sequence {} rewrote the tracked atlas before {}",
                            sequence, DreamsSculptAtlasLineagePhaseName(capture.phase)));
        }
        return false;
    }
    if (capture.root.empty()) {
        const char* value = std::getenv("SHADPS4_DREAMS_SCULPT_ATLAS_LINEAGE_CAPTURE_DIR");
        if (value == nullptr || value[0] == '\0') {
            return false;
        }
        capture.root = std::filesystem::path{value};
    }

    // Leave the request in place until an exact, safely bounded producer dispatch is available.
    // Consuming it earlier could turn an ineligible 84aa into the lineage generation by accident.
    if (!exact_doc || !producer.valid || groups == 0 ||
        groups > DreamsSculptAtlasLineageMax84aaGroups) {
        return false;
    }

    const auto trigger = capture.root / "capture.request";
    std::error_code error;
    if (!std::filesystem::is_regular_file(trigger, error) || error) {
        return false;
    }
    error.clear();
    if (!std::filesystem::remove(trigger, error) || error) {
        LOG_ERROR(Render_Vulkan, "Dreams sculpt-atlas lineage trigger {} could not be consumed: {}",
                  trigger.string(), error.message());
        return false;
    }

    capture.producer_sequence = sequence;
    capture.deadline_sequence = sequence + DreamsSculptAtlasLineageMaxDispatchGap;
    capture.producer_groups = groups;
    const auto nonce = std::chrono::system_clock::now().time_since_epoch().count();
    capture.directory = capture.root / fmt::format("capture-{}-{}", sequence, nonce);
    error.clear();
    if (!std::filesystem::create_directory(capture.directory, error) || error) {
        capture.phase = Phase::Capturing84aa;
        FailDreamsSculptAtlasLineage(fmt::format("could not create unique capture directory {}: {}",
                                                 capture.directory.string(), error.message()));
        return false;
    }
    capture.phase = Phase::Capturing84aa;
    const bool files_ok =
        WriteDreamsCaptureText(
            capture.directory / "started.tsv",
            fmt::format("schema\t1\nproducer_sequence\t{}\n84aa_groups\t{}\n"
                        "producer_attempt\t{}\nmax_producer_attempts\t{}\n"
                        "max_84aa_groups\t{}\nmax_consumer_attempts\t{}\n"
                        "max_f030_records\t{}\nmax_f030_waves\t{}\n"
                        "max_consumer_invocations\t{}\n"
                        "sample_window\twg_xyz_lt_4_local_xyz_lt_2\n"
                        "max_candidates_per_site\t{}\n",
                        sequence, groups, capture.producer_attempts + 1,
                        DreamsSculptAtlasLineageMaxProducerAttempts,
                        DreamsSculptAtlasLineageMax84aaGroups,
                        DreamsSculptAtlasLineageMaxConsumerAttempts,
                        DreamsSculptAtlasLineageMaxF030Records,
                        DreamsSculptAtlasLineageMaxF030Waves,
                        DreamsSculptAtlasLineageMaxConsumerInvocations,
                        Shader::DreamsCompat::ImageGather3DSampleWindow::MaxCandidatesPerSite)) &&
        WriteDreamsCaptureText(
            capture.directory / "resource-mismatches.tsv",
            "attempt\tshader\tvalid\tbinding\timage_id\timage_uid\tbacking\t"
            "descriptor_base\tguest_base\twidth\theight\tdepth\tview_format\n") &&
        WriteDreamsCaptureText(capture.directory / "events.tsv",
                               "phase\tstage\tsequence\trelation\tdecision\n");
    if (!files_ok) {
        FailDreamsSculptAtlasLineage("failed to write capture-start metadata");
        return false;
    }
    LOG_WARNING(Render_Vulkan,
                "Dreams sculpt-atlas lineage accepted request directory={} sequence={} groups={}",
                capture.directory.string(), sequence, groups);
    return true;
}

static bool RecordDreamsSculptAtlasLineageProducer(const DreamsAtlasImageIdentity& identity,
                                                   std::span<const u32> groups,
                                                   std::span<const u32> destinations,
                                                   std::span<const vk::Offset3D> offsets,
                                                   std::span<const u8> expected,
                                                   std::span<const u8> actual) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    constexpr u64 BrickBytes = 8 * 8 * 8;
    if (capture.phase != Phase::Capturing84aa) {
        return false;
    }
    if (!identity.valid || groups.empty() ||
        groups.size() > DreamsSculptAtlasLineageMax84aaGroups ||
        destinations.size() != groups.size() || offsets.size() != groups.size() ||
        expected.size() != groups.size() * BrickBytes || actual.size() != expected.size()) {
        FailDreamsSculptAtlasLineage("84aa producer capture was incomplete or exceeded its cap");
        return false;
    }

    const auto output = capture.directory / "84aa";
    std::error_code error;
    std::filesystem::create_directory(output, error);
    if (error) {
        FailDreamsSculptAtlasLineage("could not create the 84aa output directory");
        return false;
    }
    u64 expected_hash{};
    u64 actual_hash{};
    const auto expected_file = output / "expected-bricks.bin";
    const auto actual_file = output / "actual-bricks.bin";
    bool files_ok = WriteDreamsCaptureBytes(expected_file, expected, expected_hash) &&
                    WriteDreamsCaptureBytes(actual_file, actual, actual_hash) &&
                    VerifyDreamsCaptureBytes(expected_file, expected, expected_hash) &&
                    VerifyDreamsCaptureBytes(actual_file, actual, actual_hash);

    capture.producer_image = identity;
    capture.producer_groups = static_cast<u32>(groups.size());
    capture.bricks.clear();
    capture.bricks.reserve(groups.size());
    capture.producer_mismatched_bytes = 0;
    std::string rows = "index\tgroup\tdestination\tbrick_x\tbrick_y\tbrick_z\tbrick_key\t"
                       "expected_hash\tactual_hash\tproducer_mismatches\n";
    for (u32 index = 0; index < groups.size(); ++index) {
        const auto& offset = offsets[index];
        const auto key = PackDreamsAtlasBrick(offset.x, offset.y, offset.z);
        if (!key.has_value()) {
            FailDreamsSculptAtlasLineage("84aa emitted an invalid atlas brick coordinate");
            return false;
        }
        DreamsSculptAtlasLineageBrick brick{
            .group = groups[index],
            .destination = destinations[index],
        };
        const u64 base = static_cast<u64>(index) * BrickBytes;
        std::copy_n(expected.data() + base, BrickBytes, brick.expected.data());
        std::copy_n(actual.data() + base, BrickBytes, brick.actual.data());
        for (u32 byte = 0; byte < BrickBytes; ++byte) {
            brick.producer_mismatches += brick.expected[byte] != brick.actual[byte];
        }
        capture.producer_mismatched_bytes += brick.producer_mismatches;
        if (!capture.bricks.emplace(*key, brick).second) {
            FailDreamsSculptAtlasLineage("84aa emitted duplicate atlas brick coordinates");
            return false;
        }
        rows += fmt::format("{}\t{}\t{}\t{}\t{}\t{}\t{:#018x}\t{:#018x}\t{:#018x}\t{}\n", index,
                            groups[index], destinations[index], offset.x / 8, offset.y / 8,
                            offset.z / 8, *key, HashDreamsTraceBytes(brick.expected),
                            HashDreamsTraceBytes(brick.actual), brick.producer_mismatches);
    }
    files_ok &= WriteDreamsCaptureText(output / "bricks.tsv", rows);
    files_ok &= WriteDreamsCaptureText(
        output / "manifest.tsv",
        fmt::format("schema\t1\nshader\t{:#x}\nsequence\t{}\ngroups\t{}\nbrick_bytes\t{}\n"
                    "expected_bytes\t{}\nactual_bytes\t{}\nexpected_fnv1a64\t{:#018x}\n"
                    "actual_fnv1a64\t{:#018x}\nproducer_mismatched_bytes\t{}\n"
                    "binding\t{}\nimage_id\t{}\nimage_uid\t{}\nbacking\t{:#x}\n"
                    "descriptor_base\t{:#x}\nguest_base\t{:#x}\nguest_size\t{}\n"
                    "descriptor_shape\t{}x{}x{}\ndescriptor_pitch\t{}\n"
                    "cached_shape\t{}x{}x{}\ncached_pitch\t{}\nview_type\t{}\n"
                    "view_format\t{}\nbase_level\t{}\nlevels\t{}\nbase_layer\t{}\nlayers\t{}\n",
                    Shader::DreamsCompat::SculptVolumeWriterShader, capture.producer_sequence,
                    groups.size(), BrickBytes, expected.size(), actual.size(), expected_hash,
                    actual_hash, capture.producer_mismatched_bytes, identity.binding,
                    identity.image_id, identity.image_uid, identity.backing_handle,
                    identity.descriptor_base, identity.guest_base, identity.guest_size,
                    identity.descriptor_width, identity.descriptor_height,
                    identity.descriptor_depth, identity.descriptor_pitch, identity.cached_width,
                    identity.cached_height, identity.cached_depth, identity.cached_pitch,
                    identity.view_type, identity.view_format, identity.base_level, identity.levels,
                    identity.base_layer, identity.layers));
    if (!files_ok) {
        FailDreamsSculptAtlasLineage("failed to write or verify the 84aa producer files");
        return false;
    }
    capture.phase = Phase::Waiting2f;
    LOG_WARNING(Render_Vulkan,
                "Dreams sculpt-atlas lineage captured 84aa sequence={} groups={} bricks={} "
                "producer_mismatched_bytes={}",
                capture.producer_sequence, capture.producer_groups, capture.bricks.size(),
                capture.producer_mismatched_bytes);
    return true;
}

static bool WantsDreamsSculptAtlasLineageConsumer(u64 shader, u64 sequence,
                                                  const DreamsAtlasImageIdentity& consumer) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    if (capture.phase != Phase::Waiting2f && capture.phase != Phase::WaitingF030) {
        return false;
    }
    if (SameDreamsAtlasByteCoordinates(capture.producer_image, consumer)) {
        const u64 expected_shader = capture.phase == Phase::Waiting2f
                                        ? Shader::DreamsCompat::SculptAtlasPrepareShader
                                        : Shader::DreamsCompat::SculptSurfaceCompactShader;
        if (shader != expected_shader) {
            AppendDreamsSculptAtlasLineageEvent(fmt::format("{:#x}", shader), sequence,
                                                "same_atlas", "fail_out_of_order");
            FailDreamsSculptAtlasLineage(fmt::format(
                "out-of-order same-atlas consumer {:#x}; expected {:#x} during {}", shader,
                expected_shader, DreamsSculptAtlasLineagePhaseName(capture.phase)));
            return false;
        }
        const u64 predecessor_sequence = capture.phase == Phase::Waiting2f
                                             ? capture.producer_sequence
                                             : capture.prepare.sequence;
        if (sequence <= predecessor_sequence) {
            AppendDreamsSculptAtlasLineageEvent(fmt::format("{:#x}", shader), sequence,
                                                "same_atlas", "fail_non_monotonic");
            FailDreamsSculptAtlasLineage(
                fmt::format("same-atlas consumer {:#x} sequence {} did not follow predecessor {}",
                            shader, sequence, predecessor_sequence));
            return false;
        }
        if (!AppendDreamsSculptAtlasLineageEvent(fmt::format("{:#x}", shader), sequence,
                                                 "same_atlas", "ordering_valid")) {
            FailDreamsSculptAtlasLineage("failed to append the consumer ordering event");
            return false;
        }
        return true;
    }

    ++capture.consumer_attempts;
    AppendDreamsCaptureText(
        capture.directory / "resource-mismatches.tsv",
        fmt::format("{}\t{:#x}\t{}\t{}\t{}\t{}\t{:#x}\t{:#x}\t{:#x}\t{}\t{}\t{}\t{}\n",
                    capture.consumer_attempts, shader, consumer.valid, consumer.binding,
                    consumer.image_id, consumer.image_uid, consumer.backing_handle,
                    consumer.descriptor_base, consumer.guest_base, consumer.descriptor_width,
                    consumer.descriptor_height, consumer.descriptor_depth, consumer.view_format));
    LOG_WARNING(Render_Vulkan,
                "Dreams sculpt-atlas lineage rejected consumer {:#x} attempt={}/{}: exact "
                "producer backing/byte coordinates did not match",
                shader, capture.consumer_attempts, DreamsSculptAtlasLineageMaxConsumerAttempts);
    if (capture.consumer_attempts >= DreamsSculptAtlasLineageMaxConsumerAttempts) {
        FailDreamsSculptAtlasLineage("consumer resource identity did not match after the cap");
    }
    return false;
}

static void MarkDreamsSculptAtlasLineageF030Files(bool complete) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    if (capture.phase != DreamsSculptAtlasLineageCapture::Phase::WaitingF030) {
        return;
    }
    if (!complete) {
        FailDreamsSculptAtlasLineage("f030 count/record capture was incomplete");
        return;
    }
    capture.f030_files_complete = true;
}

static bool FinalizeDreamsSculptAtlasLineage() {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    if (capture.phase != Phase::WaitingF030 || !capture.prepare.complete ||
        !capture.compact.complete || !capture.f030_files_complete) {
        return false;
    }
    const bool manifest_ok = WriteDreamsCaptureText(
        capture.directory / "manifest.tsv",
        fmt::format("schema\t1\nstatus\tcomplete\n"
                    "capture_scope\tbounded_sampled_gather_store_boundary\n"
                    "sample_window\twg_xyz_lt_4_local_xyz_lt_2\n"
                    "max_candidates_per_site\t{}\n"
                    "gather_scope\tfirst_winner_per_static_site_within_sample_window\n"
                    "store_scope\tfirst_16_claimants_per_static_site_within_sample_window\n"
                    "gather_store_pairing\tindependent_claimants_no_per_invocation_join\n"
                    "store_reload_evidence\timmediate_shader_observation_not_host_persistence\n"
                    "producer_shader\t{:#x}\nproducer_sequence\t{}\n"
                    "producer_groups\t{}\nproducer_bricks\t{}\nproducer_mismatched_bytes\t{}\n"
                    "prepare_shader\t{:#x}\nprepare_sequence\t{}\nprepare_match\t{}\n"
                    "prepare_mismatch\t{}\nprepare_unknown\t{}\ncompact_shader\t{:#x}\n"
                    "compact_sequence\t{}\ncompact_match\t{}\ncompact_mismatch\t{}\n"
                    "compact_unknown\t{}\nf030_files_complete\t{}\nce3_join\tnot_captured\n",
                    Shader::DreamsCompat::ImageGather3DSampleWindow::MaxCandidatesPerSite,
                    Shader::DreamsCompat::SculptVolumeWriterShader, capture.producer_sequence,
                    capture.producer_groups, capture.bricks.size(),
                    capture.producer_mismatched_bytes,
                    Shader::DreamsCompat::SculptAtlasPrepareShader, capture.prepare.sequence,
                    capture.prepare.matched, capture.prepare.mismatched, capture.prepare.unknown,
                    Shader::DreamsCompat::SculptSurfaceCompactShader, capture.compact.sequence,
                    capture.compact.matched, capture.compact.mismatched, capture.compact.unknown,
                    capture.f030_files_complete));
    if (!manifest_ok || !WriteDreamsCaptureCompletionMarker(capture.directory)) {
        FailDreamsSculptAtlasLineage("failed to write the verified completion marker");
        return false;
    }
    capture.phase = Phase::Complete;
    LOG_WARNING(Render_Vulkan,
                "Dreams sculpt-atlas lineage complete directory={} producer={} 2f={} f030={} "
                "(CE3 join deliberately not captured)",
                capture.directory.string(), capture.producer_sequence, capture.prepare.sequence,
                capture.compact.sequence);
    return true;
}

static bool RecordDreamsSculptAtlasLineageConsumer(
    u64 shader, u64 sequence, const DreamsAtlasImageIdentity& consumer,
    const std::array<u32, Gather3DCapture::DwordCount>& gather,
    const std::array<u32, Gather3DConsumerCapture::DwordCount>& stores) {
    auto& capture = g_dreams_sculpt_atlas_lineage;
    using Phase = DreamsSculptAtlasLineageCapture::Phase;
    const bool is_prepare = shader == Shader::DreamsCompat::SculptAtlasPrepareShader &&
                            capture.phase == Phase::Waiting2f;
    const bool is_compact = shader == Shader::DreamsCompat::SculptSurfaceCompactShader &&
                            capture.phase == Phase::WaitingF030;
    if (!is_prepare && !is_compact) {
        return false;
    }
    if (!SameDreamsAtlasByteCoordinates(capture.producer_image, consumer)) {
        FailDreamsSculptAtlasLineage("captured consumer resource identity changed after arming");
        return false;
    }

    const auto gather_word = [&](u32 absolute_dword) {
        return gather[absolute_dword - Gather3DCapture::BaseDword];
    };
    const auto gather_record = [&](u32 site, u32 field) {
        return gather_word(Gather3DCapture::RecordDword(site, field));
    };
    const auto store_word = [&](u32 absolute_dword) {
        return stores[absolute_dword - Gather3DConsumerCapture::BaseDword];
    };
    const auto store_record = [&](u32 site, u32 index, u32 field) {
        return store_word(Gather3DConsumerCapture::RecordDword(site, index, field));
    };
    const u32 gather_seen = gather_word(Gather3DCapture::SeenDword);
    const u32 store_seen = store_word(Gather3DConsumerCapture::SeenDword);
    constexpr u32 RequiredGatherSites = 0x3;
    if ((gather_seen & RequiredGatherSites) != RequiredGatherSites || store_seen == 0) {
        FailDreamsSculptAtlasLineage(
            fmt::format("consumer {:#x} capture incomplete: gather_seen={:#x} store_seen={:#x}",
                        shader, gather_seen, store_seen));
        return false;
    }

    const auto output = capture.directory / (is_prepare ? "2f" : "f030") / "gather";
    std::error_code error;
    std::filesystem::create_directories(output, error);
    if (error) {
        FailDreamsSculptAtlasLineage("could not create the consumer output directory");
        return false;
    }
    u64 gather_hash{};
    u64 stores_hash{};
    const std::span<const u8> gather_bytes{reinterpret_cast<const u8*>(gather.data()),
                                           gather.size() * sizeof(u32)};
    const std::span<const u8> stores_bytes{reinterpret_cast<const u8*>(stores.data()),
                                           stores.size() * sizeof(u32)};
    bool files_ok = WriteDreamsCaptureWords(output / "gather.bin", gather, gather_hash) &&
                    VerifyDreamsCaptureBytes(output / "gather.bin", gather_bytes, gather_hash) &&
                    WriteDreamsCaptureWords(output / "stores.bin", stores, stores_hash) &&
                    VerifyDreamsCaptureBytes(output / "stores.bin", stores_bytes, stores_hash);

    u32 matched{};
    u32 mismatched{};
    u32 unknown{};
    std::string gather_rows =
        "site\tsource\tx\ty\tz\tbinding\tcomponent\tsampled_raw\tsampled_byte\t"
        "producer_actual\tproducer_expected\tproducer_mismatches\tstatus\n";
    for (u32 site = 0; site < Gather3DCapture::MaxSites; ++site) {
        if ((gather_seen & (1U << site)) == 0) {
            continue;
        }
        const u64 captured_hash = u64{gather_record(site, Gather3DCapture::ShaderHashLo)} |
                                  (u64{gather_record(site, Gather3DCapture::ShaderHashHi)} << 32);
        const u32 binding = gather_record(site, Gather3DCapture::ImageBinding);
        const u32 component = gather_record(site, Gather3DCapture::Component);
        if (captured_hash != shader || binding != 0 || component != 0) {
            FailDreamsSculptAtlasLineage(
                "consumer gather site did not use the expected shader/image/red component");
            return false;
        }
        for (u32 source = 0; source < 4; ++source) {
            const s32 x = std::bit_cast<s32>(
                gather_record(site, Gather3DCapture::SourceCoordinates + source * 3));
            const s32 y = std::bit_cast<s32>(
                gather_record(site, Gather3DCapture::SourceCoordinates + source * 3 + 1));
            const s32 z = std::bit_cast<s32>(
                gather_record(site, Gather3DCapture::SourceCoordinates + source * 3 + 2));
            const u32 sampled_raw =
                gather_record(site, Gather3DCapture::SelectedComponents + source);
            const float sampled_float = std::bit_cast<float>(sampled_raw);
            const bool sampled_valid =
                std::isfinite(sampled_float) && sampled_float >= 0.0f && sampled_float <= 1.0f;
            const u32 sampled_byte = sampled_valid
                                         ? static_cast<u32>(std::lround(sampled_float * 255.0f))
                                         : std::numeric_limits<u32>::max();
            const auto key = PackDreamsAtlasBrick(x, y, z);
            const auto brick_it =
                key.has_value() ? capture.bricks.find(*key) : capture.bricks.end();
            u32 producer_actual = std::numeric_limits<u32>::max();
            u32 producer_expected = std::numeric_limits<u32>::max();
            u32 producer_mismatches{};
            std::string_view status = "UNKNOWN";
            if (brick_it != capture.bricks.end()) {
                const u32 lane = (static_cast<u32>(y) & 7U) * 8U + (static_cast<u32>(x) & 7U);
                const u32 byte = static_cast<u32>(z) & 7U;
                const u32 offset = byte * 64 + lane;
                producer_actual = brick_it->second.actual[offset];
                producer_expected = brick_it->second.expected[offset];
                producer_mismatches = brick_it->second.producer_mismatches;
                if (sampled_valid && sampled_byte == producer_actual) {
                    status = "MATCH";
                    ++matched;
                } else {
                    status = "MISMATCH";
                    ++mismatched;
                }
            } else {
                ++unknown;
            }
            gather_rows +=
                fmt::format("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:#010x}\t{:#x}\t{:#x}\t{:#x}\t{}\t{}\n",
                            site, source, x, y, z, binding, component, sampled_raw, sampled_byte,
                            producer_actual, producer_expected, producer_mismatches, status);
        }
    }

    std::string store_rows =
        "site\tindex\twindow_claims\thandle\tcomponents\traw_address\tresolved_address\t"
        "input0\tinput1\tinput2\tinput3\treload0\treload1\treload2\treload3\t"
        "match_mask\tbuffer_type\n";
    for (u32 site = 0; site < Gather3DConsumerCapture::MaxSites; ++site) {
        const u32 total = store_word(Gather3DConsumerCapture::CounterDword(site));
        const u32 stored = std::min(total, Gather3DConsumerCapture::MaxRecordsPerSite);
        for (u32 index = 0; index < stored; ++index) {
            store_rows += fmt::format(
                "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:#010x}\t{:#010x}\t{:#010x}\t{:#010x}\t"
                "{:#010x}\t{:#010x}\t{:#010x}\t{:#010x}\t{:#x}\t{}\n",
                site, index, total, store_record(site, index, Gather3DConsumerCapture::Handle),
                store_record(site, index, Gather3DConsumerCapture::Components),
                store_record(site, index, Gather3DConsumerCapture::RawAddress),
                store_record(site, index, Gather3DConsumerCapture::ResolvedAddress),
                store_record(site, index, Gather3DConsumerCapture::InputValues),
                store_record(site, index, Gather3DConsumerCapture::InputValues + 1),
                store_record(site, index, Gather3DConsumerCapture::InputValues + 2),
                store_record(site, index, Gather3DConsumerCapture::InputValues + 3),
                store_record(site, index, Gather3DConsumerCapture::ReloadedValues),
                store_record(site, index, Gather3DConsumerCapture::ReloadedValues + 1),
                store_record(site, index, Gather3DConsumerCapture::ReloadedValues + 2),
                store_record(site, index, Gather3DConsumerCapture::ReloadedValues + 3),
                store_record(site, index, Gather3DConsumerCapture::MatchMask),
                store_record(site, index, Gather3DConsumerCapture::BufferType));
        }
    }
    files_ok &= WriteDreamsCaptureText(output / "gather.tsv", gather_rows);
    files_ok &= WriteDreamsCaptureText(output / "stores.tsv", store_rows);
    files_ok &= WriteDreamsCaptureText(
        output / "manifest.tsv",
        fmt::format(
            "schema\t1\nshader\t{:#x}\nsequence\t{}\n"
            "capture_scope\tbounded_sampled_gather_store_boundary\n"
            "sample_window\twg_xyz_lt_4_local_xyz_lt_2\n"
            "max_candidates_per_site\t{}\n"
            "gather_scope\tfirst_winner_per_static_site_within_sample_window\n"
            "store_scope\tfirst_16_claimants_per_static_site_within_sample_window\n"
            "gather_store_pairing\tindependent_claimants_no_per_invocation_join\n"
            "store_reload_evidence\timmediate_shader_observation_not_host_persistence\n"
            "gather_seen\t{:#x}\n"
            "store_seen\t{:#x}\nmatched\t{}\nmismatched\t{}\nunknown\t{}\n"
            "gather_fnv1a64\t{:#018x}\nstores_fnv1a64\t{:#018x}\n"
            "resource_identity\texact_same_backing_and_byte_coordinates\n",
            shader, sequence, Shader::DreamsCompat::ImageGather3DSampleWindow::MaxCandidatesPerSite,
            gather_seen, store_seen, matched, mismatched, unknown, gather_hash, stores_hash));
    if (!files_ok) {
        FailDreamsSculptAtlasLineage("failed to write the consumer gather/store files");
        return false;
    }

    auto& result = is_prepare ? capture.prepare : capture.compact;
    result = {
        .complete = true,
        .sequence = sequence,
        .gather_seen = gather_seen,
        .store_seen = store_seen,
        .matched = matched,
        .mismatched = mismatched,
        .unknown = unknown,
    };
    capture.consumer_attempts = 0;
    if (is_prepare) {
        capture.phase = Phase::WaitingF030;
        capture.deadline_sequence = sequence + DreamsSculptAtlasLineageMaxDispatchGap;
    } else {
        FinalizeDreamsSculptAtlasLineage();
    }
    return true;
}

static void FailDreamsUpstreamLineageCapture(std::string_view reason) {
    auto& capture = g_dreams_upstream_lineage_capture;
    if (capture.phase == DreamsUpstreamLineageCaptureState::Phase::Complete ||
        capture.phase == DreamsUpstreamLineageCaptureState::Phase::Failed) {
        return;
    }
    capture.phase = DreamsUpstreamLineageCaptureState::Phase::Failed;
    LOG_ERROR(Render_Vulkan, "Dreams upstream lineage capture failed: {}", reason);
    if (!capture.directory.empty()) {
        std::error_code error;
        std::filesystem::remove(capture.directory / "complete.txt", error);
        WriteDreamsCaptureText(capture.directory / "failed.txt", fmt::format("{}\n", reason));
    }
}

static void CompleteDreamsUpstreamLineageCapture() {
    auto& capture = g_dreams_upstream_lineage_capture;
    using Phase = DreamsUpstreamLineageCaptureState::Phase;
    if (capture.phase != Phase::Capturing7aa || capture.directory.empty()) {
        FailDreamsUpstreamLineageCapture("7aa completion arrived in the wrong capture phase");
        return;
    }
    if (capture.b535_records.empty() || capture.b535_records.size() > 4096 ||
        capture.active_count == 0 || capture.active_count > 4096 ||
        capture.d8_input.size() != capture.active_count ||
        capture.d8_output.size() != capture.active_count ||
        capture.list_input != capture.d8_output || capture.source_rows.empty()) {
        FailDreamsUpstreamLineageCapture("upstream payload lengths or the d8-to-7aa handoff differ");
        return;
    }

    std::map<u32, u32> d8_input_multiplicity;
    std::map<u32, u32> d8_output_multiplicity;
    for (const u32 selector : capture.d8_input) {
        ++d8_input_multiplicity[selector];
    }
    for (const u32 selector : capture.d8_output) {
        ++d8_output_multiplicity[selector];
    }
    if (d8_input_multiplicity != d8_output_multiplicity) {
        FailDreamsUpstreamLineageCapture("d8 output is not an exact permutation of its input");
        return;
    }

    std::map<u32, std::array<u32, 2>> source_by_index;
    for (const auto& source : capture.source_rows) {
        if (!source_by_index.emplace(source.index, source.words).second) {
            FailDreamsUpstreamLineageCapture("7aa source-row inventory contains duplicate indices");
            return;
        }
    }
    for (const u32 selector : capture.list_input) {
        if (!source_by_index.contains(selector >> 10)) {
            FailDreamsUpstreamLineageCapture("7aa source-row inventory is incomplete");
            return;
        }
    }

    struct LabelCounts {
        u32 b535_input{};
        u32 b535_terminal_b3{};
        u32 b535_linked_d8_input{};
        u32 d8_input{};
        u32 d8_output{};
        u32 list_output{};
    };
    std::map<u32, LabelCounts> label_counts;
    std::map<std::array<u32, 2>, u32> list_output_multiplicity;
    for (const auto& output : capture.list_output) {
        ++label_counts[output.words[1] & 0xffff].list_output;
        ++list_output_multiplicity[output.words];
    }
    for (const u32 selector : capture.d8_input) {
        const auto& source = source_by_index.at(selector >> 10);
        ++label_counts[source[1] & 0xffff].d8_input;
    }
    for (const u32 selector : capture.d8_output) {
        const auto& source = source_by_index.at(selector >> 10);
        ++label_counts[source[1] & 0xffff].d8_output;
    }

    std::string lineage =
        "pass\tworkgroup\tlane\tidentity\trecord\tb535_record_low16\toutput_role\tflags\t"
        "output_index\td8_input_valid\td8_input_selector\tsource_index\tsource_word0\t"
        "source_word1\tsource_word1_low16\td8_output_selector_multiplicity\t"
        "list_output_pair_multiplicity\n";
    for (const auto& record : capture.b535_records) {
        const u32 label = record.record & 0xffff;
        ++label_counts[label].b535_input;
        const bool terminal_b3 = (record.output_role & 8) != 0;
        label_counts[label].b535_terminal_b3 += terminal_b3;
        const bool input_valid = terminal_b3 && record.output_index < capture.d8_input.size();
        label_counts[label].b535_linked_d8_input += input_valid;
        const u32 selector = input_valid ? capture.d8_input[record.output_index] : 0;
        const u32 source_index = selector >> 10;
        const auto source = input_valid ? source_by_index.find(source_index) : source_by_index.end();
        const bool source_valid = source != source_by_index.end();
        const std::array<u32, 2> source_words = source_valid ? source->second
                                                             : std::array<u32, 2>{};
        lineage += fmt::format(
            "{}\t{}\t{}\t{:#010x}\t{:#010x}\t{:#06x}\t{:#04x}\t{:#010x}\t{}\t{}\t"
            "{:#010x}\t{}\t{:#010x}\t{:#010x}\t{:#06x}\t{}\t{}\n",
            record.pass, record.workgroup, record.lane, record.identity, record.record, label,
            record.output_role, record.flags, record.output_index, input_valid, selector,
            source_index, source_words[0], source_words[1], source_words[1] & 0xffff,
            input_valid ? d8_output_multiplicity[selector] : 0,
            source_valid ? list_output_multiplicity[source_words] : 0);
    }

    std::string d8_records =
        "position\tinput_selector\toutput_selector\toutput_source_index\toutput_word0\t"
        "output_word1\toutput_word1_low16\n";
    for (u32 position = 0; position < capture.active_count; ++position) {
        const u32 selector = capture.d8_output[position];
        const auto& source = source_by_index.at(selector >> 10);
        d8_records += fmt::format("{}\t{:#010x}\t{:#010x}\t{}\t{:#010x}\t{:#010x}\t"
                                  "{:#06x}\n",
                                  position, capture.d8_input[position], selector, selector >> 10,
                                  source[0], source[1], source[1] & 0xffff);
    }

    std::string source_rows = "source_index\tword0\tword1\tword1_low16\n";
    std::vector<u32> source_words;
    source_words.reserve(capture.source_rows.size() * 3);
    for (const auto& source : capture.source_rows) {
        source_rows += fmt::format("{}\t{:#010x}\t{:#010x}\t{:#06x}\n", source.index,
                                   source.words[0], source.words[1], source.words[1] & 0xffff);
        source_words.push_back(source.index);
        source_words.insert(source_words.end(), source.words.begin(), source.words.end());
    }

    std::string output_records = "partition\tposition\tword0\tword1\tword1_low16\n";
    std::vector<u32> output_words;
    output_words.reserve(capture.list_output.size() * 4);
    for (const auto& output : capture.list_output) {
        output_records += fmt::format("{}\t{}\t{:#010x}\t{:#010x}\t{:#06x}\n",
                                      output.partition, output.position, output.words[0],
                                      output.words[1], output.words[1] & 0xffff);
        output_words.push_back(output.partition);
        output_words.push_back(output.position);
        output_words.insert(output_words.end(), output.words.begin(), output.words.end());
    }

    std::string labels =
        "low16_key\tb535_record_inputs\tb535_record_terminal_b3\t"
        "b535_record_linked_d8_input\td8_input_source_word1\td8_output_source_word1\t"
        "7aa_output_word1\n";
    for (const auto& [label, counts] : label_counts) {
        labels += fmt::format("{:#06x}\t{}\t{}\t{}\t{}\t{}\t{}\n", label,
                              counts.b535_input, counts.b535_terminal_b3,
                              counts.b535_linked_d8_input, counts.d8_input, counts.d8_output,
                              counts.list_output);
    }

    const u64 output_delta =
        u64{capture.list_final_counters[0] - capture.list_initial_counters[0]} +
        u64{capture.list_final_counters[1] - capture.list_initial_counters[1]};
    const u32 overlap_begin =
        std::max(capture.list_initial_counters[0], capture.list_initial_counters[1]);
    const u32 overlap_end =
        std::min(capture.list_final_counters[0], capture.list_final_counters[1]);
    const u32 partition_overlap_records =
        overlap_end > overlap_begin ? overlap_end - overlap_begin : 0;
    std::string manifest = "key\tvalue\n";
    const auto row = [&](std::string_view key, const auto& value) {
        manifest += fmt::format("{}\t{}\n", key, value);
    };
    row("capture", "b535-d8-7aa-upstream-lineage");
    row("record_limit_per_stage", 4096);
    row("b535_records", capture.b535_records.size());
    row("b535_first_sequence", capture.b535_first_sequence);
    row("b535_final_sequence", capture.b535_final_sequence);
    row("d8_active_records", capture.active_count);
    row("d8_input_hash", fmt::format("{:#018x}", HashDreamsTraceWords(capture.d8_input)));
    row("d8_output_hash", fmt::format("{:#018x}", HashDreamsTraceWords(capture.d8_output)));
    row("d8_permutation_valid", 1);
    row("d8_input_base", fmt::format("{:#x}", capture.d8_input_base));
    row("d8_output_base", fmt::format("{:#x}", capture.d8_output_base));
    row("d8_input_bound_offset", fmt::format("{:#x}", capture.d8_input_bound_offset));
    row("d8_input_bound_range", fmt::format("{:#x}", capture.d8_input_bound_range));
    row("d8_input_logical_offset", fmt::format("{:#x}", capture.d8_input_logical_offset));
    row("d8_output_bound_offset", fmt::format("{:#x}", capture.d8_output_bound_offset));
    row("d8_output_bound_range", fmt::format("{:#x}", capture.d8_output_bound_range));
    row("d8_output_logical_offset", fmt::format("{:#x}", capture.d8_output_logical_offset));
    row("7aa_sequence", capture.list_sequence);
    row("7aa_input_matches_d8_output", 1);
    row("7aa_unique_source_rows", capture.source_rows.size());
    row("7aa_initial_counters",
        fmt::format("{},{}", capture.list_initial_counters[0],
                    capture.list_initial_counters[1]));
    row("7aa_final_counters",
        fmt::format("{},{}", capture.list_final_counters[0],
                    capture.list_final_counters[1]));
    row("7aa_output_delta", output_delta);
    row("7aa_captured_output_records", capture.list_output.size());
    row("7aa_partition_overlap_records", partition_overlap_records);
    row("7aa_input_bound_offset", fmt::format("{:#x}", capture.list_input_bound_offset));
    row("7aa_input_bound_range", fmt::format("{:#x}", capture.list_input_bound_range));
    row("7aa_input_logical_offset", fmt::format("{:#x}", capture.list_input_logical_offset));
    row("7aa_source_bound_offset", fmt::format("{:#x}", capture.list_source_bound_offset));
    row("7aa_source_bound_range", fmt::format("{:#x}", capture.list_source_bound_range));
    row("7aa_source_logical_offset", fmt::format("{:#x}", capture.list_source_logical_offset));
    row("7aa_output_bound_offset", fmt::format("{:#x}", capture.list_output_bound_offset));
    row("7aa_output_bound_range", fmt::format("{:#x}", capture.list_output_bound_range));
    row("7aa_output_logical_offset", fmt::format("{:#x}", capture.list_output_logical_offset));
    row("readback", "exact bound Vulkan buffers; no guest CPU mirror used for payloads");
    row("b535_low16_semantics",
        "record low16 (guest instrumentation calls it object index); equality to 7aa word1 "
        "low16 is measured by lineage.tsv, not assumed");
    row("label_stage_count_key",
        "numeric low16 union; B535 columns use record low16 and d8/7aa columns use source/output "
        "word1 low16");
    row("duplicate_selector_caveat",
        "equal selectors preserve exact multiplicity but do not have a distinguishable identity");
    row("completion_boundary", "immediately after matched 7aa; VS370 is not instrumented");

    const auto write_verified_text = [](const std::filesystem::path& file,
                                        std::string_view value) {
        const std::span<const u8> bytes{reinterpret_cast<const u8*>(value.data()), value.size()};
        return WriteDreamsCaptureText(file, value) &&
               VerifyDreamsCaptureBytes(file, bytes, HashDreamsTraceBytes(bytes));
    };
    const auto write_verified_words = [](const std::filesystem::path& file,
                                         std::span<const u32> words) {
        u64 hash{};
        const std::span<const u8> bytes{reinterpret_cast<const u8*>(words.data()),
                                       words.size_bytes()};
        return WriteDreamsCaptureWords(file, words, hash) &&
               VerifyDreamsCaptureBytes(file, bytes, hash);
    };

    bool files_ok = write_verified_text(capture.directory / "lineage.tsv", lineage);
    files_ok &= write_verified_text(capture.directory / "d8-records.tsv", d8_records);
    files_ok &= write_verified_text(capture.directory / "7aa-source-rows.tsv", source_rows);
    files_ok &= write_verified_text(capture.directory / "7aa-output-records.tsv", output_records);
    files_ok &= write_verified_text(capture.directory / "label-stage-counts.tsv", labels);
    files_ok &= write_verified_text(capture.directory / "manifest.tsv", manifest);
    files_ok &= write_verified_words(capture.directory / "d8-input.bin", capture.d8_input);
    files_ok &= write_verified_words(capture.directory / "d8-output.bin", capture.d8_output);
    files_ok &= write_verified_words(capture.directory / "7aa-input.bin", capture.list_input);
    files_ok &= write_verified_words(capture.directory / "7aa-source-rows.bin", source_words);
    files_ok &= write_verified_words(capture.directory / "7aa-output-records.bin", output_words);
    if (!files_ok || output_delta != capture.list_output.size()) {
        FailDreamsUpstreamLineageCapture(
            !files_ok ? "one or more lineage files failed write-back verification"
                      : "7aa output counter deltas do not match the captured records");
        return;
    }
    if (!WriteDreamsCaptureCompletionMarker(capture.directory)) {
        FailDreamsUpstreamLineageCapture("verified lineage files were written but marker failed");
        return;
    }
    capture.phase = Phase::Complete;
    LOG_WARNING(Render_Vulkan,
                "Dreams upstream lineage complete b535_rows={} active={} source_rows={} "
                "7aa_output={} directory={}",
                capture.b535_records.size(), capture.active_count, capture.source_rows.size(),
                capture.list_output.size(), capture.directory.string());
}

static void FailDreamsVs370ListSliceCapture(std::string_view reason) {
    auto& capture = g_dreams_vs370_list_slice_capture;
    capture.armed = false;
    capture.complete = false;
    capture.failed = true;
    LOG_ERROR(Render_Vulkan, "Dreams VS370 list-slice capture failed: {}", reason);
    if (!capture.directory.empty()) {
        WriteDreamsCaptureText(capture.directory / "failed.txt", fmt::format("{}\n", reason));
    }
}

static void CompleteDreamsVs370ListSliceCapture(
    const DreamsVs370ListSlicePendingDraw& pending, std::span<const u32> settled_words) {
    auto& capture = g_dreams_vs370_list_slice_capture;
    const auto fail = [&](std::string_view reason) {
        FailDreamsVs370ListSliceCapture(reason);
    };
    const u64 expected_words = u64{pending.command.instanceCount} * 2;
    if (!pending.ready || settled_words.size() != expected_words || expected_words == 0) {
        fail("exact bound visibility-list read returned the wrong length");
        return;
    }

    struct Word1Group {
        std::vector<u32> word0_draw_order;
        std::map<u32, u32> word0_multiplicities;
        std::map<u32, u32> low24_multiplicities;
    };
    struct Low24Group {
        std::vector<u32> draw_order_pairs;
        std::map<u32, u32> full_word0_multiplicities;
        std::map<u32, u32> word1_multiplicities;
    };
    std::map<u32, Word1Group> word1_groups;
    std::map<u32, Low24Group> low24_groups;
    std::string records =
        "draw_index\tproducer_record\tword0\tword0_low24\tword0_high8\tword1\t"
        "word1_low16\tword1_high16\n";
    for (u32 record = 0; record < pending.command.instanceCount; ++record) {
        const u32 word0 = settled_words[record * 2];
        const u32 word1 = settled_words[record * 2 + 1];
        const u32 low24 = word0 & 0x00ffffff;
        records += fmt::format("{}\t{}\t{:#010x}\t{:#08x}\t{:#04x}\t{:#010x}\t{:#06x}\t"
                               "{:#06x}\n",
                               record, pending.first_record + record, word0, low24, word0 >> 24,
                               word1, word1 & 0xffff, word1 >> 16);
        auto& word1_group = word1_groups[word1];
        word1_group.word0_draw_order.push_back(word0);
        ++word1_group.word0_multiplicities[word0];
        ++word1_group.low24_multiplicities[low24];
        auto& low24_group = low24_groups[low24];
        low24_group.draw_order_pairs.push_back(word0);
        low24_group.draw_order_pairs.push_back(word1);
        ++low24_group.full_word0_multiplicities[word0];
        ++low24_group.word1_multiplicities[word1];
    }

    const auto format_multiplicities = [](const std::map<u32, u32>& values) {
        std::string text;
        for (const auto& [value, count] : values) {
            if (!text.empty()) {
                text += ';';
            }
            text += fmt::format("{:#010x}:{}", value, count);
        }
        return text;
    };
    const auto multiplicity_hash = [](const std::map<u32, u32>& values) {
        std::vector<u32> words;
        words.reserve(values.size() * 2);
        for (const auto& [value, count] : values) {
            words.push_back(value);
            words.push_back(count);
        }
        return HashDreamsTraceWords(words);
    };

    u64 grouped_word1_records{};
    std::string word1_inventory =
        "word1\tword1_low16\tword1_high16\trecords\tunique_word0\tunique_word0_low24\t"
        "draw_order_word0_hash\tword0_multiplicity_hash\tword0_low24_multiplicity_hash\t"
        "word0_multiplicities\tword0_low24_multiplicities\n";
    for (const auto& [word1, group] : word1_groups) {
        grouped_word1_records += group.word0_draw_order.size();
        word1_inventory += fmt::format(
            "{:#010x}\t{:#06x}\t{:#06x}\t{}\t{}\t{}\t{:#018x}\t{:#018x}\t{:#018x}\t"
            "{}\t{}\n",
            word1, word1 & 0xffff, word1 >> 16, group.word0_draw_order.size(),
            group.word0_multiplicities.size(), group.low24_multiplicities.size(),
            HashDreamsTraceWords(group.word0_draw_order),
            multiplicity_hash(group.word0_multiplicities),
            multiplicity_hash(group.low24_multiplicities),
            format_multiplicities(group.word0_multiplicities),
            format_multiplicities(group.low24_multiplicities));
    }

    u64 grouped_low24_records{};
    std::string low24_inventory =
        "word0_low24\trecords\tunique_full_word0\tunique_word1\tdraw_order_pair_hash\t"
        "full_word0_multiplicity_hash\tword1_multiplicity_hash\t"
        "full_word0_multiplicities\tword1_multiplicities\n";
    for (const auto& [low24, group] : low24_groups) {
        const u64 records_in_group = group.draw_order_pairs.size() / 2;
        grouped_low24_records += records_in_group;
        low24_inventory += fmt::format(
            "{:#08x}\t{}\t{}\t{}\t{:#018x}\t{:#018x}\t{:#018x}\t{}\t{}\n", low24,
            records_in_group, group.full_word0_multiplicities.size(),
            group.word1_multiplicities.size(), HashDreamsTraceWords(group.draw_order_pairs),
            multiplicity_hash(group.full_word0_multiplicities),
            multiplicity_hash(group.word1_multiplicities),
            format_multiplicities(group.full_word0_multiplicities),
            format_multiplicities(group.word1_multiplicities));
    }
    if (grouped_word1_records != pending.command.instanceCount ||
        grouped_low24_records != pending.command.instanceCount) {
        fail("visibility-list fixture grouping did not conserve the draw record count");
        return;
    }

    u32 changed_from_guest_backing{};
    if (pending.guest_words_before.size() == settled_words.size()) {
        for (u32 word = 0; word < settled_words.size(); ++word) {
            changed_from_guest_backing +=
                settled_words[word] != pending.guest_words_before[word];
        }
    } else {
        fail("guest-backing comparison has the wrong length");
        return;
    }

    constexpr u32 B0RowsCaptured = 11;
    const u64 expected_b0_bytes = u64{B0RowsCaptured} * pending.b0.stride;
    if (pending.b0.stride != 432 ||
        pending.b0_rows_0_through_10.size() != expected_b0_bytes) {
        fail("exact bound B0 object-row fixture has the wrong size");
        return;
    }
    std::set<u32> observed_low16_labels;
    for (u32 record = 0; record < pending.command.instanceCount; ++record) {
        observed_low16_labels.insert(settled_words[record * 2 + 1] & 0xffff);
    }
    std::vector<u32> unique_b0_row_representatives;
    std::string b0_inventory =
        "label\tobserved_in_b3\trow_offset\trow_bytes\trow_byte_hash\tall_zero\t"
        "duplicate_of\n";
    for (u32 label = 0; label < B0RowsCaptured; ++label) {
        const std::span<const u8> row_bytes{
            pending.b0_rows_0_through_10.data() + u64{label} * pending.b0.stride,
            pending.b0.stride};
        s32 duplicate_of = -1;
        for (const u32 representative : unique_b0_row_representatives) {
            const std::span<const u8> representative_bytes{
                pending.b0_rows_0_through_10.data() +
                    u64{representative} * pending.b0.stride,
                pending.b0.stride};
            if (std::ranges::equal(row_bytes, representative_bytes)) {
                duplicate_of = static_cast<s32>(representative);
                break;
            }
        }
        if (duplicate_of < 0) {
            unique_b0_row_representatives.push_back(label);
        }
        const bool all_zero = std::ranges::all_of(row_bytes, [](u8 byte) { return byte == 0; });
        b0_inventory += fmt::format("{}\t{}\t{:#x}\t{}\t{:#018x}\t{}\t{}\n", label,
                                    observed_low16_labels.contains(label),
                                    u64{label} * pending.b0.stride, pending.b0.stride,
                                    HashDreamsTraceBytes(row_bytes), all_zero,
                                    duplicate_of < 0 ? "none" : fmt::format("{}", duplicate_of));
    }
    const std::span<const u8> b0_rows_bytes{pending.b0_rows_0_through_10};
    const u64 b0_rows_byte_hash = HashDreamsTraceBytes(b0_rows_bytes);

    const u64 settled_word_hash = HashDreamsTraceWords(settled_words);
    const std::span<const u8> settled_bytes{
        reinterpret_cast<const u8*>(settled_words.data()), settled_words.size_bytes()};
    const u64 settled_byte_hash = HashDreamsTraceBytes(settled_bytes);
    std::array<u32, sizeof(VkDrawIndexedIndirectCommand) / sizeof(u32)> command_words{};
    static_assert(sizeof(pending.command) == sizeof(command_words));
    std::memcpy(command_words.data(), &pending.command, sizeof(pending.command));
    const std::span<const u8> command_bytes{
        reinterpret_cast<const u8*>(command_words.data()), command_words.size() * sizeof(u32)};
    const u64 command_byte_hash = HashDreamsTraceBytes(command_bytes);

    std::string manifest = "key\tvalue\n";
    const auto row = [&](std::string_view key, const auto& value) {
        manifest += fmt::format("{}\t{}\n", key, value);
    };
    row("capture", "vs370-list-slice-host-only");
    row("fixture_validation", "passed");
    row("vertex_shader", fmt::format("{:#x}", pending.vertex_shader));
    row("fragment_shader", fmt::format("{:#x}", pending.fragment_shader));
    row("command_address", fmt::format("{:#x}", pending.command_address));
    row("count_address", fmt::format("{:#x}", pending.count_address));
    row("indirect_count", pending.indirect_count);
    row("index_count", pending.command.indexCount);
    row("instance_count", pending.command.instanceCount);
    row("capture_record_limit", 4096);
    row("first_index", pending.command.firstIndex);
    row("vertex_offset", pending.command.vertexOffset);
    row("first_instance", pending.command.firstInstance);
    row("shader_instance_base", pending.shader_instance_base);
    row("first_record", pending.first_record);
    row("end_record", pending.end_record);
    row("producer_sequence", pending.producer.dispatch_sequence);
    row("producer_shader", fmt::format("{:#x}", pending.producer.shader_hash));
    row("producer_args_address", fmt::format("{:#x}", pending.producer.args_address));
    row("producer_output_base", fmt::format("{:#x}", pending.producer.output_base));
    row("producer_output_size", fmt::format("{:#x}", pending.producer.output_size));
    row("producer_output_stride", pending.producer.output_stride);
    row("producer_output_capacity_records", pending.producer.output_capacity_records);
    row("producer_dispatch_initiator",
        fmt::format("{:#x}", pending.producer.dispatch_initiator));
    row("producer_start", fmt::format("{},{},{}", pending.producer.start[0],
                                      pending.producer.start[1], pending.producer.start[2]));
    row("producer_threads", fmt::format("{},{},{}", pending.producer.threads[0],
                                        pending.producer.threads[1], pending.producer.threads[2]));
    row("producer_raw_descriptor",
        fmt::format("{:#010x},{:#010x},{:#010x},{:#010x}",
                    pending.producer.raw_output_descriptor[0],
                    pending.producer.raw_output_descriptor[1],
                    pending.producer.raw_output_descriptor[2],
                    pending.producer.raw_output_descriptor[3]));
    for (u32 upstream = 0; upstream < 2; ++upstream) {
        const u32 binding = upstream + 1;
        row(fmt::format("producer_b{}_descriptor_valid", binding),
            pending.producer.upstream_descriptor_valid[upstream]);
        row(fmt::format("producer_b{}_base", binding),
            fmt::format("{:#x}", pending.producer.upstream_base[upstream]));
        row(fmt::format("producer_b{}_size", binding),
            fmt::format("{:#x}", pending.producer.upstream_size[upstream]));
        row(fmt::format("producer_b{}_stride", binding),
            pending.producer.upstream_stride[upstream]);
        row(fmt::format("producer_b{}_raw_descriptor", binding),
            fmt::format("{:#010x},{:#010x},{:#010x},{:#010x}",
                        pending.producer.raw_upstream_descriptors[upstream][0],
                        pending.producer.raw_upstream_descriptors[upstream][1],
                        pending.producer.raw_upstream_descriptors[upstream][2],
                        pending.producer.raw_upstream_descriptors[upstream][3]));
    }
    row("b3_base", fmt::format("{:#x}", pending.b3.base_address));
    row("b3_size", fmt::format("{:#x}", pending.b3.GetSize()));
    row("b3_stride", pending.b3.stride);
    row("b3_capacity_records", pending.b3.GetSize() / pending.b3.stride);
    row("b0_base", fmt::format("{:#x}", pending.b0.base_address));
    row("b0_size", fmt::format("{:#x}", pending.b0.GetSize()));
    row("b0_stride", pending.b0.stride);
    row("b0_rows_captured", "0..10");
    row("b0_rows_unique", unique_b0_row_representatives.size());
    row("b0_rows_byte_hash", fmt::format("{:#018x}", b0_rows_byte_hash));
    row("b0_bound_source_offset", fmt::format("{:#x}", pending.b0_bound_source_offset));
    row("b0_bound_source_range", fmt::format("{:#x}", pending.b0_bound_source_range));
    row("b0_bound_logical_base_offset",
        fmt::format("{:#x}", pending.b0_bound_logical_base_offset));
    row("bound_source_offset", fmt::format("{:#x}", pending.bound_source_offset));
    row("bound_source_range", fmt::format("{:#x}", pending.bound_source_range));
    row("bound_logical_base_offset",
        fmt::format("{:#x}", pending.bound_logical_base_offset));
    row("bound_slice_relative_offset",
        fmt::format("{:#x}", pending.bound_slice_relative_offset));
    row("producer_snapshot_matches_b3", 1);
    row("producer_snapshot_covers_draw", 1);
    row("compute_sequence_at_draw", pending.compute_sequence_at_draw);
    row("producer_to_draw_dispatch_delta",
        pending.compute_sequence_at_draw - pending.producer.dispatch_sequence);
    row("gpu_modified_before_read", pending.gpu_modified_before_read);
    row("changed_from_guest_backing_words", changed_from_guest_backing);
    row("guest_words_before_hash", fmt::format("{:#018x}", pending.guest_words_before_hash));
    row("settled_slice_word_hash", fmt::format("{:#018x}", settled_word_hash));
    row("settled_slice_byte_hash", fmt::format("{:#018x}", settled_byte_hash));
    row("word1_groups", word1_groups.size());
    row("word0_low24_groups", low24_groups.size());
    row("readback", "exact settled Vulkan bindings 0 and 3 copied to download buffers");
    row("synchronization",
        "draw-side producer settle, then an exact bound-buffer transfer and finish before draw");
    row("remaining_caveat",
        "producer identity is a descriptor/sequence handoff; reuse of the same base has no "
        "immutable guest generation ID");
    row("producer_input_caveat",
        "bindings 1 and 2 are descriptor-only; exact producer-time contents require a separate "
        "dispatch-side capture");

    const auto write_verified_text = [](const std::filesystem::path& file,
                                        std::string_view text) {
        const std::span<const u8> bytes{reinterpret_cast<const u8*>(text.data()), text.size()};
        return WriteDreamsCaptureText(file, text) &&
               VerifyDreamsCaptureBytes(file, bytes, HashDreamsTraceBytes(bytes));
    };
    u64 slice_file_hash{};
    bool files_ok = WriteDreamsCaptureWords(capture.directory / "b3-list-slice.bin",
                                             settled_words, slice_file_hash);
    files_ok &= slice_file_hash == settled_byte_hash;
    files_ok &= VerifyDreamsCaptureBytes(capture.directory / "b3-list-slice.bin", settled_bytes,
                                         settled_byte_hash);
    u64 command_file_hash{};
    files_ok &= WriteDreamsCaptureWords(capture.directory / "draw-command.bin", command_words,
                                        command_file_hash);
    files_ok &= command_file_hash == command_byte_hash;
    files_ok &= VerifyDreamsCaptureBytes(capture.directory / "draw-command.bin", command_bytes,
                                         command_byte_hash);
    u64 b0_rows_file_hash{};
    files_ok &= WriteDreamsCaptureBytes(capture.directory / "b0-object-rows-0-10.bin",
                                        b0_rows_bytes, b0_rows_file_hash);
    files_ok &= b0_rows_file_hash == b0_rows_byte_hash;
    files_ok &= VerifyDreamsCaptureBytes(capture.directory / "b0-object-rows-0-10.bin",
                                         b0_rows_bytes, b0_rows_byte_hash);
    files_ok &= write_verified_text(capture.directory / "records.tsv", records);
    files_ok &= write_verified_text(capture.directory / "b0-object-rows-0-10.tsv",
                                    b0_inventory);
    files_ok &= write_verified_text(capture.directory / "word1-groups.tsv", word1_inventory);
    files_ok &= write_verified_text(capture.directory / "word0-low24-groups.tsv",
                                    low24_inventory);
    files_ok &= write_verified_text(capture.directory / "manifest.tsv", manifest);
    if (!files_ok) {
        fail("one or more list-slice output files failed write-back verification");
        return;
    }

    std::error_code error;
    std::filesystem::remove(capture.directory / "failed.txt", error);
    if (error || std::filesystem::is_regular_file(capture.directory / "failed.txt", error) ||
        error) {
        fail("verified outputs were written but a stale failure marker could not be removed");
        return;
    }
    if (!WriteDreamsCaptureCompletionMarker(capture.directory)) {
        fail("the verified list-slice outputs were written but the completion marker failed");
        return;
    }
    capture.armed = false;
    capture.complete = true;
    capture.failed = false;
    LOG_WARNING(Render_Vulkan,
                "Dreams VS370 list-slice capture complete instances={} first_record={} "
                "word1_groups={} low24_groups={} word_hash={:#x} byte_hash={:#x} "
                "changed_from_guest={} directory={}",
                pending.command.instanceCount, pending.first_record, word1_groups.size(),
                low24_groups.size(), settled_word_hash, settled_byte_hash,
                changed_from_guest_backing, capture.directory.string());
}

static std::optional<std::filesystem::path> ConsumeDreams7baProvenanceRequest() {
    auto& capture = g_dreams_7ba_provenance_capture;
    if (capture.active || capture.waiting_for_consumer || capture.consumer_active ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return std::nullopt;
    }
    const char* directory_value =
        std::getenv("SHADPS4_DREAMS_7BA_PROVENANCE_CAPTURE_DIR");
    if (directory_value == nullptr || directory_value[0] == '\0') {
        return std::nullopt;
    }
    const std::filesystem::path directory{directory_value};
    const char* trigger_value =
        std::getenv("SHADPS4_DREAMS_7BA_PROVENANCE_TRIGGER_FILE");
    const std::filesystem::path trigger =
        trigger_value != nullptr && trigger_value[0] != '\0'
            ? std::filesystem::path{trigger_value}
            : directory / "capture.request";
    std::error_code error;
    if (!std::filesystem::remove(trigger, error)) {
        return std::nullopt;
    }
    error.clear();
    std::filesystem::create_directories(directory, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Dreams 7ba provenance cannot create {}: {}",
                  directory.string(), error.message());
        return std::nullopt;
    }
    capture = {};
    capture.output_dir = directory;
    if (!WriteDreamsCaptureText(directory / "producer-passes.tsv",
                                "pass\tproducer_sequence\taccepted_transition\t"
                                "accepted_or_preexisting\trecords_post_hash\n")) {
        return std::nullopt;
    }
    return directory;
}

static std::optional<std::filesystem::path> AcquireDreams7baProvenanceRequest() {
    auto& capture = g_dreams_7ba_provenance_capture;
    if (capture.retry_next_producer && !capture.active && !capture.waiting_for_consumer &&
        !capture.consumer_active && !capture.failed) {
        capture.retry_next_producer = false;
        return capture.output_dir;
    }
    return ConsumeDreams7baProvenanceRequest();
}

static void FailDreams7baProvenance(std::string_view reason) {
    auto& capture = g_dreams_7ba_provenance_capture;
    capture.failed = true;
    capture.active = false;
    capture.waiting_for_consumer = false;
    capture.consumer_active = false;
    LOG_ERROR(Render_Vulkan, "Dreams 7ba provenance failed: {}", reason);
    if (!capture.output_dir.empty()) {
        WriteDreamsCaptureText(capture.output_dir / "failed.txt", fmt::format("{}\n", reason));
    }
}

static std::string Sha256DreamsCapture(std::span<const u8> bytes) {
    static constexpr std::array<u32, 64> K{
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
        0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
        0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
        0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
        0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
        0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
        0xc67178f2,
    };
    std::array<u32, 8> state{
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    };
    std::vector<u8> padded(bytes.begin(), bytes.end());
    const u64 bit_count = static_cast<u64>(bytes.size()) * 8;
    padded.push_back(0x80);
    while ((padded.size() & 63) != 56) {
        padded.push_back(0);
    }
    for (s32 shift = 56; shift >= 0; shift -= 8) {
        padded.push_back(static_cast<u8>(bit_count >> shift));
    }
    for (size_t block = 0; block < padded.size(); block += 64) {
        std::array<u32, 64> words{};
        for (u32 word = 0; word < 16; ++word) {
            const size_t offset = block + word * 4;
            words[word] = (u32{padded[offset]} << 24) | (u32{padded[offset + 1]} << 16) |
                          (u32{padded[offset + 2]} << 8) | u32{padded[offset + 3]};
        }
        for (u32 word = 16; word < words.size(); ++word) {
            const u32 s0 = std::rotr(words[word - 15], 7) ^ std::rotr(words[word - 15], 18) ^
                           (words[word - 15] >> 3);
            const u32 s1 = std::rotr(words[word - 2], 17) ^ std::rotr(words[word - 2], 19) ^
                           (words[word - 2] >> 10);
            words[word] = words[word - 16] + s0 + words[word - 7] + s1;
        }
        auto [a, b, c, d, e, f, g, h] = state;
        for (u32 round = 0; round < words.size(); ++round) {
            const u32 sum1 = std::rotr(e, 6) ^ std::rotr(e, 11) ^ std::rotr(e, 25);
            const u32 choose = (e & f) ^ (~e & g);
            const u32 temp1 = h + sum1 + choose + K[round] + words[round];
            const u32 sum0 = std::rotr(a, 2) ^ std::rotr(a, 13) ^ std::rotr(a, 22);
            const u32 majority = (a & b) ^ (a & c) ^ (b & c);
            const u32 temp2 = sum0 + majority;
            h = g;
            g = f;
            f = e;
            e = d + temp1;
            d = c;
            c = b;
            b = a;
            a = temp1 + temp2;
        }
        state[0] += a;
        state[1] += b;
        state[2] += c;
        state[3] += d;
        state[4] += e;
        state[5] += f;
        state[6] += g;
        state[7] += h;
    }
    return fmt::format("{:08x}{:08x}{:08x}{:08x}{:08x}{:08x}{:08x}{:08x}", state[0], state[1],
                       state[2], state[3], state[4], state[5], state[6], state[7]);
}

