enum class DreamsBrushstrokeLimitTraceRole : u8 {
    None,
    Reset,
    SpriteEmit,
    CopyStats,
};

struct DreamsBrushstrokeLimitTraceState {
    bool active{};
    bool reset_seen{};
    bool sprite_seen{};
    u32 generation{};
    u32 remaining{};
};

static DreamsBrushstrokeLimitTraceState g_dreams_brushstroke_limit_trace;

static DreamsBrushstrokeLimitTraceRole DreamsBrushstrokeLimitRole(u64 hash, bool indirect) {
    if (!indirect && hash == 0x19b50176) {
        return DreamsBrushstrokeLimitTraceRole::Reset;
    }
    if (indirect && (hash == 0xe4dcd599 || hash == 0xfd2a2c3b)) {
        return DreamsBrushstrokeLimitTraceRole::SpriteEmit;
    }
    if (!indirect && hash == 0x77179b49) {
        return DreamsBrushstrokeLimitTraceRole::CopyStats;
    }
    return DreamsBrushstrokeLimitTraceRole::None;
}

static void PollDreamsBrushstrokeLimitTraceRequest() {
    if (g_dreams_brushstroke_limit_trace.active ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return;
    }
    const char* trigger_file = std::getenv("SHADPS4_DREAMS_BRUSHSTROKE_LIMIT_TRACE_TRIGGER_FILE");
    if (trigger_file == nullptr || trigger_file[0] == '\0') {
        return;
    }
    std::error_code error;
    if (!std::filesystem::remove(trigger_file, error)) {
        return;
    }
    g_dreams_brushstroke_limit_trace = {
        .active = true,
        .generation = g_dreams_brushstroke_limit_trace.generation + 1,
        .remaining = 16,
    };
    LOG_WARNING(Render_Vulkan, "Dreams brushstroke-limit trace #{} armed",
                g_dreams_brushstroke_limit_trace.generation);
}

static bool BeginDreamsBrushstrokeLimitTrace(DreamsBrushstrokeLimitTraceRole role) {
    if (role == DreamsBrushstrokeLimitTraceRole::None) {
        return false;
    }
    PollDreamsBrushstrokeLimitTraceRequest();
    auto& trace = g_dreams_brushstroke_limit_trace;
    if (!trace.active || trace.remaining == 0) {
        return false;
    }
    if (role == DreamsBrushstrokeLimitTraceRole::Reset) {
        // A reset begins the only coherent Reset -> SpriteEmit -> CopyStats chain. If the trigger
        // arrived halfway through an older chain, discard those partial role markers here.
        trace.reset_seen = true;
        trace.sprite_seen = false;
    } else if (!trace.reset_seen) {
        return false;
    } else if (role == DreamsBrushstrokeLimitTraceRole::SpriteEmit && trace.sprite_seen) {
        return false;
    }
    --trace.remaining;
    return true;
}

static void EndDreamsBrushstrokeLimitTrace(DreamsBrushstrokeLimitTraceRole role) {
    auto& trace = g_dreams_brushstroke_limit_trace;
    if (!trace.active) {
        return;
    }
    if (role == DreamsBrushstrokeLimitTraceRole::SpriteEmit) {
        trace.sprite_seen = true;
    } else if (role == DreamsBrushstrokeLimitTraceRole::CopyStats && trace.reset_seen &&
               trace.sprite_seen) {
        LOG_WARNING(Render_Vulkan, "Dreams brushstroke-limit trace #{} complete", trace.generation);
        trace.active = false;
        return;
    }
    if (trace.remaining == 0) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams brushstroke-limit trace #{} stopped after bounded target budget",
                    trace.generation);
        trace.active = false;
    }
}

