static bool ConsumeDreamsCountChainTraceRequest() {
    if (!TraceDreamsSlowDrawArgs() || Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return false;
    }
    const auto window_config = GetDreamsD25CaptureWindowConfig();
    // A configured window enumerates D25 draws directly. Preserve the original paired-902
    // one-shot when the window environment variable is absent.
    if (window_config.configured) {
        return false;
    }
    const char* trigger_file = std::getenv("SHADPS4_DREAMS_GEOMETRY_TRACE_TRIGGER_FILE");
    if (trigger_file == nullptr || trigger_file[0] == '\0') {
        return false;
    }
    std::error_code error;
    if (!std::filesystem::remove(trigger_file, error)) {
        return false;
    }
    g_dreams_d25_capture_window = {
        .active = true,
        .use_occurrence_directories = window_config.configured,
        .total = window_config.count,
        .remaining = window_config.count,
        .occurrence_index = 0,
        .direct_draw_mode = false,
    };
    // The pre-902 capture consumes the trigger. Arm the matched d25/3f6 draw; a configured window
    // automatically repeats this exact producer-to-consumer chain after each nonempty capture.
    g_dreams_sprite_geometry_trace_remaining = 1;
    LOG_WARNING(Render_Vulkan,
                "Dreams D25 capture window start total={} occurrence=occ{:03} subdirectories={}",
                g_dreams_d25_capture_window.total, g_dreams_d25_capture_window.occurrence_index,
                g_dreams_d25_capture_window.use_occurrence_directories);
    return true;
}

static bool PollDreamsD25DirectCaptureWindow() {
    if (!TraceDreamsSlowDrawArgs() || Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return false;
    }
    const auto window_config = GetDreamsD25CaptureWindowConfig();
    if (!window_config.configured) {
        return false;
    }
    if (g_dreams_d25_capture_window.active) {
        return g_dreams_d25_capture_window.direct_draw_mode;
    }
    const char* trigger_file = std::getenv("SHADPS4_DREAMS_GEOMETRY_TRACE_TRIGGER_FILE");
    if (trigger_file == nullptr || trigger_file[0] == '\0') {
        return false;
    }
    std::error_code error;
    if (!std::filesystem::remove(trigger_file, error)) {
        return false;
    }
    g_dreams_d25_capture_window = {
        .active = true,
        .use_occurrence_directories = true,
        .total = window_config.count,
        .remaining = window_config.count,
        .occurrence_index = 0,
        .direct_draw_mode = true,
    };
    g_dreams_count_chain_capture = {};
    g_dreams_count_chain_capture_retry = false;
    g_dreams_sprite_geometry_trace_remaining = 0;
    g_dreams_d25_selector_pre_alias = {};
    LOG_WARNING(Render_Vulkan,
                "Dreams D25 direct capture window start total={} occurrence=occ{:03}",
                g_dreams_d25_capture_window.total, g_dreams_d25_capture_window.occurrence_index);
    return true;
}

