struct DreamsD25LiveSelectorControl {
    bool environment_checked{};
    bool control_seen{};
    bool enabled{};
    bool mismatch_logged{};
    u64 generation{};
    u64 last_applied_generation{};
    std::filesystem::path control_path;
    std::filesystem::path candidate_path;
    std::filesystem::file_time_type observed_control_time{};
    std::filesystem::file_time_type observed_candidate_time{};
    std::uintmax_t observed_control_size{};
    std::uintmax_t observed_candidate_size{};
    std::chrono::steady_clock::time_point next_poll{};
    DreamsD25LiveSelectorFingerprint fingerprint;
    std::vector<u8> candidate_bytes;
};

static DreamsD25LiveSelectorControl g_dreams_d25_live_selector;

static std::string_view TrimDreamsD25ControlValue(std::string_view value) {
    constexpr std::string_view Whitespace = " \t\r\n";
    const auto first = value.find_first_not_of(Whitespace);
    if (first == std::string_view::npos) {
        return {};
    }
    const auto last = value.find_last_not_of(Whitespace);
    return value.substr(first, last - first + 1);
}

static bool ParseDreamsD25ControlNumber(std::string_view value, u64& output) {
    const std::string text{TrimDreamsD25ControlValue(value)};
    if (text.empty() || text.front() == '-') {
        return false;
    }
    char* end{};
    const u64 parsed = std::strtoull(text.c_str(), &end, 0);
    if (end == text.c_str() || *end != '\0') {
        return false;
    }
    output = parsed;
    return true;
}

static bool ParseDreamsD25LiveSelectorControl(const std::filesystem::path& control_path,
                                              std::filesystem::path& candidate_path,
                                              DreamsD25LiveSelectorFingerprint& fingerprint,
                                              bool& enabled, std::string& error) {
    std::ifstream input{control_path};
    if (!input) {
        error = "control file could not be opened";
        return false;
    }

    enabled = true;
    bool candidate_seen{};
    std::string line;
    u32 line_number{};
    while (std::getline(input, line)) {
        ++line_number;
        const std::string_view trimmed = TrimDreamsD25ControlValue(line);
        if (trimmed.empty() || trimmed.front() == '#') {
            continue;
        }
        const auto separator = trimmed.find_first_of("=\t");
        if (separator == std::string_view::npos) {
            error = fmt::format("line {} has no '=' or tab separator", line_number);
            return false;
        }
        const std::string_view key = TrimDreamsD25ControlValue(trimmed.substr(0, separator));
        const std::string_view value = TrimDreamsD25ControlValue(trimmed.substr(separator + 1));
        if (key == "candidate" || key == "candidate_path") {
            candidate_path = std::filesystem::path{std::string{value}};
            candidate_seen = !candidate_path.empty();
            continue;
        }

        u64 parsed{};
        if (!ParseDreamsD25ControlNumber(value, parsed)) {
            error = fmt::format("line {} field '{}' is not an unsigned integer", line_number, key);
            return false;
        }
        const auto parse_u32 = [&](std::optional<u32>& field) {
            if (parsed > std::numeric_limits<u32>::max()) {
                return false;
            }
            field = static_cast<u32>(parsed);
            return true;
        };
        if (key == "enabled") {
            if (parsed > 1) {
                error = fmt::format("line {} enabled must be 0 or 1", line_number);
                return false;
            }
            enabled = parsed != 0;
        } else if (key == "schema") {
            if (parsed != 1) {
                error = fmt::format("line {} unsupported schema {}", line_number, parsed);
                return false;
            }
        } else if (key == "commands_address" || key == "commands_base") {
            fingerprint.commands_address = parsed;
        } else if (key == "count_address") {
            fingerprint.count_address = parsed;
        } else if (key == "stride" || key == "commands_stride") {
            if (!parse_u32(fingerprint.stride)) {
                error = fmt::format("line {} stride exceeds u32", line_number);
                return false;
            }
        } else if (key == "max_count") {
            if (!parse_u32(fingerprint.max_count)) {
                error = fmt::format("line {} max_count exceeds u32", line_number);
                return false;
            }
        } else if (key == "draw_count") {
            if (!parse_u32(fingerprint.draw_count)) {
                error = fmt::format("line {} draw_count exceeds u32", line_number);
                return false;
            }
        } else if (key == "commands_hash") {
            fingerprint.commands_hash = parsed;
        } else if (key == "selector_base") {
            fingerprint.selector_base = parsed;
        } else if (key == "selector_size") {
            fingerprint.selector_size = parsed;
        } else if (key == "transform_address") {
            fingerprint.transform_address = parsed;
        } else if (key == "framebuffer_width") {
            if (!parse_u32(fingerprint.framebuffer_width)) {
                error = fmt::format("line {} framebuffer_width exceeds u32", line_number);
                return false;
            }
        } else if (key == "framebuffer_height") {
            if (!parse_u32(fingerprint.framebuffer_height)) {
                error = fmt::format("line {} framebuffer_height exceeds u32", line_number);
                return false;
            }
        } else if (key == "screen_scissor_left") {
            if (!parse_u32(fingerprint.screen_scissor_left)) {
                error = fmt::format("line {} screen_scissor_left exceeds u32", line_number);
                return false;
            }
        } else if (key == "screen_scissor_top") {
            if (!parse_u32(fingerprint.screen_scissor_top)) {
                error = fmt::format("line {} screen_scissor_top exceeds u32", line_number);
                return false;
            }
        } else if (key == "screen_scissor_right") {
            if (!parse_u32(fingerprint.screen_scissor_right)) {
                error = fmt::format("line {} screen_scissor_right exceeds u32", line_number);
                return false;
            }
        } else if (key == "screen_scissor_bottom") {
            if (!parse_u32(fingerprint.screen_scissor_bottom)) {
                error = fmt::format("line {} screen_scissor_bottom exceeds u32", line_number);
                return false;
            }
        } else {
            error = fmt::format("line {} has unknown field '{}'", line_number, key);
            return false;
        }
    }
    if (!input.eof()) {
        error = "control file could not be read completely";
        return false;
    }
    if (!enabled) {
        return true;
    }
    if (!candidate_seen) {
        error = "enabled control has no candidate path";
        return false;
    }
    if (candidate_path.is_relative()) {
        candidate_path = control_path.parent_path() / candidate_path;
    }
    candidate_path = candidate_path.lexically_normal();
    return true;
}

static bool ReadDreamsD25LiveSelectorCandidate(const std::filesystem::path& candidate_path,
                                               std::vector<u8>& bytes,
                                               std::filesystem::file_time_type& write_time,
                                               std::uintmax_t& file_size, std::string& error) {
    std::error_code fs_error;
    write_time = std::filesystem::last_write_time(candidate_path, fs_error);
    if (fs_error) {
        error = "candidate file is missing";
        return false;
    }
    file_size = std::filesystem::file_size(candidate_path, fs_error);
    constexpr std::uintmax_t MaxCandidateBytes = 8_MB;
    if (fs_error || file_size == 0 || file_size > MaxCandidateBytes || (file_size & 3) != 0) {
        error = "candidate must be a non-empty little-endian u32 file no larger than 8 MiB";
        return false;
    }
    std::ifstream input{candidate_path, std::ios::binary};
    std::vector<u8> candidate(static_cast<size_t>(file_size));
    if (!input || !input.read(reinterpret_cast<char*>(candidate.data()), candidate.size())) {
        error = "candidate file could not be read completely";
        return false;
    }
    bytes = std::move(candidate);
    return true;
}

static bool PollDreamsD25LiveSelectorControl() {
    auto& state = g_dreams_d25_live_selector;
    if (state.control_path.empty()) {
        if (state.environment_checked) {
            return false;
        }
        state.environment_checked = true;
        const char* value = std::getenv("SHADPS4_DREAMS_D25_LIVE_SELECTOR_CONTROL_FILE");
        if (value == nullptr || value[0] == '\0') {
            return false;
        }
        state.control_path = std::filesystem::path{value};
    }

    const auto now = std::chrono::steady_clock::now();
    if (now < state.next_poll) {
        return state.enabled;
    }
    state.next_poll = now + std::chrono::milliseconds{100};

    std::error_code fs_error;
    const auto control_time = std::filesystem::last_write_time(state.control_path, fs_error);
    const auto control_size =
        !fs_error ? std::filesystem::file_size(state.control_path, fs_error) : 0;
    if (fs_error) {
        if (state.control_seen) {
            LOG_WARNING(Render_Vulkan, "Dreams D25 live selector disabled: control file removed");
        }
        state.control_seen = false;
        state.enabled = false;
        state.candidate_bytes.clear();
        return false;
    }

    const bool control_changed = !state.control_seen ||
                                 control_time != state.observed_control_time ||
                                 control_size != state.observed_control_size;
    state.control_seen = true;
    if (control_changed) {
        // Record the attempted version before parsing so a malformed file emits one status line,
        // then wait for the UI's next atomic replacement instead of spamming every frame.
        state.observed_control_time = control_time;
        state.observed_control_size = control_size;

        std::filesystem::path candidate_path;
        DreamsD25LiveSelectorFingerprint fingerprint;
        bool enabled{};
        std::string error;
        if (!ParseDreamsD25LiveSelectorControl(state.control_path, candidate_path, fingerprint,
                                               enabled, error)) {
            LOG_ERROR(Render_Vulkan, "Dreams D25 live selector control rejected: {}", error);
            return state.enabled;
        }
        if (!enabled) {
            state.enabled = false;
            state.candidate_path.clear();
            state.candidate_bytes.clear();
            state.fingerprint = {};
            state.mismatch_logged = false;
            ++state.generation;
            LOG_WARNING(Render_Vulkan, "Dreams D25 live selector disabled by control generation={}",
                        state.generation);
            return false;
        }

        std::vector<u8> candidate_bytes;
        std::filesystem::file_time_type candidate_time{};
        std::uintmax_t candidate_size{};
        if (!ReadDreamsD25LiveSelectorCandidate(candidate_path, candidate_bytes, candidate_time,
                                                candidate_size, error)) {
            LOG_ERROR(Render_Vulkan, "Dreams D25 live selector candidate rejected path={} error={}",
                      candidate_path.string(), error);
            return state.enabled;
        }
        state.enabled = true;
        state.candidate_path = std::move(candidate_path);
        state.candidate_bytes = std::move(candidate_bytes);
        state.fingerprint = std::move(fingerprint);
        state.observed_candidate_time = candidate_time;
        state.observed_candidate_size = candidate_size;
        state.mismatch_logged = false;
        ++state.generation;
        LOG_WARNING(Render_Vulkan,
                    "Dreams D25 live selector loaded generation={} path={} words={} "
                    "fingerprinted={} command_readback={}",
                    state.generation, state.candidate_path.string(),
                    state.candidate_bytes.size() / sizeof(u32),
                    state.fingerprint.commands_address.has_value() ||
                        state.fingerprint.count_address.has_value() ||
                        state.fingerprint.selector_base.has_value() ||
                        state.fingerprint.transform_address.has_value() ||
                        state.fingerprint.framebuffer_width.has_value(),
                    state.fingerprint.NeedsCommandReadback());
        return true;
    }

    if (!state.enabled) {
        return false;
    }
    const auto candidate_time = std::filesystem::last_write_time(state.candidate_path, fs_error);
    const auto candidate_size =
        !fs_error ? std::filesystem::file_size(state.candidate_path, fs_error) : 0;
    if (fs_error || (candidate_time == state.observed_candidate_time &&
                     candidate_size == state.observed_candidate_size)) {
        return true;
    }

    std::vector<u8> candidate_bytes;
    std::filesystem::file_time_type loaded_time{};
    std::uintmax_t loaded_size{};
    std::string error;
    if (!ReadDreamsD25LiveSelectorCandidate(state.candidate_path, candidate_bytes, loaded_time,
                                            loaded_size, error)) {
        LOG_ERROR(Render_Vulkan, "Dreams D25 live selector reload rejected path={} error={}",
                  state.candidate_path.string(), error);
        return true;
    }
    state.candidate_bytes = std::move(candidate_bytes);
    state.observed_candidate_time = loaded_time;
    state.observed_candidate_size = loaded_size;
    state.mismatch_logged = false;
    ++state.generation;
    LOG_WARNING(Render_Vulkan, "Dreams D25 live selector reloaded generation={} path={} words={}",
                state.generation, state.candidate_path.string(),
                state.candidate_bytes.size() / sizeof(u32));
    return true;
}

static bool SyncDreamsImageBufferAliases() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_IMAGE_BUFFER_ALIAS_SYNC");
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static void ApplyDreamsA3a9BdaPrewarm(const Shader::Info& info, Core::MemoryManager* memory,
                                       VideoCore::BufferCache& buffer_cache) {
    if (!PrewarmDreamsA3a9BdaConstants() || info.pgm_hash != DreamsPackedPositionProducerShader) {
        return;
    }

    // a3a9e9ef performs dynamic ReadConst loads from SGPR5:SGPR4. Its buffer 4 is a
    // u32 lookup table: flattened[0x44] selects the final lookup entry, and the
    // largest lookup value is the actual dynamic-read count. A first-use BDA fault
    // is serviced only after this producer has already dispatched, so publish and
    // synchronize that exact range once per root before BindResources submits it.
    constexpr VAddr BdaAddressLimit = VAddr{VideoCore::BufferCache::CACHING_NUMPAGES}
                                      << VideoCore::BufferCache::CACHING_PAGEBITS;
    constexpr u64 FirstDynamicByte = 6 * sizeof(u32);
    const bool has_user_data = info.user_data.size() > 5;
    const bool has_selector_limit = info.flattened_ud_buf.size() > 0x44;
    VAddr root_base{};
    if (has_user_data) {
        root_base = VAddr{info.user_data[4]} | (VAddr{info.user_data[5]} << 32);
    }

    static std::array<VAddr, 8> attempted_roots{};
    static u32 attempted_root_count{};
    if (root_base == 0) {
        static bool logged_missing_root{};
        if (!logged_missing_root) {
            logged_missing_root = true;
            LOG_WARNING(Render_Vulkan,
                        "Dreams a3a9 BDA prewarm success=false reason=missing_root "
                        "userdata={} selector_limit={}",
                        has_user_data, has_selector_limit);
        }
        return;
    }
    if (std::find(attempted_roots.begin(), attempted_roots.begin() + attempted_root_count,
                  root_base) != attempted_roots.begin() + attempted_root_count) {
        return;
    }
    if (attempted_root_count == attempted_roots.size()) {
        static bool logged_capacity{};
        if (!logged_capacity) {
            logged_capacity = true;
            LOG_WARNING(Render_Vulkan,
                        "Dreams a3a9 BDA prewarm success=false reason=root_capacity root={:#x}",
                        root_base);
        }
        return;
    }
    attempted_roots[attempted_root_count++] = root_base;

    const bool has_lookup = info.buffers.size() > 4 && !info.buffers[4].IsSpecial();
    if (!has_selector_limit || !has_lookup) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams a3a9 BDA prewarm success=false reason=missing_metadata root={:#x} "
                    "selector_limit={} lookup={}",
                    root_base, has_selector_limit, has_lookup);
        return;
    }

    const u32 selector_limit = info.flattened_ud_buf[0x44];
    const auto lookup = info.buffers[4].GetSharp(info);
    const u64 lookup_size = lookup.GetSize();
    const u64 lookup_records = lookup.stride == sizeof(u32) ? lookup_size / sizeof(u32) : 0;
    const u64 requested_scan_count = u64{selector_limit} + 1;
    const u64 scan_count = std::min(requested_scan_count, lookup_records);
    const u64 scan_bytes = scan_count * sizeof(u32);
    const bool selector_covered = requested_scan_count <= lookup_records;
    const bool scan_size_fits_u32 = scan_bytes <= std::numeric_limits<u32>::max();
    const bool lookup_address_in_range = lookup.base_address != 0 &&
                                         lookup.base_address < BdaAddressLimit &&
                                         scan_bytes <= BdaAddressLimit - lookup.base_address;
    const bool lookup_mapped = scan_size_fits_u32 && lookup_address_in_range && scan_bytes != 0 &&
                               memory->IsValidMapping(lookup.base_address, scan_bytes);
    if (lookup.stride != sizeof(u32) || !selector_covered || !lookup_mapped) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams a3a9 BDA prewarm success=false reason=invalid_lookup root={:#x} "
                    "H={} lookup={:#x}+{:#x} stride={} records={} scan_count={} scan_bytes={:#x} "
                    "covered={} size_u32={} in_range={} mapped={}",
                    root_base, selector_limit, lookup.base_address, lookup_size, lookup.stride,
                    lookup_records, scan_count, scan_bytes, selector_covered, scan_size_fits_u32,
                    lookup_address_in_range, lookup_mapped);
        return;
    }

    const bool lookup_gpu_before =
        buffer_cache.IsRegionGpuModified(lookup.base_address, scan_bytes);
    buffer_cache.ReadMemory(lookup.base_address, scan_bytes);
    const bool lookup_gpu_after = buffer_cache.IsRegionGpuModified(lookup.base_address, scan_bytes);
    if (lookup_gpu_after) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams a3a9 BDA prewarm success=false reason=lookup_still_gpu_modified "
                    "root={:#x} H={} lookup={:#x}+{:#x} scan_count={} scan_bytes={:#x} "
                    "gpu_before={} gpu_after={}",
                    root_base, selector_limit, lookup.base_address, lookup_size, scan_count,
                    scan_bytes, lookup_gpu_before, lookup_gpu_after);
        return;
    }
    const auto* lookup_words = std::bit_cast<const u32*>(lookup.base_address);
    u32 dynamic_count{};
    u64 dynamic_count_index{};
    for (u64 index = 0; index < scan_count; ++index) {
        if (lookup_words[index] > dynamic_count) {
            dynamic_count = lookup_words[index];
            dynamic_count_index = index;
        }
    }

    if (dynamic_count == 0) {
        LOG_WARNING(
            Render_Vulkan,
            "Dreams a3a9 BDA prewarm success=true root={:#x} H={} lookup={:#x}+{:#x} "
            "stride={} records={} scan_count={} scan_bytes={:#x} gpu_before={} gpu_after={} "
            "Nmax=0 Nmax_index=0 dynamic_bytes=0",
            root_base, selector_limit, lookup.base_address, lookup_size, lookup.stride,
            lookup_records, scan_count, scan_bytes, lookup_gpu_before, lookup_gpu_after);
        return;
    }

    constexpr u32 MaxDynamicCount = 0x3ffffffa;
    const bool size_fits_u32 = dynamic_count <= MaxDynamicCount;
    const u64 dynamic_bytes = u64{dynamic_count} * sizeof(u32);
    const bool dynamic_address_in_range =
        root_base < BdaAddressLimit && FirstDynamicByte <= BdaAddressLimit - root_base &&
        dynamic_bytes <= BdaAddressLimit - (root_base + FirstDynamicByte);
    const VAddr dynamic_address = dynamic_address_in_range ? root_base + FirstDynamicByte : VAddr{};
    const bool dynamic_mapped = size_fits_u32 && dynamic_address_in_range &&
                                memory->IsValidMapping(dynamic_address, dynamic_bytes);
    if (!size_fits_u32 || !dynamic_mapped) {
        LOG_WARNING(
            Render_Vulkan,
            "Dreams a3a9 BDA prewarm success=false reason=invalid_dynamic root={:#x} H={} "
            "lookup={:#x}+{:#x} stride={} records={} scan_count={} scan_bytes={:#x} "
            "gpu_before={} gpu_after={} Nmax={} Nmax_index={} address={:#x}+{:#x} size_u32={} "
            "in_range={} mapped={}",
            root_base, selector_limit, lookup.base_address, lookup_size, lookup.stride,
            lookup_records, scan_count, scan_bytes, lookup_gpu_before, lookup_gpu_after,
            dynamic_count, dynamic_count_index, dynamic_address, dynamic_bytes, size_fits_u32,
            dynamic_address_in_range, dynamic_mapped);
        return;
    }

    const bool registered_before = buffer_cache.IsRegionRegistered(dynamic_address, dynamic_bytes);
    const bool dynamic_gpu_before =
        buffer_cache.IsRegionGpuModified(dynamic_address, dynamic_bytes);
    const VideoCore::BufferId buffer_id =
        buffer_cache.FindBuffer(dynamic_address, static_cast<u32>(dynamic_bytes));
    buffer_cache.SynchronizeBuffersInRange(dynamic_address, dynamic_bytes);
    const bool registered_after = buffer_cache.IsRegionRegistered(dynamic_address, dynamic_bytes);
    LOG_WARNING(
        Render_Vulkan,
        "Dreams a3a9 BDA prewarm success=true root={:#x} H={} lookup={:#x}+{:#x} "
        "stride={} records={} scan_count={} scan_bytes={:#x} gpu_before={} gpu_after={} "
        "Nmax={} Nmax_index={} address={:#x}+{:#x} in_range={} mapped={} registered_before={} "
        "registered_after={} dynamic_gpu_before={} buffer_id={}",
        root_base, selector_limit, lookup.base_address, lookup_size, lookup.stride, lookup_records,
        scan_count, scan_bytes, lookup_gpu_before, lookup_gpu_after, dynamic_count,
        dynamic_count_index, dynamic_address, dynamic_bytes, dynamic_address_in_range,
        dynamic_mapped, registered_before, registered_after, dynamic_gpu_before, buffer_id.index);
}

static std::vector<u32> SnapshotDreamsBufferDescriptors(const Shader::Info& info) {
    static_assert(sizeof(AmdGpu::Buffer) == 4 * sizeof(u32));
    std::vector<u32> descriptors(info.buffers.size() * 4);
    for (u32 index = 0; index < info.buffers.size(); ++index) {
        const auto sharp = info.buffers[index].GetSharp(info);
        std::memcpy(descriptors.data() + index * 4, &sharp, sizeof(sharp));
    }
    return descriptors;
}

static bool OverlapsDreamsRange(VAddr lhs_base, u64 lhs_size, VAddr rhs_base, u64 rhs_size);

static bool SnapshotDreamsBufferWords(const Shader::Info& info, u32 binding_index,
                                      Core::MemoryManager* memory,
                                      VideoCore::BufferCache& buffer_cache,
                                      std::vector<u32>& words) {
    constexpr u64 MaxSnapshotBytes = 16_MB;
    if (binding_index >= info.buffers.size() || info.buffers[binding_index].IsSpecial()) {
        return false;
    }
    const auto sharp = info.buffers[binding_index].GetSharp(info);
    const u64 size = sharp.GetSize();
    if (sharp.base_address == 0 || size == 0 || size > MaxSnapshotBytes || (size & 3) != 0 ||
        !memory->IsValidMapping(sharp.base_address, size)) {
        return false;
    }
    buffer_cache.ReadMemory(sharp.base_address, size);
    words.resize(size / sizeof(u32));
    std::memcpy(words.data(), std::bit_cast<const void*>(sharp.base_address), size);
    return true;
}

static bool DreamsMetadataDescriptorsEqual(std::span<const u32> producer,
                                           u32 producer_binding,
                                           std::span<const u32> consumer,
                                           u32 consumer_binding) {
    const u32 producer_offset = producer_binding * 4;
    const u32 consumer_offset = consumer_binding * 4;
    return producer_offset + 4 <= producer.size() && consumer_offset + 4 <= consumer.size() &&
           std::ranges::equal(producer.subspan(producer_offset, 4),
                              consumer.subspan(consumer_offset, 4));
}

static bool DreamsMetadataDescriptorsHandedOff(std::span<const u32> producer,
                                               std::span<const u32> consumer) {
    return DreamsMetadataDescriptorsEqual(producer, 0, consumer, 4) &&
           DreamsMetadataDescriptorsEqual(producer, 2, consumer, 3) &&
           DreamsMetadataDescriptorsEqual(producer, 3, consumer, 8) &&
           DreamsMetadataDescriptorsEqual(producer, 4, consumer, 0);
}

static bool FinalizeDreamsMetadataCapture(VideoCore::Buffer* gds) {
    auto& capture = g_dreams_ordered_chain_capture;
    const auto& root = DreamsOrderedChainCaptureDirectory();
    const bool sequence_ordered = capture.metadata_producer_sequence != 0 &&
                                  capture.metadata_producer_sequence <
                                      capture.metadata_consumer_sequence;
    const bool descriptors_handed_off = DreamsMetadataDescriptorsHandedOff(
        capture.metadata_producer_descriptors, capture.metadata_consumer_descriptors);
    const bool tables_handed_off = capture.metadata_producer_counts_post ==
                                        capture.metadata_consumer_counts_pre &&
                                    capture.metadata_producer_records_post ==
                                        capture.metadata_consumer_records_pre;
    if (!root || !sequence_ordered ||
        !capture.metadata_producer_post_valid || capture.metadata_consumer_sequence == 0 ||
        !capture.metadata_consumer_pre_valid || !descriptors_handed_off ||
        !tables_handed_off) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams metadata capture not ready producer={} producer_valid={} "
                    "consumer={} consumer_valid={} sequence_ordered={} descriptors_handed_off={} "
                    "tables_handed_off={}",
                    capture.metadata_producer_sequence, capture.metadata_producer_post_valid,
                    capture.metadata_consumer_sequence, capture.metadata_consumer_pre_valid,
                    sequence_ordered, descriptors_handed_off, tables_handed_off);
        return false;
    }
    const std::filesystem::path directory = *root / "a3-lookup-producer";
    std::error_code error;
    std::filesystem::create_directories(directory, error);
    if (error || !WriteDreamsMetadataCapture(gds, directory)) {
        WriteDreamsCaptureText(*root / "metadata-failed.txt",
                               "one or more metadata capture files could not be written\n");
        return false;
    }

    std::filesystem::remove(*root / "failed.txt", error);
    error.clear();
    std::filesystem::remove(*root / "capture.request", error);
    if (error) {
        WriteDreamsCaptureText(*root / "metadata-failed.txt",
                               fmt::format("could not consume capture.request: {}\n",
                                           error.message()));
        return false;
    }
    std::filesystem::remove(*root / "metadata-failed.txt", error);
    if (!WriteDreamsCaptureText(*root / "complete.txt", "metadata complete\n")) {
        return false;
    }
    LOG_WARNING(Render_Vulkan,
                "Dreams independent metadata capture complete producer={} consumer={} directory={}",
                capture.metadata_producer_sequence, capture.metadata_consumer_sequence,
                directory.string());
    return true;
}

static void ResetDreamsA3FocusCaptureIfRequested(
    const Shader::Info& info, Scheduler& scheduler, Core::MemoryManager* memory,
    VideoCore::BufferCache& buffer_cache, const std::array<u32, 3>& direct_dims,
    VAddr indirect_args_address = 0) {
    namespace Provenance = Shader::DreamsCompat::B1WriterProvenance;
    auto& capture = g_dreams_ordered_chain_capture;
    if (!Shader::DreamsCompat::CaptureB1WriterProvenance() ||
        Common::ElfInfo::Instance().GameSerial() != "CUSA04301" ||
        !DreamsOrderedChainCaptureRequested()) {
        return;
    }

    const auto resolve_dims = [&] {
        std::array<u32, 3> dims = direct_dims;
        if (indirect_args_address != 0 &&
            memory->IsValidMapping(indirect_args_address, sizeof(dims))) {
            buffer_cache.ReadMemory(indirect_args_address, sizeof(dims));
            std::memcpy(dims.data(), std::bit_cast<const void*>(indirect_args_address),
                        sizeof(dims));
        }
        return dims;
    };
    const auto flat = [&](u32 index) {
        return index < info.flattened_ud_buf.size() ? info.flattened_ud_buf[index] : 0;
    };

    if (info.pgm_hash == DreamsMetadataTableProducerShader) {
        scheduler.Finish();
        if (Shader::DreamsCompat::CaptureA3LookupProducerTrace()) {
            namespace ProducerTrace = Shader::DreamsCompat::A3LookupProducerTrace;
            auto* gds = buffer_cache.GetGdsBuffer();
            constexpr u64 trace_offset =
                static_cast<u64>(ProducerTrace::BaseDword) * sizeof(u32);
            constexpr u64 trace_size =
                static_cast<u64>(ProducerTrace::DwordCount) * sizeof(u32);
            if (trace_offset + trace_size > gds->SizeBytes() ||
                trace_offset + trace_size > gds->mapped_data.size()) {
                FailDreamsOrderedChainCapture(
                    "63dd producer trace range is outside private GDS");
                return;
            }
            gds->Fill(trace_offset, trace_size, 0);
        }
        capture.metadata_producer_armed = true;
        capture.metadata_producer_post_valid = false;
        capture.metadata_producer_sequence = g_compute_dispatch_sequence;
        capture.a3_focus_header_cleared = false;
        capture.metadata_consumer_armed = false;
        capture.metadata_consumer_sequence = 0;
        capture.metadata_consumer_pre_valid = false;
        capture.metadata_consumer_descriptors.clear();
        capture.metadata_consumer_flattened.clear();
        capture.metadata_consumer_counts_pre.clear();
        capture.metadata_consumer_records_pre.clear();
        capture.metadata_producer_dims = resolve_dims();
        capture.metadata_producer_base = flat(0x20);
        capture.metadata_producer_count = flat(0x21);
        capture.metadata_producer_descriptors = SnapshotDreamsBufferDescriptors(info);
        capture.metadata_producer_flattened.assign(info.flattened_ud_buf.begin(),
                                                   info.flattened_ud_buf.end());
        capture.metadata_producer_input_rows_pre.clear();
        capture.metadata_producer_input_keys_pre.clear();
        (void)SnapshotDreamsBufferWords(info, 3, memory, buffer_cache,
                                        capture.metadata_producer_input_rows_pre);
        (void)SnapshotDreamsBufferWords(info, 4, memory, buffer_cache,
                                        capture.metadata_producer_input_keys_pre);
        const u64 producer_end = std::min<u64>(
            u64{capture.metadata_producer_base} + capture.metadata_producer_count,
            capture.metadata_producer_input_rows_pre.size());
        u32 provenance_row_count{};
        for (u64 position = 0; position < producer_end; ++position) {
            const u32 row = capture.metadata_producer_input_rows_pre[position];
            if (row < Provenance::MaxRows) {
                provenance_row_count = std::max(provenance_row_count, row + 1);
            }
        }
        capture.metadata_provenance_row_count = provenance_row_count;
        if (capture.metadata_provenance_row_count != 0) {
            auto* provenance_gds = buffer_cache.GetGdsBuffer();
            const u64 clear_size =
                static_cast<u64>(capture.metadata_provenance_row_count) * sizeof(u32);
            constexpr std::array provenance_bases{
                Provenance::SiteMaskBaseDword,
                Provenance::TagBaseDword,
                Provenance::ValueBaseDword,
                Provenance::SourceBaseDword,
            };
            const u64 last_end = static_cast<u64>(provenance_bases.back()) * sizeof(u32) +
                                 clear_size;
            if (last_end > provenance_gds->SizeBytes() ||
                last_end > provenance_gds->mapped_data.size()) {
                FailDreamsOrderedChainCapture(
                    "A3 compact provenance rows are outside private GDS");
                return;
            }
            for (const u32 base : provenance_bases) {
                provenance_gds->Fill(static_cast<u64>(base) * sizeof(u32), clear_size, 0);
            }
        }
        capture.metadata_focus_row_positions.clear();
        for (u32 position = 0; position < capture.metadata_producer_input_rows_pre.size();
             ++position) {
            const u32 row = capture.metadata_producer_input_rows_pre[position];
            if (row < capture.metadata_producer_input_keys_pre.size() &&
                capture.metadata_producer_input_keys_pre[row] == Provenance::FocusInputV13) {
                capture.metadata_focus_row_positions.push_back(position);
            }
        }
        capture.metadata_focus_header.clear();
        capture.metadata_consumer_attempts.clear();
        capture.metadata_input_writers.clear();
        if (info.buffers.size() > 4 && !info.buffers[3].IsSpecial() &&
            !info.buffers[4].IsSpecial()) {
            const std::array targets{info.buffers[3].GetSharp(info),
                                     info.buffers[4].GetSharp(info)};
            constexpr u32 MaxWriterMatches = 512;
            for (auto writer = g_dreams_buffer_writers.rbegin();
                 writer != g_dreams_buffer_writers.rend() &&
                 capture.metadata_input_writers.size() < MaxWriterMatches;
                 ++writer) {
                if (!writer->declared_write ||
                    writer->dispatch_sequence >= g_compute_dispatch_sequence) {
                    continue;
                }
                u64 target_mask{};
                for (u32 target = 0; target < targets.size(); ++target) {
                    target_mask |= static_cast<u64>(OverlapsDreamsRange(
                                       writer->base, writer->size, targets[target].base_address,
                                       targets[target].GetSize()))
                                   << target;
                }
                if (target_mask != 0) {
                    capture.metadata_input_writers.push_back(
                        DreamsBufferWriterMatch{.writer = *writer,
                                                .target_mask = target_mask});
                }
            }
        }
        capture.metadata_producer_counts_post.clear();
        capture.metadata_producer_records_post.clear();
        LOG_WARNING(
            Render_Vulkan,
            "Dreams metadata producer trace armed sequence={} dims={}x{}x{} base={} count={} "
            "input_rows={} input_keys={} provenance_rows={} focus_positions={} input_writers={}",
            g_compute_dispatch_sequence, capture.metadata_producer_dims[0],
            capture.metadata_producer_dims[1], capture.metadata_producer_dims[2],
            capture.metadata_producer_base, capture.metadata_producer_count,
            capture.metadata_producer_input_rows_pre.size(),
            capture.metadata_producer_input_keys_pre.size(),
            capture.metadata_provenance_row_count,
            capture.metadata_focus_row_positions.size(), capture.metadata_input_writers.size());
        return;
    }

    if (info.pgm_hash != DreamsPackedPositionProducerShader ||
        capture.a3_focus_header_cleared || !capture.metadata_producer_post_valid) {
        return;
    }

    auto* gds = buffer_cache.GetGdsBuffer();
    constexpr u64 offset = static_cast<u64>(Provenance::BaseDword) * sizeof(u32);
    constexpr u64 size = static_cast<u64>(Provenance::HeaderDwords) * sizeof(u32);
    if (offset + size > gds->SizeBytes() || offset + size > gds->mapped_data.size()) {
        FailDreamsOrderedChainCapture("A3 focus trace header is outside private GDS");
        return;
    }
    scheduler.Finish();
    auto consumer_descriptors = SnapshotDreamsBufferDescriptors(info);
    if (!DreamsMetadataDescriptorsHandedOff(capture.metadata_producer_descriptors,
                                            consumer_descriptors)) {
        return;
    }
    std::vector<u32> consumer_counts;
    std::vector<u32> consumer_records;
    const bool consumer_counts_valid =
        SnapshotDreamsBufferWords(info, 4, memory, buffer_cache, consumer_counts);
    const bool consumer_records_valid =
        SnapshotDreamsBufferWords(info, 3, memory, buffer_cache, consumer_records);
    const bool consumer_pre_valid = consumer_counts_valid && consumer_records_valid;
    const bool tables_handed_off = consumer_pre_valid &&
                                     capture.metadata_producer_counts_post == consumer_counts &&
                                     capture.metadata_producer_records_post == consumer_records;
    if (!tables_handed_off) {
        return;
    }
    gds->Fill(offset, size, 0);
    capture.a3_focus_header_cleared = true;
    capture.metadata_consumer_armed = true;
    capture.metadata_consumer_sequence = g_compute_dispatch_sequence;
    capture.metadata_consumer_dims = resolve_dims();
    capture.metadata_consumer_base = flat(0x48);
    capture.metadata_consumer_count = flat(0x49);
    capture.metadata_consumer_descriptors = std::move(consumer_descriptors);
    capture.metadata_consumer_flattened.assign(info.flattened_ud_buf.begin(),
                                               info.flattened_ud_buf.end());
    capture.metadata_consumer_counts_pre = std::move(consumer_counts);
    capture.metadata_consumer_records_pre = std::move(consumer_records);
    capture.metadata_consumer_pre_valid = consumer_pre_valid;
    LOG_WARNING(
        Render_Vulkan,
        "Dreams A3 focus provenance reset sequence={} dims={}x{}x{} base={} count={} "
        "producer_sequence={} producer_post_valid={} consumer_pre_valid={}",
        g_compute_dispatch_sequence, capture.metadata_consumer_dims[0],
        capture.metadata_consumer_dims[1], capture.metadata_consumer_dims[2],
        capture.metadata_consumer_base, capture.metadata_consumer_count,
        capture.metadata_producer_sequence, capture.metadata_producer_post_valid,
        capture.metadata_consumer_pre_valid);
}

static void CaptureDreamsMetadataProducerPostIfRequested(
    const Shader::Info& info, Scheduler& scheduler, Core::MemoryManager* memory,
    VideoCore::BufferCache& buffer_cache) {
    auto& capture = g_dreams_ordered_chain_capture;
    if (info.pgm_hash == DreamsMetadataTableProducerShader &&
        capture.metadata_producer_armed &&
        capture.metadata_producer_sequence == g_compute_dispatch_sequence) {
        scheduler.Finish();
        const bool producer_counts_valid = SnapshotDreamsBufferWords(
            info, 0, memory, buffer_cache, capture.metadata_producer_counts_post);
        const bool producer_records_valid = SnapshotDreamsBufferWords(
            info, 2, memory, buffer_cache, capture.metadata_producer_records_post);
        capture.metadata_producer_post_valid = producer_counts_valid && producer_records_valid;
        capture.metadata_producer_armed = false;
        LOG_WARNING(
            Render_Vulkan,
            "Dreams metadata producer post sequence={} valid={} count_words={} record_words={}",
            g_compute_dispatch_sequence, capture.metadata_producer_post_valid,
            capture.metadata_producer_counts_post.size(),
            capture.metadata_producer_records_post.size());
        return;
    }

    if (info.pgm_hash != DreamsPackedPositionProducerShader ||
        !capture.metadata_consumer_armed ||
        capture.metadata_consumer_sequence != g_compute_dispatch_sequence) {
        return;
    }
    scheduler.Finish();
    capture.metadata_consumer_armed = false;
    namespace Provenance = Shader::DreamsCompat::B1WriterProvenance;
    auto* gds = buffer_cache.GetGdsBuffer();
    constexpr u64 focus_offset = static_cast<u64>(Provenance::BaseDword) * sizeof(u32);
    constexpr u64 focus_size = static_cast<u64>(Provenance::HeaderDwords) * sizeof(u32);
    if (focus_offset + focus_size > gds->SizeBytes() ||
        focus_offset + focus_size > gds->mapped_data.size()) {
        FailDreamsOrderedChainCapture("A3 focus trace header is outside private GDS after dispatch");
        return;
    }
    gds->InvalidateMappedRange(focus_offset, focus_size);
    const auto* focus_words =
        reinterpret_cast<const u32*>(gds->mapped_data.data() + focus_offset);
    const auto focus_word = [&](u32 absolute_dword) {
        return focus_words[absolute_dword - Provenance::BaseDword];
    };
    const u32 focus_invocations = focus_word(Provenance::FocusInvocationCountDword);
    bool contains_focus_row{};
    for (const u32 position : capture.metadata_focus_row_positions) {
        contains_focus_row |= position >= capture.metadata_consumer_base &&
                              u64{position} < u64{capture.metadata_consumer_base} +
                                                  capture.metadata_consumer_count;
    }
    capture.metadata_consumer_attempts.push_back({
        .sequence = capture.metadata_consumer_sequence,
        .dims = capture.metadata_consumer_dims,
        .base = capture.metadata_consumer_base,
        .count = capture.metadata_consumer_count,
        .focus_invocations = focus_invocations,
        .focus_seen_mask = focus_word(Provenance::FocusSeenMaskDword),
        .contains_focus_row = contains_focus_row,
        .consumer_pre_valid = capture.metadata_consumer_pre_valid,
    });
    if (focus_invocations != 0 && capture.metadata_focus_header.empty()) {
        capture.metadata_focus_header.assign(focus_words,
                                             focus_words + Provenance::HeaderDwords);
    }
    const u64 producer_end =
        u64{capture.metadata_producer_base} + capture.metadata_producer_count;
    bool contiguous_prefix = !capture.metadata_consumer_attempts.empty();
    u64 next_base{};
    for (const auto& attempt : capture.metadata_consumer_attempts) {
        contiguous_prefix &= attempt.base == next_base;
        next_base = u64{attempt.base} + attempt.count;
    }
    const bool exact_target_root = capture.metadata_producer_count != 0 &&
                                   !capture.metadata_focus_row_positions.empty() &&
                                   capture.metadata_consumer_base ==
                                       capture.metadata_producer_base &&
                                   capture.metadata_consumer_count ==
                                       capture.metadata_producer_count &&
                                   contiguous_prefix && next_base == producer_end;
    if (!exact_target_root) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams A3 epoch continuing attempt={} sequence={} base={} count={} "
                    "contains_focus_row={} focus_invocations={} target_rows={} "
                    "contiguous_prefix={} next_base={} root_position={}",
                    capture.metadata_consumer_attempts.size(),
                    capture.metadata_consumer_sequence, capture.metadata_consumer_base,
                    capture.metadata_consumer_count, contains_focus_row, focus_invocations,
                    capture.metadata_focus_row_positions.size(), contiguous_prefix, next_base,
                    producer_end != 0 ? producer_end - 1 : 0);
        capture.a3_focus_header_cleared = false;
        return;
    }
    if (!FinalizeDreamsMetadataCapture(gds)) {
        capture.a3_focus_header_cleared = false;
        capture.metadata_consumer_sequence = 0;
        capture.metadata_consumer_pre_valid = false;
        capture.metadata_consumer_descriptors.clear();
        capture.metadata_consumer_flattened.clear();
        capture.metadata_consumer_counts_pre.clear();
        capture.metadata_consumer_records_pre.clear();
    }
}

static void ApplyDreamsDccBdaPrewarm(const GraphicsPipeline* pipeline, Core::MemoryManager* memory,
                                     VideoCore::BufferCache& buffer_cache) {
    if (!PrewarmDreamsDccBdaConstants()) {
        return;
    }

    const Shader::Info* fragment_info{};
    for (const auto* shader : pipeline->GetStages()) {
        if (shader != nullptr && shader->l_stage == Shader::LogicalStage::Fragment) {
            fragment_info = shader;
            break;
        }
    }
    if (fragment_info == nullptr || fragment_info->pgm_hash != DreamsFleckFragmentShader) {
        return;
    }

    constexpr VAddr GuestAddressLimit = VAddr{1} << 48;
    constexpr u64 ConstantBlockSize = 16;
    const bool has_user_data = fragment_info->user_data.size() >= 5;
    VAddr root_base{};
    u32 selector{};
    u64 block_offset{};
    VAddr constant_address{};
    bool address_in_range{};
    bool mapped{};
    bool registered_before{};
    bool registered_after{};
    bool gpu_modified{};
    VideoCore::BufferId buffer_id{};
    std::array<u32, ConstantBlockSize / sizeof(u32)> words{};

    if (has_user_data) {
        root_base =
            (VAddr{fragment_info->user_data[0]} | (VAddr{fragment_info->user_data[1]} << 32)) &
            (GuestAddressLimit - 1);
        selector = fragment_info->user_data[4];
        block_offset = u64{selector} * ConstantBlockSize;
        address_in_range = root_base != 0 && block_offset <= GuestAddressLimit - root_base &&
                           ConstantBlockSize <= GuestAddressLimit - (root_base + block_offset);
        if (address_in_range) {
            constant_address = root_base + block_offset;
            mapped = memory->IsValidMapping(constant_address, ConstantBlockSize);
        }
        if (mapped) {
            registered_before =
                buffer_cache.IsRegionRegistered(constant_address, ConstantBlockSize);
            gpu_modified = buffer_cache.IsRegionGpuModified(constant_address, ConstantBlockSize);
            // Dynamic ReadConst has no ordinary descriptor to register this guest page. Register
            // and synchronize it before BindResources builds the shader's BDA page table.
            buffer_id = buffer_cache.FindBuffer(constant_address, ConstantBlockSize);
            buffer_cache.SynchronizeBuffersInRange(constant_address, ConstantBlockSize);
            registered_after = buffer_cache.IsRegionRegistered(constant_address, ConstantBlockSize);
            std::memcpy(words.data(), std::bit_cast<const void*>(constant_address),
                        ConstantBlockSize);
        }
    }

    static u32 log_count{};
    if (log_count < 32) {
        LOG_WARNING(Render_Vulkan,
                    "Dreams dcc BDA prewarm #{} root={:#x} selector={} address={:#x}+{:#x} "
                    "userdata={} in_range={} mapped={} registered_before={} registered_after={} "
                    "gpu_modified={} buffer_id={} words={:#010x},{:#010x},{:#010x},{:#010x}",
                    ++log_count, root_base, selector, constant_address, ConstantBlockSize,
                    has_user_data, address_in_range, mapped, registered_before, registered_after,
                    gpu_modified, buffer_id.index, words[0], words[1], words[2], words[3]);
    }
}

static void ApplyDreamsCe3BdaPrewarm(const GraphicsPipeline* pipeline, Core::MemoryManager* memory,
                                     VideoCore::BufferCache& buffer_cache) {
    if (Shader::DreamsCompat::CaptureCe3ReadConst() || !PrewarmDreamsCe3BdaConstants()) {
        return;
    }

    const Shader::Info* fragment_info{};
    for (const auto* shader : pipeline->GetStages()) {
        if (shader != nullptr && shader->l_stage == Shader::LogicalStage::Fragment) {
            fragment_info = shader;
            break;
        }
    }
    if (fragment_info == nullptr || fragment_info->pgm_hash != DreamsSculptFragmentShader) {
        return;
    }

    // ce3b8413 dynamically reads four dwords from
    // (SGPR1:SGPR0 & ((1 << 48) - 1)) + SGPR2 * 16 + 96. Because that address is
    // not represented by an ordinary descriptor, publish and synchronize the exact range before
    // BindResources builds the BDA page table for this draw.
    constexpr VAddr GuestAddressLimit = VAddr{1} << 48;
    constexpr u64 ConstantBlockSize = 16;
    constexpr u64 ConstantBlockBias = 96;
    const bool has_user_data = fragment_info->user_data.size() >= 3;
    VAddr root_base{};
    u32 selector{};
    u64 block_offset{};
    VAddr constant_address{};
    bool address_in_range{};
    bool mapped{};
    bool registered_before{};
    bool registered_after{};
    bool gpu_modified{};
    VideoCore::BufferId buffer_id{};
    std::array<u32, ConstantBlockSize / sizeof(u32)> words{};

    if (has_user_data) {
        root_base =
            (VAddr{fragment_info->user_data[0]} | (VAddr{fragment_info->user_data[1]} << 32)) &
            (GuestAddressLimit - 1);
        selector = fragment_info->user_data[2];
        block_offset = u64{selector} * ConstantBlockSize + ConstantBlockBias;
        address_in_range = root_base != 0 && block_offset <= GuestAddressLimit - root_base &&
                           ConstantBlockSize <= GuestAddressLimit - (root_base + block_offset);
        if (address_in_range) {
            constant_address = root_base + block_offset;
            mapped = memory->IsValidMapping(constant_address, ConstantBlockSize);
        }
        if (mapped) {
            registered_before =
                buffer_cache.IsRegionRegistered(constant_address, ConstantBlockSize);
            gpu_modified = buffer_cache.IsRegionGpuModified(constant_address, ConstantBlockSize);
            buffer_id = buffer_cache.FindBuffer(constant_address, ConstantBlockSize);
            buffer_cache.SynchronizeBuffersInRange(constant_address, ConstantBlockSize);
            registered_after = buffer_cache.IsRegionRegistered(constant_address, ConstantBlockSize);
            std::memcpy(words.data(), std::bit_cast<const void*>(constant_address),
                        ConstantBlockSize);
        }
    }

    static u32 log_count{};
    static VAddr last_address = ~VAddr{};
    if (log_count == 0 || (log_count < 32 && constant_address != last_address)) {
        last_address = constant_address;
        LOG_WARNING(Render_Vulkan,
                    "Dreams ce3 BDA prewarm #{} root={:#x} selector={} address={:#x}+{:#x} "
                    "userdata={} in_range={} mapped={} registered_before={} registered_after={} "
                    "gpu_modified={} buffer_id={} words={:#010x},{:#010x},{:#010x},{:#010x}",
                    ++log_count, root_base, selector, constant_address, ConstantBlockSize,
                    has_user_data, address_in_range, mapped, registered_before, registered_after,
                    gpu_modified, buffer_id.index, words[0], words[1], words[2], words[3]);
    }
}

static bool ApplyDreamsCe3SrtRefresh(const GraphicsPipeline* pipeline, Core::MemoryManager* memory,
                                     VideoCore::BufferCache& buffer_cache) {
    if (Shader::DreamsCompat::CaptureCe3ReadConst() || !RefreshDreamsCe3SrtDescriptors()) {
        return false;
    }

    const Shader::Info* fragment_info{};
    for (const auto* shader : pipeline->GetStages()) {
        if (shader != nullptr && shader->l_stage == Shader::LogicalStage::Fragment) {
            fragment_info = shader;
            break;
        }
    }
    if (fragment_info == nullptr || fragment_info->pgm_hash != DreamsSculptFragmentShader ||
        fragment_info->user_data.size() < 2) {
        return false;
    }

    constexpr VAddr GuestAddressMask = (VAddr{1} << 48) - 1;
    constexpr u64 ImageDescriptorOffset = 0x20;
    constexpr u64 ImageDescriptorSize = 0x40;
    constexpr u64 SamplerDescriptorOffset = 0xA0;
    constexpr u64 SamplerDescriptorSize = 0x0C;
    constexpr u32 FlatImageWord = 0x40 / sizeof(u32);
    constexpr u32 FlatSamplerWord = 0x80 / sizeof(u32);
    constexpr u32 ImageWords = ImageDescriptorSize / sizeof(u32);
    constexpr u32 SamplerWords = SamplerDescriptorSize / sizeof(u32);
    constexpr u32 CapturedWords = ImageWords + SamplerWords;

    const VAddr root =
        (VAddr{fragment_info->user_data[0]} | (VAddr{fragment_info->user_data[1]} << 32)) &
        GuestAddressMask;
    const VAddr image_address = root + ImageDescriptorOffset;
    const VAddr sampler_address = root + SamplerDescriptorOffset;
    const bool image_mapped =
        root != 0 && memory->IsValidMapping(image_address, ImageDescriptorSize);
    const bool sampler_mapped =
        root != 0 && memory->IsValidMapping(sampler_address, SamplerDescriptorSize);
    const bool image_gpu_modified =
        image_mapped && buffer_cache.IsRegionGpuModified(image_address, ImageDescriptorSize);
    const bool sampler_gpu_modified =
        sampler_mapped && buffer_cache.IsRegionGpuModified(sampler_address, SamplerDescriptorSize);

    const auto capture_guest = [&] {
        std::array<u32, CapturedWords> words{};
        if (image_mapped) {
            std::memcpy(words.data(), std::bit_cast<const void*>(image_address),
                        ImageDescriptorSize);
        }
        if (sampler_mapped) {
            std::memcpy(words.data() + ImageWords, std::bit_cast<const void*>(sampler_address),
                        SamplerDescriptorSize);
        }
        return words;
    };
    const auto capture_flat = [](const Shader::Info& info) {
        std::array<u32, CapturedWords> words{};
        if (info.flattened_ud_buf.size() >= FlatSamplerWord + SamplerWords) {
            std::copy_n(info.flattened_ud_buf.begin() + FlatImageWord, ImageWords, words.begin());
            std::copy_n(info.flattened_ud_buf.begin() + FlatSamplerWord, SamplerWords,
                        words.begin() + ImageWords);
        }
        return words;
    };

    const auto guest_before = capture_guest();
    const auto flat_before = capture_flat(*fragment_info);
    bool refreshed{};
    if (image_gpu_modified) {
        buffer_cache.ReadMemory(image_address, ImageDescriptorSize);
        refreshed = true;
    }
    if (sampler_gpu_modified) {
        buffer_cache.ReadMemory(sampler_address, SamplerDescriptorSize);
        refreshed = true;
    }
    if (refreshed) {
        const_cast<Shader::Info&>(*fragment_info).RefreshFlatBuf();
    }

    const auto guest_after = capture_guest();
    const auto flat_after = capture_flat(*fragment_info);
    const u32 readback_changes =
        static_cast<u32>(std::ranges::count_if(std::views::iota(0U, CapturedWords), [&](u32 index) {
            return guest_before[index] != guest_after[index];
        }));
    const u32 flat_mismatches =
        static_cast<u32>(std::ranges::count_if(std::views::iota(0U, CapturedWords), [&](u32 index) {
            return guest_after[index] != flat_after[index];
        }));

    static std::unordered_map<VAddr, std::array<u32, CapturedWords>> last_by_root;
    const auto [last, is_new_root] = last_by_root.try_emplace(root, guest_after);
    const bool descriptor_changed = !is_new_root && last->second != guest_after;
    last->second = guest_after;
    static u32 log_count{};
    if (log_count < 96 && (is_new_root || descriptor_changed || refreshed)) {
        std::array<u64, ImageDescriptorSize / sizeof(u64)> image_raw{};
        std::memcpy(image_raw.data(), guest_after.data(), ImageDescriptorSize);
        LOG_WARNING(Render_Vulkan,
                    "Dreams ce3 SRT refresh #{} root={:#x} image={:#x}+{:#x} sampler={:#x}+{:#x} "
                    "mapped={},{} gpu_modified={},{} refreshed={} readback_changes={} "
                    "flat_mismatches={} descriptor_changed={}",
                    ++log_count, root, image_address, ImageDescriptorSize, sampler_address,
                    SamplerDescriptorSize, image_mapped, sampler_mapped, image_gpu_modified,
                    sampler_gpu_modified, refreshed, readback_changes, flat_mismatches,
                    descriptor_changed);
        LOG_WARNING(Render_Vulkan,
                    "Dreams ce3 SRT data root={:#x} images={:#018x},{:#018x},{:#018x},{:#018x},"
                    "{:#018x},{:#018x},{:#018x},{:#018x} sampler={:#010x},{:#010x},{:#010x}",
                    root, image_raw[0], image_raw[1], image_raw[2], image_raw[3], image_raw[4],
                    image_raw[5], image_raw[6], image_raw[7], guest_after[ImageWords],
                    guest_after[ImageWords + 1], guest_after[ImageWords + 2]);
    }
    return refreshed;
}

static bool TraceDreamsFleckRendering() {
    static bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_FLECK_TRACE");
        return value != nullptr && std::string_view{value} == "1";
    }();
    if (!enabled) {
        const char* trigger_file = std::getenv("SHADPS4_DREAMS_FLECK_TRACE_TRIGGER_FILE");
        if (trigger_file != nullptr && trigger_file[0] != '\0') {
            std::error_code error;
            if (std::filesystem::remove(trigger_file, error)) {
                enabled = true;
                LOG_WARNING(Render_Vulkan, "Dreams fleck trace armed from trigger file");
            }
        }
    }
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static bool TraceDreamsTemporalImages() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_TEMPORAL_IMAGE_TRACE");
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static u32 DreamsTemporalImageTraceLimit() {
    static const u32 limit = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_TEMPORAL_IMAGE_TRACE_LIMIT");
        if (value == nullptr || value[0] == '\0') {
            return 16U;
        }
        char* end{};
        const u64 parsed = std::strtoull(value, &end, 10);
        return end != value ? static_cast<u32>(std::clamp<u64>(parsed, 2, 32)) : 16U;
    }();
    return limit;
}

static u32 g_dreams_temporal_image_trace_remaining{};
static u32 g_dreams_temporal_image_trace_ordinal{};
static bool g_dreams_temporal_image_trace_initialized{};

static bool ConsumeDreamsTemporalImageTraceRequest() {
    if (!TraceDreamsTemporalImages()) {
        return false;
    }

    const char* trigger_file = std::getenv("SHADPS4_DREAMS_TEMPORAL_IMAGE_TRACE_TRIGGER_FILE");
    if (trigger_file != nullptr && trigger_file[0] != '\0') {
        std::error_code error;
        if (std::filesystem::remove(trigger_file, error)) {
            g_dreams_temporal_image_trace_remaining = DreamsTemporalImageTraceLimit();
            LOG_WARNING(Render_Vulkan, "Dreams temporal image trace armed for {} dispatches",
                        g_dreams_temporal_image_trace_remaining);
        }
    } else if (!g_dreams_temporal_image_trace_initialized) {
        g_dreams_temporal_image_trace_initialized = true;
        g_dreams_temporal_image_trace_remaining = DreamsTemporalImageTraceLimit();
        LOG_WARNING(Render_Vulkan, "Dreams temporal image trace auto-armed for {} dispatches",
                    g_dreams_temporal_image_trace_remaining);
    }

    if (g_dreams_temporal_image_trace_remaining == 0) {
        return false;
    }
    --g_dreams_temporal_image_trace_remaining;
    return true;
}

struct DreamsTemporalContentImage {
    bool valid{};
    bool written{};
    u32 binding{};
    u32 array_size{};
    VideoCore::ImageId image_id{};
    u64 image_uid{};
    VAddr descriptor_base{};
    u32 descriptor_width{};
    u32 descriptor_height{};
    u32 descriptor_depth{};
    u32 descriptor_pitch{};
    VAddr guest_base{};
    u64 guest_size{};
    u32 cached_width{};
    u32 cached_height{};
    u32 cached_depth{};
    u32 cached_pitch{};
    u32 bits{};
    u32 image_format{};
    u32 tile_mode{};
    u32 view_format{};
    u32 base_level{};
    u32 levels{};
    u32 base_layer{};
    u32 layers{};
    u64 linear_size{};
    u32 flattened_index{};
};

struct DreamsTemporalContentChainKey {
    VAddr image_a{};
    VAddr image_b{};
    u32 width{};
    u32 height{};
    u32 pitch{};

    bool operator==(const DreamsTemporalContentChainKey&) const = default;
};

struct DreamsTemporalContentChain {
    DreamsTemporalContentChainKey key;
    u32 dispatches{};
};

struct DreamsTemporalContentCaptureState {
    bool active{};
    u32 remaining{};
    u32 ordinal{};
    std::filesystem::path output_dir;
    std::vector<DreamsTemporalContentChain> chains;
};

static DreamsTemporalContentCaptureState g_dreams_temporal_content_capture{};

static bool EnableDreamsTemporalContentCapture() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_TEMPORAL_CONTENT_CAPTURE");
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static u32 DreamsTemporalContentCaptureLimit() {
    static const u32 limit = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_TEMPORAL_CONTENT_CAPTURE_LIMIT");
        if (value == nullptr || value[0] == '\0') {
            return 4U;
        }
        char* end{};
        const u64 parsed = std::strtoull(value, &end, 10);
        return end != value ? static_cast<u32>(std::clamp<u64>(parsed, 4, 8)) : 4U;
    }();
    return limit;
}

static bool BeginDreamsTemporalContentCaptureDispatch() {
    auto& capture = g_dreams_temporal_content_capture;
    if (!EnableDreamsTemporalContentCapture()) {
        return false;
    }

    if (!capture.active) {
        const char* trigger_file =
            std::getenv("SHADPS4_DREAMS_TEMPORAL_CONTENT_CAPTURE_TRIGGER_FILE");
        const char* output_dir = std::getenv("SHADPS4_DREAMS_TEMPORAL_CONTENT_CAPTURE_DIR");
        if (trigger_file == nullptr || trigger_file[0] == '\0' || output_dir == nullptr ||
            output_dir[0] == '\0') {
            return false;
        }
        std::error_code error;
        if (!std::filesystem::remove(trigger_file, error)) {
            return false;
        }

        capture.output_dir = output_dir;
        std::filesystem::create_directories(capture.output_dir, error);
        if (error) {
            LOG_ERROR(Render_Vulkan,
                      "Failed to create Dreams temporal content capture directory {}: {}",
                      capture.output_dir.string(), error.message());
            return false;
        }

        std::ofstream dispatches{capture.output_dir / "dispatches.tsv", std::ios::trunc};
        std::ofstream images{capture.output_dir / "images.tsv", std::ios::trunc};
        if (!dispatches || !images) {
            LOG_ERROR(Render_Vulkan,
                      "Failed to initialize Dreams temporal content capture metadata in {}",
                      capture.output_dir.string());
            return false;
        }
        dispatches << "ordinal\tdispatch_sequence\tchain\tchain_dispatch\tchain_key_a\t"
                      "chain_key_b\tdim_x\tdim_y\tdim_z\tsrt28_flat44_width_max\t"
                      "srt29_flat45_height_max\tsrt30_flat46_uv_scale_x\t"
                      "srt31_flat47_uv_scale_y\tsrt32_flat48_history_weight\n";
        images << "ordinal\tdispatch_sequence\tchain\tphase\trole\tbinding\tarray_size\t"
                  "valid\twritten\timage_id\timage_uid\tdescriptor_base\t"
                  "descriptor_width\tdescriptor_height\tdescriptor_depth\t"
                  "descriptor_pitch\tguest_base\tguest_size\tcached_width\t"
                  "cached_height\tcached_depth\tcached_pitch\tbits\timage_format\t"
                  "tile_mode\tview_format\tbase_level\tlevels\tbase_layer\tlayers\t"
                  "linear_size\tfile\n";

        capture.active = true;
        capture.remaining = DreamsTemporalContentCaptureLimit();
        capture.ordinal = 0;
        capture.chains.clear();
        LOG_WARNING(Render_Vulkan, "Dreams temporal content capture armed for {} dispatches in {}",
                    capture.remaining, capture.output_dir.string());
    }

    return capture.remaining != 0;
}

static std::pair<u32, u32> AssignDreamsTemporalContentChain(
    const std::array<DreamsTemporalContentImage, 4>& images) {
    const auto image_address = [](const DreamsTemporalContentImage& image) {
        return image.valid ? image.guest_base : image.descriptor_base;
    };
    const VAddr output = image_address(images[0]);
    const VAddr history = image_address(images[1]);
    const DreamsTemporalContentChainKey key{
        .image_a = std::min(output, history),
        .image_b = std::max(output, history),
        .width = images[0].descriptor_width,
        .height = images[0].descriptor_height,
        .pitch = images[0].descriptor_pitch,
    };
    auto& chains = g_dreams_temporal_content_capture.chains;
    auto chain = std::ranges::find(chains, key, &DreamsTemporalContentChain::key);
    if (chain == chains.end()) {
        chain = chains.insert(chains.end(), {.key = key});
    }
    return {static_cast<u32>(std::distance(chains.begin(), chain)) + 1, ++chain->dispatches};
}

static void WriteDreamsTemporalContentImageMetadata(u32 ordinal, u64 dispatch_sequence, u32 chain,
                                                    std::string_view phase, std::string_view role,
                                                    const DreamsTemporalContentImage& image,
                                                    const std::filesystem::path& filename) {
    std::ofstream stream{g_dreams_temporal_content_capture.output_dir / "images.tsv",
                         std::ios::app};
    stream << ordinal << '\t' << dispatch_sequence << '\t' << chain << '\t' << phase << '\t' << role
           << '\t' << image.binding << '\t' << image.array_size << '\t' << image.valid << '\t'
           << image.written << '\t' << image.image_id.index << '\t' << image.image_uid << '\t'
           << image.descriptor_base << '\t' << image.descriptor_width << '\t'
           << image.descriptor_height << '\t' << image.descriptor_depth << '\t'
           << image.descriptor_pitch << '\t' << image.guest_base << '\t' << image.guest_size << '\t'
           << image.cached_width << '\t' << image.cached_height << '\t' << image.cached_depth
           << '\t' << image.cached_pitch << '\t' << image.bits << '\t' << image.image_format << '\t'
           << image.tile_mode << '\t' << image.view_format << '\t' << image.base_level << '\t'
           << image.levels << '\t' << image.base_layer << '\t' << image.layers << '\t'
           << image.linear_size << '\t' << filename.filename().string() << '\n';
}

static void FinishDreamsTemporalContentCaptureDispatch() {
    auto& capture = g_dreams_temporal_content_capture;
    if (capture.remaining != 0) {
        --capture.remaining;
    }
    if (capture.remaining == 0) {
        capture.active = false;
        LOG_WARNING(Render_Vulkan, "Dreams temporal content capture complete: {}",
                    capture.output_dir.string());
    }
}

static bool ForceDreamsStorageDependencies() {
    static const bool enabled = [] {
        const char* value = std::getenv("SHADPS4_DREAMS_FORCE_STORAGE_BARRIERS");
        return value != nullptr && std::string_view{value} == "1";
    }();
    return enabled && Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static bool NeedsDreamsStorageDependency(u64 shader_hash, u32 descriptor_index, bool is_written) {
    if (!is_written) {
        return false;
    }
    if (ForceDreamsStorageDependencies()) {
        return true;
    }
    const bool indirect_args_counts =
        shader_hash == Shader::DreamsCompat::IndirectArgsShader && descriptor_index == 0;
    const bool sculpt_volume_input =
        shader_hash == Shader::DreamsCompat::SculptVolumeWriterShader && descriptor_index == 0;
    const bool traversal_child_queue =
        shader_hash == Shader::DreamsCompat::TraversalShader && descriptor_index == 6;
    const bool queue_producer_alt_child_queue =
        shader_hash == Shader::DreamsCompat::QueueProducerShaderAlt && descriptor_index == 2;
    if (!indirect_args_counts && !sculpt_volume_input && !traversal_child_queue &&
        !queue_producer_alt_child_queue) {
        return false;
    }
    // 902 consumes counts written by its preceding compute producer. 84aa likewise consumes the
    // voxel stream written by 7ba4de5d. B535 refines its child queue across consecutive dispatches
    // through descriptor 6, and 692 repeats that recursion through descriptor 2. These resources
    // remain classified as writable storage at the same stage, so normal state-transition tracking
    // can elide the required write-to-read dependency.
    return Common::ElfInfo::Instance().GameSerial() == "CUSA04301";
}

static std::optional<std::filesystem::path> ConsumeDreamsFleckDumpRequest() {
    if (Common::ElfInfo::Instance().GameSerial() != "CUSA04301") {
        return std::nullopt;
    }
    const char* trigger_file = std::getenv("SHADPS4_DREAMS_FLECK_DUMP_TRIGGER_FILE");
    const char* output_dir = std::getenv("SHADPS4_DREAMS_FLECK_DUMP_DIR");
    if (trigger_file == nullptr || trigger_file[0] == '\0' || output_dir == nullptr ||
        output_dir[0] == '\0') {
        return std::nullopt;
    }

    std::error_code error;
    if (!std::filesystem::remove(trigger_file, error)) {
        return std::nullopt;
    }
    const std::filesystem::path output{output_dir};
    std::filesystem::create_directories(output, error);
    if (error) {
        LOG_ERROR(Render_Vulkan, "Failed to create Dreams fleck dump directory {}: {}",
                  output.string(), error.message());
        return std::nullopt;
    }
    return output;
}

